COLLDATA("shuabimanur","ur",[[206,"ہمیں خبر دی ہے ابو عبد اللہ حافظ نے کہ ہمیں حدیث بیان کی ہے جعفر بن محمد بن نصیر نے انہوں نے کہا کہ میں نے سنا ابو العباس بن عطاء سے وہ فرماتے تھے۔\nتدبیر کرنے اور پسند کے پیچھے پڑنے کو چھوڑ دو۔ زندگی میں خوش رہو گے۔ اس لئے کہ تدبیر اور تنگ دلی اور پسند کے درپے رہنا لوگوں پر ان کی زندگی کو مکدر کر دیتا ہے اور مشکل بنا دیتا ہے۔\nحضرت عطاء نے فرمایا کہ ابو العباس سے سوال کیا گیا۔ کہ وہ کون سا مقام ہے کہ بندہ جب اس مقام پر کھڑا ہو تو عبدیت کے مرتبہ پر کھڑا ہو جائے فرمایا کہ ترک تدبیر حضرت عطاء فرماتے ہیں میں نے ابوالعباس سے سنا وہ فرما رہے تھے۔\nسلامتی اس وقت تک نہیں آتی جب تک کہ تم تدبیر کے معاملے میں اہل قبور جیسے نہ ہو جاؤ۔\nاور عطاء فرماتے ہیں میں نے ابوالعباس کو یہ فرماتے ہوئے سنا تھا۔\nہمارے لئے سرور و خوشی اللہ کی تدبیر میں ہے اور محرومی ہماری اپنی تدبیر میں ہے۔\nفائدہ:...... اس لئے کہ بندے کی تدبیر ناقص ہوتی ہے اس لئے ناکامی کا امکان زیادہ کامیابی کا بہت کم ہوتا ہے جب کہ اللہ کی تدبیر مضبوط اور کامیاب ہوتی ہے اس لئے توکل کا اعلیٰ مقام یہی ہے بندہ مکمل اپنے آپ کو اللہ کی تدبیر کے حوالے کر دے از روئے سستی و کاہلی نہیں بلکہ بطور توکل علی اللہ۔ (از مترجم)"],[207,"§بعض علماء کی نصیحت\nہمیں خبر دی ہے ابو عبد اللہ حافظ نے کہ ہمیں حدیث بیان کی ہے ابو عمر زاہد نے انہوں نے کہا ہمیں حدیث بیان کی ہے ابوالعباس محمد بن علی انصاری نے کہ ہمیں حدیث بیان کی ہے ہمارے والد نے انہوں نے کہا میں نے سنا سفیان ابن عیینہ سے کہتے تھے کہ علماء فرماتے تھے۔ جو شخص اللہ کی تقدیر پر قناعت نہیں کرتا وہ اپنے نفس کی تدبیر پر بھی قناعت نہیں کر سکتا۔"],[208,"ہمیں خبر دی ہے ابو عبد الرحمن سلمی نے اس نے سنا عبد اللہ بن محمد بن عبد الرحمن رازی سے وہ فرماتے تھے کہ میں نے سنا ابو العباس احمد بن محمد بن مسروق طوسی سے وہ فرماتے تھے۔ جو شخص تدبیر (کا سہارا کرنا) چھوڑ دے (بلکہ اللہ کا سہارا کرے) وہ راحت وسکون کی زندگی گذارتا ہے۔ مسروق کہتے ہیں میں نے سنا ابوالعباس سے وہ کہتے تھے کہ میں نے سنا ابوالحسین فارسی سے کہتے تھے کہ میں نے سنا عباس بن عاصم سے وہ کہتے تھے میں نے سنا سہل سے وہ کہتے تھے۔ آزمائش اور پریشانی اللہ کی طرف سے دو طرح کی ہوتی ہے یا تو بطور رحمت کے یا بطور سزا کے بطور رحمت وہ ہوتی ہے جو انسان کو ترک تدبیر پر اور اللہ تعالیٰ کی بارگاہ میں فقر وفاقہ کے اظہار پر ابھارتی ہے اور بطور سزا وہ ہوتی ہے جو انسان کو اپنی پسند اپنی مرضی کرنے اور اپنی تدبیر کرنے پر اکساتی ہے۔ (1)","",{"k":"(1) أخرجه أبو نعيم في الحلية ۱۹۶/۱۰ قال أبو نعيم سمعت أبي يقول سمعت أبا بكر يقول سمعت سهل بن عبد الله يقول فذكره."}],[209,"§جب فقر مقدر ہو تو غذا نہیں آتا\nہمیں حدیث بیان کی ہے عبداللہ بن یوسف اصبہانی نے انہوں نے کہا ہمیں بات بتائی ہے ابوسعید بن اعرابی نے انہوں نے کہا ہمیں حدیث بتائی ہے محمد بن اسماعیل اصبہانی نے وہ کہتے ہیں کہ میں نے ابو تراب سے سنا وہ فرماتے تھے میں نے حاتم سے سنا کہتے تھے میں نے شفیق سے سنا وہ کہتے تھے۔ اے فقیر (یعنی اللہ کا فقیر) دنیا میں مشغول نہ ہو۔ اور غنا کی تلاش میں مشقت نہ اٹھا اس لئے کہ جب فقر تیرے لئے مقدر ہو چکا ہے تو تو غنی نہیں ہو سکے گا۔ (1)","",{"k":"(1) وفى الأصل والمطبوعة على (اظهاره قدرة) وهو خطأ والصحيح (على إظهار فقره وفاقته) كما في الحلية شقيق هو أبو على البلخي."}],[210,"ہمیں خبر دی ہے ابوالحسین بن فضل قطان نے انہوں نے کہا ہمیں بات بتائی ہے عبداللہ بن جعفر نے اس نے کہا ہمیں بات بیان کی ہے یعقوب بن سفیان نے انہوں نے کہا ہمیں بات بتائی ہے سلیمان بن حرب نے انہوں نے کہا ہمیں حدیث بتائی ہے حماد نے وہ کہتے ہیں کہ ایوب نے کہا۔ جو کچھ تو ارادہ کرتا ہے جب وہ نہیں ہوا تو پھر تو بھی وہی ارادہ کر جو خود ہوگا۔ (1)","",{"k":"(1) أيوب هو أيوب بن كيسان السختياني."}],[211,"ہمیں خبر دی ہے ابو عبد الرحمن سلمی رحمۃ اللہ علیہ نے کہ ہمیں بات بتائی ہے محمد بن احمد بن سعید رازی نے کہ بات بتائی ہے ہمیں عباس بن حمزہ نے انہوں نے کہا ہمیں حدیث بتائی ہے احمد بن ابو حواری نے سفیان سے اللہ تعالیٰ کے اس قول کے بارے میں۔\n﴿ ومن يؤمن بالله يهد قلبه ﴾ [تغابن ۱۱]\n’’جو شخص اللہ کے ساتھ ایمان لے آئے اللہ اس کے دل کو رہنمائی کرتا ہے۔‘‘ فرمایا کہ رہنمائی فرماتا ہے تسلیم و رضاء کے ساتھ۔ (1)","",{"k":"(1) أحمد بن أبى الحوارى هو أحمد بن عبد الله بن ميمون بن العباس بن الحارس التغلبي الحسن بن أبى الحوارى ثقة زاهد"}],[212,"ہمیں خبر دی ہے ابو عبد الرحمن سلمی نے اس نے کہا میں نے سنا علی بن احمد بن عبد العزیز قزوینی سے اس نے کہا میں نے سنا جعفر سے وہ کہتے ہیں میں نے سنا ابو العباس بن عطاء سے وہ کہتے تھے کہ رضا اللہ تعالیٰ کی مخالفت ترک کرنے کو کہتے ہیں ان امور کے اندر جو کچھ وہ بندے پر جاری کرے۔"],[213,"§عمر بن عبد العزیز کی جامع دعا\nہمیں خبر دی ہے ابو نصر عمر بن قتادہ نے انہوں نے کہا ہمیں بات بیان کی ہے ابو العباس محمد بن الحق صبغی نے اس نے کہا ہمیں بات بتائی ہے حسن بن علی بن زیادہ نے کہ بات بتائی ہے ہمیں اسحاق مروی نے اس نے کہا ہمیں بات بتائی ہے مالک نے یحییٰ بن سعید نے کہ عمر بن عبد العزیز نے فرمایا۔ مجھے ان دعاؤں نے چھوڑ دیا ہے مجھے تمام امور میں کوئی دلچسپی نہیں (یعنی تمام امور کی دعا کی بجائے ایک جامع دعا کرتا ہوں) میں چاہتا ہوں کہ اللہ کی تقدیر کی جگہ ہو جاؤں۔ (اس لئے کہ وہ) یہ دعا کرتے تھے۔ اے اللہ مجھے اپنی قضاء اور فیصلے کے ساتھ راضی رکھ اپنی تقدیر میں میرے لئے برکت عطا فرما یہاں تک کہ تو جس چیز کو مؤخر کر دے میں اس کی جلدی پسند نہ کروں اور جس چیز کو تو جلدی دے میں اس کی تاخیر پسند نہ کروں۔\nیونس بن عبید کا ارشاد:"],[214,"ہمیں خبر دی ہے ابو زکریا بن ابو الحق نے کہ ہمیں بات بتائی ہے ابوالحسن احمد بن حسین بن یزید قزوینی نے مقام رائے میں کہ ہمیں بات بتائی ہے محمد بن ایوب بن یحییٰ نے انہوں نے کہا خبر دی ہے سلیمان عتکی نے کہ ہمیں حدیث بتائی ہے حماد نے کہ ہمیں حدیث بیان کی ہے یحییٰ بن سعید نے اس نے کہا میں نے سنا تھا عمر بن عبد العزیز سے وہ کہتے ہیں۔\nکہ مجھے اللہ کی قضا اور فیصلے کے سوا کوئی خواہش نہیں ہوئی۔"],[215,"ہمیں خبر دی ہے ابو الحسین بن بشران نے کہ خبر دی ہے اسماعیل بن محمد صفار نے کہ ہمیں بات بیان کی ہے عباس بن محمد نے کہ ہمیں بات بتائی ہے یحییٰ بن معین نے کہ ہمیں بات بتائی ہے حجاج نے شعبہ سے اس نے کہا کہ مجھے یونس بن عبید نے کہا تھا۔ ’’کہ میں نے کبھی کسی چیز کی تمنا اور آرزو ہی نہیں کی۔‘‘\nحضرت فضیل بن عیاض کا ارشاد:"],[216,"ہمیں خبر دی ہے ابو حازم حافظ نے کہ خبر دی ہے ہمیں محمد بن احمد بن سنان نے کہ ہمیں بات بیان کی ہے ہیثم بن خلف نے کہ ہمیں بات بتائی ہے محمد بن علی بن حسن نے وہ کہتے ہیں میں نے ابراہیم اشعث سے سنا وہ کہتے تھے کہ میں نے فضیل بن عیاض سے سنا وہ کہتے تھے اپنے مرتبے اور مقام سے اوپر راضی ہونے والا یا راضی ہوتا کوئی چیز نہیں ہے۔\nحضرت ذوالنون مصری کا ارشاد:"],[217,"ہمیں خبر دی ہے ابو عبد اللہ حافظ نے کہ ہمیں بات بتائی ہے حسن بن محمد بن الحق نے انہوں نے کہا میں نے سنا ابو عثمان خیاط سے وہ کہتے ہیں کہ میں نے سنا ذوالنون مصری سے وہ کہتے تھے۔\n❶...... تسلیم و رضا کی (یعنی اپنے آپ کو اللہ کے سپرد کرنے اللہ کے فیصلے پر راضی ہونے) کی تین علامات ہیں۔ قضاء کے مقابلے میں رضاء۔ آزمائش پر صبر کرنا۔ خوشحالی پر شکر کرنا۔\n❷...... اور تفویض کرنے اور اللہ کے سپرد کرنے کی تین علامات ہیں۔ ترک حکم اللہ کے فیصلوں میں اور اس کے اندازوں میں ایک وقت سے دوسرے وقت کی طرف۔ اور اپنے ارادے کو اللہ کے ارادے کے لئے معطل کرنا نوافل میں اور دنیا کے اسباب میں۔ اور اس بات پر نظر رکھنا کہ اس بارے میں اللہ کی تدبیر کیا واقع ہوتی ہے۔\n❸...... دل روشن یا روشن ضمیر ہونے کی علامات تین ہیں۔ ہر چیز کو اللہ طرف سے دیکھنا۔ ہر شے کو اسی سے قبول کرنا۔ ہر شے کی نسبت اسی کی طرف کرنا۔\nابو عبد اللہ نباجی کا ارشاد: (1)","",{"k":"(1) أخرجه أبو نعيم في الحلية (۳۶۲/۹ و ۳۶۳) من طريق سعيد بن عثمان الخياط عن ذى النون الثلاثة الأولى فقط أثناء حديث طويل"}],[218,"ہمیں خبر دی ہے ابو عبد اللہ حافظ نے کہ میں نے سنا ابو احمد حافظ سے وہ کہتے ہیں خبر دی ہے ابو عثمان سعید بن عبد العزیز حلیمی نے انہوں نے کہا ہمیں بات بتائی۔ احمد بن ابی حواری نے وہ کہتے ہیں میں نے سنا ابو عبد اللہ نباجی سے وہ کہتے تھے۔\nعظیم ترین عبادات میرے نزدیک تین ہیں:\n❶...... کہ آپ اللہ کے احکام میں سے کسی حکم کو رد نہ کیجئے۔\n❷...... اللہ کے سوا کسی اور سے کوئی حاجت نہ مانگئے۔\n❸...... اس سے کوئی چیز ذخیرہ نہ کیجئے۔\nمحمد بن احمد بن شمعون کا ارشاد:"],[219,"ہمیں خبر دی ہے ابو عبد الرحمن سلمی نے وہ کہتے ہیں میں نے سنا تھا۔ محمد بن احمد بن شمعون سے جب کہ ان سے رضاء کے بارے پوچھا گیا تھا (کہ اللہ سے راضی ہونے کی کیا حقیقت ہے) انہوں نے جواب دیا۔ (کہ اس کی تین صورتیں ہیں) اللہ کے ساتھ راضی ہونا۔ اللہ سے راضی ہونا اللہ کے لئے راضی ہونا۔ اللہ کے ساتھ راضی ہونا یہ ہے کہ وہی مدبر ہے وہی مختار ہے اور اس سے راضی ہونا یہ ہے کہ وہی تقسیم کرنے والا ہے۔ وہی عطاء کرنے والا ہے اور اس کے لئے رضا یہ ہے کہ وہی الہ ہے وہی رب ہے۔\nابن فرجی کا ارشاد:"],[220,"ہمیں خبر دی ہے ابو عبد الرحمن نے کہ انہوں نے سنا منصور بن عبد اللہ سے وہ کہتے ہیں کہ میں نے سنا عباس بن یوسف شکلی سے وہ کہتے ہیں کہ میں نے سنا ابن فرجی سے وہ کہتے تھے کہ رضا کے مفہوم میں تین اقوال ہیں:\n❶...... اپنی پسند کو ترک کرنا۔\n❷...... قضاء کے گذر سے دل کا سرور۔\n❸...... اپنے نفس سے تدبیر کو ساقط کرنا۔ یہاں تک کہ وہ اس کے خلاف فیصلہ دے۔"],[221,"§’’ابو عثمان بیکندی رحمۃ اللہ علیہ کا ارشاد:‘‘\nہمیں خبر دی ہے ابو عبد الرحمن نے کہ انہوں نے سنا ابو بکر بن شاذان سے کہتے تھے کہ ابو عثمان بیکندی سے رضا کے بارے پوچھا گیا تو انہوں نے فرمایا: جو شخص پشیمان نہ ہو اس پر جو دنیا کے اسباب میں سے اسے حاصل نہ ہو بلکہ اس سے رہ جائے اور نہ ہی اس پر افسوس کرے نہ ہی اس پر افسردہ ہو۔\nسیدنا عبد اللہ بن عباس کی نصیحت:"],[222,"ہمیں خبر دی ہے ابو سعید مالینی نے کہ ہمیں بات بیان کی ہے احمد بن محمد بن حسن نے انہوں نے کہا ہمیں بات بتائی ہے ابو العباس بن حکمویہ رازی نے انہوں نے کہا میں نے سنا تھا یحییٰ بن معاذ رازی سے وہ کہتے تھے۔ اے آدم کے بیٹے اس غیر موجودگی پر افسوس نہ کر جو مر کر بھی تجھے نہ مل سکے اور اس موجودگی پر نہ اترا جب موت تیرے ہاتھوں میں نہ رہنے دے۔"],[223,"ہمیں خبر دی ہے ابو عبد اللہ حافظ نے کہ ہمیں حدیث بیان کی ہے ابو العباس محمد بن یعقوب نے کہ ہمیں حدیث بیان کی ہے احمد بن حازم نے کہ ہمیں حدیث بیان کی ہے عبید اللہ بن موسیٰ نے سفیان سے انہوں نے سماک سے انہوں نے عکرمہ سے انہوں نے سیدنا ابن عباس رضی اللہ عنہ سے اللہ تعالیٰ کے اس ارشاد کے بارے میں:\n﴿ لكيلا تأسوا على ما فاتكم ولا تفرحوا بما آتاكم ﴾ [الحدید ۲۳]\n’’تا آنکہ افسوس نہ کرو تم اس پر جو تم سے رہ جائے اور تا آنکہ نہ اتراؤ اس پر جو کچھ تمہیں وہ دے دے۔‘‘\nسیدنا ابن عباس نے فرمایا کہ ہر انسان خوش بھی ہوتا ہے اور غمگین بھی۔ لیکن مطلب یہ ہے کہ جس وقت اسے مصیبت پہنچے اس کو صبر بنا دے اور اگر اسے خیر و بھلائی ملے تو اس کو شکر بنا دے۔\nامام بیہقی کا قول:\nسیدنا عبد اللہ بن عباس کے قول سے اس آیت کے بارے میں شیخ حلیمی رحمتہ اللہ علیہ کے قول کی تائید ہوتی ہے، وہ فرماتے ہیں کہ جزع و فزع سے مراد ہے زبردستی ناراض ہونا اور گالی گلوچ کرنا ہے اور فرح و خوشی سے مراد اترانا اور اکڑنا ہے۔ (1)","",{"k":"(1) أخرجه الحاكم في المستدرك (۴۷۹/۲) من طريق سفيان به وصححه الحاكم ووافقه الذهبي وعزاه السيوطي في الدر المنثور (۱۸۷/۶) لابن أبي شيبة وعبد بن حميد وابن جرير وابن المنذر والحاكم وصححه والمصنف في الشعب."}],[224,"§حضرت ذوالنون مصری کا تقوے پر مبنی نصیحت آمیز واقعہ\nہمیں خبر دی ہے ابو سعد مالینی نے کہ ہمیں بات بیان کی ہے ابو محمد حسن بن ابوالحسن عسکری نے کہ ہمیں بات بیان کی ہے۔ محمد بن احمد بن عبد العزیز عامری نے کہ مجھے حدیث بیان کی ہے عمر بن صدقہ محال نے انہوں نے فرمایا: کہ میں اثیم شہر میں حضرت ذوالنون مصری سے ساتھ گیا ہوا تھا۔ انہوں نے وہاں پر کھیل کود کی اور ڈھول بجنے اور بڑائی کرنے یا اترانے کی آوازیں سنیں تو پوچھا کہ یہ کیا ماجرا ہے؟ انہیں بتایا گیا ہے کہ یہ شہر کے کسی آدمی کے ہاں شادی ہو رہی ہے اور دوسری جانب انہوں نے رونے چیخنے اور بلبلانے کی آوازیں سنیں تو پوچھا کہ یہ کیا معاملہ ہے؟ انہیں بتایا گیا کہ فلاں شخص کا انتقال ہو گیا ہے۔ تو انہوں نے مجھ سے فرمایا اے عمر بن صدقہ (وہ لوگ جو شادی پر غیر شرعی کام کر رہے ہیں) یہ وہ لوگ ہیں جنہیں اللہ کی نعمتیں عطا کی گئیں ہیں مگر ان کا شکر ادا نہیں کیا۔ (اور یہ دوسرے لوگ جو رو پیٹ رہے ہیں) ابتلاء اور آزمائش میں مبتلاء کئے گئے ہیں مگر انہوں نے صبر نہیں کیا۔ مجھ پر اللہ کی ناراضگی واقع ہوگی اگر میں اس شہر میں رات گزار لوں چنانچہ وہ اسی لمحے شہر اثیم سے شہر فسطاط کی طرف نکل گئے۔ کیونکہ بے صبری اور ناشکری اللہ کی ناراضگی اور بے یاری و بے مددگاری کو لاتے ہیں اور صبر و شکر اللہ رضا اور نصرت کو۔ (از مترجم)"],[225,"§سیدنا علی المرتضیٰ رضی اللہ عنہ کا نماز تہجد میں بارگاہ الہی میں عجز پیش کرنا\nہمیں خبر دی ہے محمد بن عبد اللہ حافظ نے کہ ہمیں بات بیان کی ہے ابو الولید نے کہ ہمیں حدیث بیان کی ہے ابو عبد اللہ بوشنجی نے انہوں نے کہا ہمیں بات بتائی ہے احمد بن حنبل نے انہوں نے کہا ہمیں حدیث بیان کی ہے عبد الرزاق نے اس نے کہا ہمیں خبر دی ہے، معمر نے بشر بن جابان صنعانی سے انہوں نے حجر بن قیس مدری سے انہوں نے کہا کہ میں نے امیر المؤمنین علی بن ابی طالب کے ہاں رات کو قیام کیا وہ رات نماز پڑھ رہے تھے اور زور سے قرآت کر رہے تھے۔ قرآت کے دوران جب وہ اس آیت پر پہنچے:\n﴿ افرأيتم ما تمنون أنتم تخلقونه ام نحن الخالقون ﴾ [الواقعہ ۵۸-۵۹]\n’’بھلا بتلاؤ جو تم شکم مادر میں منی کا قطرہ ڈالتے ہو کیا تم اس سے بچہ پیدا کرتے ہو یا ہم پیدا کرنے والے ہیں۔‘‘\n(سیدنا علی نے یہ پڑھنے کے بعد کہا) بلکہ آپ ہی اے رب پیدا کرنے والے ہیں۔ تین دفعہ یہی جملہ دہرایا۔ اس کے بعد یہ آیت پڑھی:\n﴿ افرأيتم ما تحرثون أأنتم تزرعونه ام نحن الزارعون ﴾ [الواقعہ ۶۳-۶۴]\n’’بتلاؤ بھلا جو تم کھیتی کاشت کرتے ہو اسے تم لہلہاتے کھیت بنا لیتے ہو یا ہم بنانے والے ہیں۔‘‘\nسیدنا علی نے کہا۔ بلکہ تو ہی یہ کرتا ہے یا رب تین بار یہی کہا۔ اس کے بعد یہ آیت پڑھی۔\n﴿ افرأيتم الماء الذي تشربون أأنتم انزلتموه من المزن ام نحن المنزلون ﴾ [الواقعہ ۶۸-۶۹]\n’’بھلا تم بتاؤ تو سہی یہ پانی جسے تم پیتے ہو کیا اسے بادلوں سے تم اتارتے ہو یا ہم اتارنے والے ہیں۔‘‘\n(پھر سیدنا علی نے کہا۔ بلکہ یا رب تو ہی یہ کرتا ہے تین بار یہی جملہ کہا۔ پھر انہوں نے یہ آیت پڑھی:\n﴿ افرأيتم النار التي تورون أنتم أنشأتم شجرتها ام نحن المنشئون ﴾ [الواقعہ ۷۱-۷۲]\n’’بھلا تم لوگ بتلاؤ کہ یہ آگ یہ جسے تم سلگاتے ہو کیا اس کا درخت تم نے بنایا ہے یا کہ ہم بنانے والے ہیں۔‘‘\nپھر سیدنا علی رضی اللہ عنہ نے کہا بلکہ یا رب تو ہی ہے۔ تین بار یہی کہا۔"],[226,"§حضرت عیسیٰ علیہ السلام کی طرف منسوب پر مغز اور جامع دعا\nہمیں خبر دی ہے ابو عبد اللہ حافظ نے کہ خبر دی ہے ابو عبد اللہ محمد بن علی صنعانی نے کہ ہمیں حدیث بیان کی اسحق بن ابراہیم نے۔ کہ خبر دی ہے عبد الرزاق نے معمر سے انہوں نے جعفر بن برقان سے کہ عیسیٰ بن مریم علیہ السلام یہ فرماتے تھے۔ اے اللہ میں تو ایسا ہوں یہ جو چیز میں ناپسند کرتا ہوں اس کو بھی ہٹا نہیں سکتا۔ اور جس چیز کی میں آرزو کرتا ہوں اس کے نفع کو حاصل کرنے کا بھی میں مالک نہیں ہوں۔ میرا معاملہ تو میرے سوا کسی اور کے ہاتھ میں ہے۔ اور میں خود بھی اپنے عمل کا رہن ہوں۔ مجھ سے بڑا فقیر کوئی نہیں۔ اے اللہ میرے دشمن کو میرے معاملے میں خوش نہ فرما۔ اور میرے دوست کو میرے معاملے میں دکھ نہ پہنچا۔ اور میری مصیبت کو میرے دین میں واقع نہ فرما اور اس شخص کو مجھ پر مسلط نہ فرما جو مجھ پر رحم نہ کرے۔\nبعض اہل نظر کا قول:"],[227,"ہمیں خبر دی ہے ابو عبد الرحمن سلمی نے اس چیز کے بارے میں جو ان کے سامنے پڑھا گیا بعض حضرات سے بطور حکایت کے کہ انہوں نے کہا تھا کہ دین کا کمال نیکی کی طاقت اور بدی سے رکنے کی طاقت سے بیزار ہونے اور سب چیز میں ہر چیز کے خالق مالک کی طرف رجوع ہونے میں ہے۔\nحضرت سہل کا قول:\nعبد الرحمن سلمی نے کہا کہ حضرت سہل نے فرمایا: جس شخص نے (از راہ خود پسندی) اپنے نفس کی طرف نظر رکھی وہ کامیاب نہیں ہوا۔ اور جس نے اپنے نفس کے لئے کسی حال کا دعویٰ کیا اس کا وہ دعویٰ پورا نہیں ہوا۔ مخلوق میں سے خوش نصیب و سعادت مند وہ ہے جس نے اپنے افعال و اقوال سے نظر ہٹا لی۔ اس شخص کے لئے فضل حاصل کرنے اور دوسروں کو فضل پہنچانے کا اور تمام افعال میں اللہ کے احسان کی رؤیت کا دروازہ کھول دیا جاتا ہے۔ اور مخلوق میں سے شقی اور بدنصیب وہ ہے جس کے اپنے افعال و اقوال اس کی اپنی نظر میں اچھے لگیں اور وہ ان پر فخر کرے اور اپنے لئے ان کا دعویٰ کرے وہ دعویٰ اس کو ایک دن تباہ کر دے گا۔ اگر چہ فی الوقت وہ تباہی سے بچا رہا ہو کیا آپ دیکھتے ہیں کہ اللہ تعالیٰ نے قارون کے بارے کیسے واقعہ بیان فرمایا ہے۔ (خصوصی طور پر یہ فقرہ قابل غور ہے)\n﴿ انما اوتيته على علم عندي ﴾ [القصص ۷۸]\n’’کہ یہ مال کثیر میرے اپنے اس علم کی بدولت ہے جو میرے پاس ہے۔‘‘\nاس سے معلوم ہوتا ہے کہ وہ اللہ کے فضل کو یکسر بھول گیا تھا۔ اور اس نے اپنی ذات کے لئے فضیلت اور خوبی کا دعویٰ کر لیا لہذا اللہ تعالیٰ اس کو اسی کی پاداش میں اسی مال و علم سمیت زمین میں دھنسا دیا۔ اور کتنے ہی شریروں کو اللہ نے (قارون کی طرح) زمین میں دھنسایا اس حال میں کہ وہ شریر اپنے فضل کا ادعا رکھنے والے اس ہلاکت اور زمین میں دھنس جانے کا شعور و ادراک بھی نہیں کر سکے۔ اور اشرار کو زمین میں دھنسا دینا (دراصل) حفاظت کو ختم کر دینا ہے اور گناہوں سے ہٹنے بچنے اور نیکی کرنے کی قوت کے حوالے کرنا ہے۔ اور چوڑے چوڑے دعووں کے ساتھ زبان کھولنا۔ اور اللہ کے فضل اور اس کی عنایت سے اندھا بن جانا۔ اور اللہ کے انعام اور احسان پر شکر کرنا (جب یہ کیفیات آجائیں تو یہی زوال کا وقت ہوتا ہے۔ یعنی ایسا انسان ہمیشہ کے لئے ان خرابیوں کی بدولت زوال سے دوچار ہو جاتا ہے۔"],[228,"ہمیں خبر دی ہے ابو عبد اللہ حافظ نے کہ ہمیں بات بیان کی ہے۔ ابو بکر محمد بن جعفر ادمی قاری نے کہ ہمیں بات بتائی ابو العیناء نے انہوں نے کہا ہمیں بات بیان کی ہے۔ عمر بن اسماعیل بن مجالد بن سعید ہمدانی نے ہمیں بات بیان کی ہمارے والد نے مجالد سے انہوں نے شعبی سے انہوں نے محمد بن اشعث کندی سے انہوں نے کہا کہ ہر شے کے لئے غلبہ اور حکومت ہوتی ہے۔ یہاں تک کہ حماقت کے لئے بھی عقل پر غلبہ اور حکومت ہوتی ہے۔\nامام بیہقی رحمۃ اللہ علیہ نے فرمایا:\nامام بیہقی رحمۃ اللہ علیہ نے فرمایا غلبہ اس کے لئے ہے کہ قضاء و قدر جس کی موافقت کر لے۔ اللہ تعالیٰ کا ارشاد ہے۔\n﴿ وتلك الايام نداولها بين الناس ﴾ [آل عمران ۱۴۰]\n’’یہی ایام ہیں ہم جنہیں لوگوں کے درمیان پھیرتے رہتے ہیں۔‘‘"],[229,"ہمیں خبر دی ہے ابو عبد اللہ حافظ نے کہ میں نے سنا ابو عبد اللہ محمد بن ابراہیم بن حمش سے وہ کہتے تھے کہ میں نے اپنے والد سے سنا وہ فرماتے تھے۔ کہ جب تو اپنے رب کی اطاعت نہیں کرتا تو اس کا دیا ہوا رزق بھی نہ کھا۔ جب تو اس کی منع کی ہوئی بات سے باز نہیں آتا تو اس کی حکومت سے باہر نکل جا جب تو اس کے فعل سے راضی نہیں ہے تو تو رب بھی اپنے لئے اس کے سوا کوئی دوسرا تلاش کر لے جب اس کی نافرمانی کرتا ہے تو ایسی جگہ چلا جا جہاں وہ تجھے نہ دیکھے۔\nابراہیم بن حمش زاہد کا قول:"],[230,"ہمیں خبر دی ہے ابو عبد اللہ حافظ نے کہ میں نے سنا تھا ابو منصور صوفی سے جو کہ ابراہیم بن حمش زاہد کے نواسے ہوتے تھے وہ کہتے تھے کہ میں نے اپنے نانا سے سنا تھا وہ کہتے تھے کہ۔ قضا ہنستی ہے حفاظتی تدبیر پر۔ موت ہنستی امید و آرزو پر تقدیر ہنستی ہے تدبیر پر۔ نصیب قسمت ہنستی ہے کوشش اور غنی ہونے پر۔"],[231,"§بعض اہل نظر کے منظوم ارشادات\nہمیں ابو عبد اللہ حافظ نے شعر سنائے اور کہا کہ مجھے شعر سنائے تھے ابو محمد حسین بن علی علوی شہید نے انہوں نے کہا کہ مجھے المثنیٰ۔ اپنے یہ ذاتی شعر سنائے تھے۔\nوبعين مفتقر اليك رأيتني فهجرتني ونزلت بي من حالق\n(اے میرے مالک) اپنی بارگاہ میں اٹھی ہوئی میری محتاج و سائل نظروں کو دیکھ کر آپ نے جدا کر دیا ہے اور میرے ساتھ مصیبت اتر پڑی ہے۔\nلست الملوم انا الملوم لانني انزلت حاجاتي بغير الخالق آپ کے اوپر کوئی ملامت نہیں ہے ملامت تو مجھ پر ہے اس لئے کہ میں نے اپنی حاجات غیر خالق و مالک کے آگے پیش کر دیں۔"],[232,"§’’عمرو زاہد کا ارشاد:‘‘\nہمیں خبر دی ہے ابو عبد اللہ حافظ نے کہ میں نے سنا ابو محمد حسن بن احمد بن یعقوب مامونی سے وہ کہتے تھے میں نے سنا عمرو زاہد سے شافعی رحمۃ اللہ علیہ کے لئے شعر کہتے تھے:\nواذا سمعت بان مجدوداً حوى عوداً فاثمر في يديه فصدق\nجب آپ یہ بات سنیں کہ کٹی ہوئی سیاہ لکڑی اس کے ہاتھوں میں پھل آور ہو گئی ہے تو اس بات کی تصدیق کر دے۔\nواذا سمعت بان محروماً اتى ماءً ليشربه فغاض فحقق\nاور جب آپ یہ سنیں کہ کوئی ناکام (پیاسا انسان) پانی کے پاس آیا ہے پینے کے لئے اور وہ نیچے ہو گیا اور خشک ہو گیا تو مان لے۔\nومن الدليل على القضاء وكونه بؤس اللبيب وطيب عيش الاحمق\nیہ بات قضاء کے ہونے اور وجود کے دلائل میں سے ہے کہ عقلمند بھوکا رہتا ہے اور بے وقوف عیش کرتا ہے۔\nعبد اللہ بن شبیب کا ارشاد:"],[233,"ہمیں خبر دی ہے ابو عبد اللہ حافظ نے کہ ہمیں بات بیان کی ابو الصقر احمد بن فضل کاتب نے ہمدان میں کہ ہمیں شعر سنائے تھے احمد بن یحییٰ ثعلب نے انہوں نے کہا ہمیں شعر بیان کئے عبد اللہ بن شبیب نے۔\nليس اختيار ولا عقل ولا ادب يجدى عليك اذا لم يسعد القدر\nجب تقدیر معاونت نہ کرے تو نہ بزرگی فائدہ تجھے دے گی نہ علم نہ ہی عقل۔\nما يقضه الله لا يعييك مطلبه والسعي في نيل مالم يقضه عسر\nاور جس چیز کا اللہ فیصلہ کر دے اس کی تلاش تجھے نہیں تھکائے گی۔ اور جس چیز کا اس نے فیصلہ نہ کیا ہو اس کے حصول کی کوشش بھی گراں ہوتی ہے۔\nكم مانع نفسه ارابها حذراً للفقر ليس له من ماله ذخر\nبہت سے لوگ اپنے نفس کو فقر کے خوف سے اس کی خواہشات پوری کرنے سے باز رکھتے ہیں مگر پھر بھی ان کے پاس مال جمع نہیں ہوتا۔\nان كان امساكه للفقر يحذره فقد يعجل فقراً قبل يفتقر\nاحمد بن عبید اللہ دارمی کا ارشاد:"],[234,"ہمیں خبر دی ہے ابو عبد اللہ حافظ نے کہ ہمیں شعر سنائے تھے ابو عمر محمد بن احمد بن اسحق نحوی نے اس نے کہا ہمیں شعر سنائے تھے احمد بن عبید اللہ دارمی نے انطاکیہ میں۔ اپنے کلام میں سے۔\nيا لأم الدهر على مابنا لا تلم الدهر على غدره\nہمارے ساتھ جو گذر رہی ہے اس پر زمانے کو اے ملامت کرنے والے زمانے کو اس کی بے وفائی اور دھوکے پر ملامت نہ کر۔\nفالدهر مامور له امر ينصرف الدهر الى امره\nاس لئے کہ زمانے کو تو حکم ملا ہوا ہے (وہ مجبور ہے) اس کے حکم دینے والا موجود ہے جو زمانے کو اپنے حکم کی طرف پھیرتا ہے۔\nتم كافر بالله امواله تذداد اضعافاً على كفره بہت سے اللہ کے ساتھ کفر کرنے والے کافر ہیں جن کے مال دو گنے چوگنے بڑھ رہے ہیں ان کے کفر کے باوجود بھی۔\nومؤمن ليس له دانق يزداد ايماناً على فقره\nاور بہت سے مؤمن ایسے ہیں جن کے پاس کوئی پائی پیسہ نہیں بلکہ وہ اپنے فقر کے باوجود ایمان میں بڑھ رہے ہیں۔\nلا خير في من لم يكن عاقلاً يبسط رجليه على قدره\nاس شخص میں کوئی اچھائی نہیں ہے وہ عقلمند نہیں ہوتا۔ جو تقدیر کے آسرے پر پیر پسار لیتا ہے۔\nسیدنا ابن عباس رضی اللہ عنہ کا ارشاد:"],[235,"ہمیں خبر دی ہے ابو عبد اللہ نے اس نے کہا مجھے خبر دی ہے ابو زکریا یحییٰ بن محمد عنبری نے انہوں نے کہا ہمیں بات بتائی ہے۔ محمد بن عبد السلام نے انہوں نے کہا ہمیں بات بتلائی ہے اسحاق بن ابراہیم نے کہ خبر دی ہے ابو معاویہ نے انہوں نے کہا ہمیں بات بیان کی ہے اعمش نے انہوں نے منہال بن عمرو سے انہوں نے سعید بن جبیر سے انہوں نے ابن عباس رضی اللہ عنہ اور انہوں نے سلیمان بن داؤد علیھما السلام کا قصہ ذکر فرمایا یعنی ان کے سفر کے بارے میں فرمایا وہ جنگل میں سفر کر رہے تھے اچانک پانی کی ضرورت پیش آئی لہذا ھدھد پیش ہو گیا اور زمین پر ٹھوکریں مارنے لگا اور اس نے پانی کا مقام پا لیا۔ اتنے میں جنات آ گئے انہوں نے اس مقام کو پو چھیل دیا جیسے جانور کی کھال اتاری جاتی ہے لہذا انہوں نے پانی حاصل کر لیا۔ نافع بن ازرق نے کہا۔ ٹھہرئیے ذرا۔ آپ نے ھدھد کو دیکھا ہے کہ وہ آ کر زمین کو ٹھوکریں مارتا ہے اور وہ پانی کا مقام پا لیتا ہے۔ اور جب وہ شکار کے جال کے پاس آتا ہے تو اسے نہیں دیکھتا یہاں تک کہ وہ اس کے گلے میں پھنس جاتا ہے۔\nسیدنا عبد اللہ بن عباس رضی اللہ عنہ کا قول:\nفرماتے ہیں:\nان القدر اذا جاء حال دون البصر\nتقدیر جب آتی ہے نظروں کے آگے حائل ہو جاتی ہے۔"],[236,"میں نے سنا ابو عبد الرحمن سلمی سے وہ فرماتے تھے میں نے سنا حسن بن احمد بن موسیٰ قاضی سے وہ کہتے تھے میں نے سنا ترمذی سے وہ کہتے تھے۔\nاذا جاء القدر عمى البصر واذا جاء الحين غطى العين\nجب تقدیر آتی ہے آنکھیں اندھی ہو جاتی ہیں۔ اور جب موت آتی ہے تو آنکھوں پر پردہ ڈال دیتی ہے۔\nابو عمرو زاہد کا ارشاد:"],[237,"ہمیں خبر دی ہے ابو عبد اللہ حافظ نے کہ ہمیں شعر بتائے ابوالحسین محمد بن احمد بن ثابت بغدادی نے انہوں نے کہا ہمیں شعر سنائے ابو عمرو زاہد نے۔\nاذا اراد الله امراً بامرئ وكان ذا رأي وعقل وبصير\nجب اللہ تعالیٰ کسی آدمی کے ساتھ کسی امر کا ارادہ کرتے ہیں، اور وہ صاحب رائے صاحب عقل و صاحب بصیرت ہوتا ہے۔\nوحللية يعملها في كل ما ياتي به محتوم اسباب القدر اس کو ایسی تدبیر سکھاتا ہے وہ ہر اس چیز میں بروئے کار لاتا ہے جس کے ساتھ تقدیر کے حتمی اسباب پیدا ہو جاتے ہیں۔\nاغراه بالجهل واعمى عينه فسله عن عقله سل الشعر\nجہالت میں واقع کرتا ہے اس کو اور اندھا کر دیتا ہے اس کی آنکھ کو۔ اس کی عقل کو ایسے بھینچ لیتا ہے جیسے بال کھینچا جاتا ہے۔\nحتى اذا انفذ فيه حكمه رد عليه عقله ليعتبر\nیہاں تک کہ جب اس میں اپنے حکم کو جاری کرتا ہے۔ تو اس کی عقل بھی واپس کر دیتا ہے تانکہ وہ نصیحت عبرت حاصل کرے۔\nمحمود بن حسن وراق کا ارشاد:"],[238,"استاذ ابوالقاسم حسن بن محمد بن حبیب نے شعر بیان کئے انہوں نے کہا۔ مجھے شعر بیان کئے ابو جعفر بن محمد بن صالح اوبری نے انہوں نے کہا ہمیں شعر سنائے۔ حماد بن علی بکراوی نے۔ اور یہ شعر محمود بن حسن وراق کے ہیں۔\nتوكل على الرحمن في كل حاجة اردت فان الله يقضي ويقدر\nاپنی ہر ہر حاجت اور مراد میں رحمن پر بھروسہ کیجئے، اس لئے کہ اللہ تعالیٰ ہی تقدیر و قضا کا مالک ہے۔\nمتى ما يرد ذو العرش امرا بعبده يصبه وما للعبد ما يتخير\nجس وقت عرش کا مالک اپنے بندے کے ساتھ جس چیز کا ارادہ کرتا ہے وہ اسے یہ پہنچ جاتی ہے اور بندے کے لئے کوئی پسند و اختیار نہیں ہے۔\nوقد يهلك الانسان من وجه امنه وينجو بحمد الله من حيث يحذر\nکبھی انسان امن کے طریقے سے بھی ہلاک ہو جاتا ہے۔ اور کبھی بحمد اللہ خطرے کی جگہ سے بھی نجات پا لیتا ہے۔\nابوالفوارس جنید طبری کا ارشاد:"],[239,"استاد ابوالقاسم نے کہا کہ مجھے شعر سنائے ابوالفوارس جنید بن احمد طبری نے۔\nالعبد ذو ضجر والرب ذا القدر والدهر ذو دول والرزق مقسوم\nبندہ مقام کی تنگی اور رب تقدیر کا مالک ہے۔ اور زمانہ ڈول اور بادلوں والا ہے اور رزق تقسیم شدہ ہے۔\nوالخير اجمع فيما اختار خالقنا وفي اختيار سواه اللوم والشوم\nہر چیز اسی میں جمع ہے جو ہمارے خالق نے انتخاب فرمایا ہے۔ اور اللہ کے انتخاب کے ماسوا انتخاب میں خوف اور ملامت اور انجام کی خرابی اور نحوست ہے۔ (1)","",{"k":"(1) مختصر شعب الإيمان ص ۲۵"}],[240,"§باب نمبر ۶\n§ایمان کا چھٹا شعبہ\n§یوم آخرت کے ساتھ ایمان\n§شیخ حلیمی رحمتہ اللہ علیہ نے فرمایا:\nکہ یوم آخرت کے ساتھ ایمان کا مطلب ہے اس بات کی تصدیق کرنا کہ ایام دنیا کے لئے آخر ہے اور انتہا ہے۔ یعنی یہ دنیا ٹوٹ جانے والی ہے، اور اس جہان دنیا کی بناوٹ ایک دن ٹوٹ پھوٹ کر تباہ ہو جانے والی ہے۔ اور اس کی ترکیب ایک وقت تحلیل ہونے والی ہے۔ حقیقت میں دنیا کے ختم ہو جانے کے اعتراف میں دنیا کی ابتدا ہونے کا بھی اعتراف ہے۔ کیونکہ اگر یہ عالم قدیم ہوتا اس کی ابتدا نہ ہوتی تو یہ فنا ہوتا اور نہ یہ تبدیل ہوتا۔\nآخرت کا عقیدہ رکھنے اور اس کے بارے میں شرح صدر حاصل کرنے میں وہ بات ہے جو اللہ سے ڈرنے کی فضیلت پر ابھارتی ہے۔ اور یہ کہ دنیا کی طرف میلان کم رکھے۔ اور دنیا کی مصیبتوں اور غموں کو تحقیر سمجھے۔ اور ان پر صبر کرے۔ اور خواہشات کے پریشان کرنے پر صبر کرے۔ اور اللہ تعالیٰ کے پاس جو جزاء اور ثواب ہے اس کے ساتھ یقین رکھے اور اس پر اجر کے حصول کی نیت و ارادہ کرے۔ اللہ تعالیٰ نے اپنی کتاب میں ارشاد فرمایا ہے۔\n§﴿ ومن الناس من يقول آمنا بالله وباليوم الآخر وما هم بمؤمنين ﴾ [البقرہ ۸]\n’’لوگوں میں سے کچھ وہ لوگ بھی ہیں جو یہ کہتے ہیں کہ ہم اللہ پر ایمان لائے ہیں اور آخرت کے دن کے ساتھ بھی حالانکہ وہ ایماندار نہیں ہیں۔‘‘\n§اور ایک ارشاد ہے:\n§﴿ قاتلوا الذين لا يؤمنون بالله ولا باليوم الآخر ﴾ [التوبہ ۲۹]\n§’’جہاد کرو ان لوگوں کے ساتھ جو اللہ پر اور آخرت پر ایمان نہیں لائے۔‘‘\nان کے علاوہ اور بہت ہی آیات ہیں۔\n§امام بیہقی کا قول:\nامام بیہقی رحمۃ اللہ علیہ نے فرمایا۔ ہم نے سیدنا ابن عمر والی سیدنا عمر رضی اللہ عنہ سے اور نبی کریم صلی اللہ علیہ وسلم سے روایت میں جب کہ آپ سے ایمان کے بارے میں پوچھا گیا تھا۔ روایت کیا ہے۔ کہ آپ نے فرمایا تھا:\n§ان تؤمن بالله وملائكته وكتبه ورسله واليوم الآخر وتؤمن بالقدر خيره وشره\nیہ کہ تو اللہ پر ایمان لا۔ اور اس کے فرشتوں۔ اس کی کتابوں اس کے رسولوں کے ساتھ اور آخرت کے دن کے ساتھ۔ اور تو ایمان لا اچھی اور بری تقدیر کے ساتھ۔\nہمیں خبر دی ہے ابو عبد اللہ حافظ نے کہ ہمیں خبر دی ہے ابو بکر بن محمد صوفی نے کہ ہمیں حدیث بتائی ہے۔ عبد الصمد بن فضل نے کہ ہمیں حدیث بتائی ہے عبد اللہ بن یزید نے یحییٰ بن عمر سے انہوں نے سیدنا ابن عمر رضی اللہ عنہ سے پھر وہی مذکور حدیث ذکر فرمائی ہے۔\nشیخ حلیمی رحمتہ اللہ علیہ کا ارشاد:\nشیخ حلیمی رحمتہ اللہ علیہ نے فرمایا اللہ تعالیٰ نے اپنے نبی صلی اللہ علیہ وسلم کی زبان اقدس کے ذریعے خبر دی ہے کہ وہ اس کو فنا کر دے گا جو کچھ دھرتی پر ہے۔ اور اس دھرتی کو دوسری دھرتی سے تبدیل کر دے گا اور یہ خبر دی ہے کہ سورج لپیٹ دیا جائے گا اور سمندر آگ سے گئے۔ اور ستارے بکھر جائیں گے آسمان پھٹ جائے گا، اور پگھلے ہوئے تانبے کی مثل ہو جائے گا۔ پھر اسے لپیٹ دیا جائے گا جیسے کوئی تحریر لپیٹ دی جاتی ہے۔ اور پہاڑ دھنی ہوئی اون کی طرح ہو جائیں گے۔ کہ اللہ تعالیٰ ان کو اڑا کر بکھیر دے گا۔ اور چھوڑ دے گا زمین چٹیل میدان۔ نہ دیکھوں اس میں کوئی ٹیلہ اور نہ ہی کوئی بلندی، اور یہ سب کچھ ہونے والا ہے۔ جیسے اس کے بارے حدیث شریف آ چکی ہے اللہ کا وعدہ سچا ہے اور اس کا قول برحق ہے۔\nشیخ حلیمی نے فرمایا۔\nکہ الساعة جس کا ذکر قرآن میں مکرر آیا ہے وہ دو طرح پر ہے۔\nاول: دنیا کی ساعات میں سے آخری ساعت۔\nارشاد باری تعالیٰ ہے:\n﴿ يسئلونك عن الساعة ايان مرسها ﴾ [اعراف ۱۸۷]\n’’(اے پیغمبر یہ لوگ) آپ سے قیامت کے بارے میں پوچھتے ہیں کہ اس کے واقع ہونے کا وقت کب ہے۔‘‘\nیہ سوال اس دنیا کی آخری ساعت کے بارے میں ہے۔ اس لئے کہ اس کا جواب اللہ تعالیٰ کی طرف ان الفاظ میں دیا گیا ہے:\n﴿لا تأتيكم الا بغتة﴾\n’’کہ وہ تمہارے پاس اچانک ہی آ جائے گی۔‘‘ (سورۃ اعراف ۱۸۷)\nاسی طرح ارشاد باری تعالیٰ ہے:\n﴿ وما يدريك لعل الساعة تكون قريبا ﴾ [الاحزاب ۶۳]\n’’اور تمہیں کیا معلوم کہ شاید قیامت قریب ہی آ گئی ہو۔‘‘\nدوم: آخرت کی ساعات میں پہلی ساعت۔\nارشاد باری تعالیٰ ہے:\n﴿ ويوم تقوم الساعة ﴾ [سورۃ الروم ۵۵]\n’’جس دن ساعت (قیامت) قائم ہوگی۔‘‘\nیعنی جس دن وہ لوگ اٹھائے جائیں گے جو قبروں میں پڑے ہیں۔\nاس لئے کہ اللہ تعالیٰ فرماتے ہیں:\n﴿ يقسم المجرمون ما لبثوا غير ساعة ﴾ [روم ۵۵]\n’’جس دن قیامت قائم ہوگی گنہگار قسمیں کھائیں گے۔ کہ وہ دنیا میں ایک گھڑی سے زیادہ نہیں رہے تھے۔‘‘\nاسی طرح اور آیت میں ارشاد ہے:\n﴿ ويوم تقوم الساعة ادخلوا آل فرعون اشد العذاب ﴾ [غافر ۴۶]\nجس دن قیامت قائم ہوگی (حکم ہوگا) کہ فرعونیوں کو سخت ترین عذاب میں داخل کرو۔\nامام بیہقی کا قول:\nامام بیہقی رحمۃ اللہ علیہ فرماتے ہیں۔ تحقیق قرآن اس بات کے ساتھ ناطق ہے کہ نبی کریم صلی اللہ علیہ وسلم یہ نہیں جانتے قیامت کب قائم ہوگی اور نہ ہی اس بات کو اللہ کی مخلوق میں سے کوئی ایک جانتا ہے۔\n(اگر یہ اعتراض کیا جائے کہ نبی کریم صلی اللہ علیہ وسلم اگر نہیں جانتے تھے تو اس حدیث کا کیا مطلب ہے؟)\nبعثت انا والساعة كهاتين\nمیں بھیجا گیا ہوں اور قیامت ان دو انگلیوں کی طرح (جیسے شہادت کی اور بیچ کی انگلی ملی ہوئی ہیں)۔\nاس سے معلوم ہوتا ہے آپ جانتے تھے کہ قیامت کب قائم ہوگی) (تو اس کا جواب یہ ہے) کہ اس حدیث کا مطلب یہ ہے کہ میں آخری نبی ہوں۔ میرے بعد کوئی نبی نہیں آئے گا ہاں میرے بعد قیامت ہی آئے گی۔ اس کے ساتھ ساتھ وہ قریب ہے اس لئے کہ اس کی اشراط میرے اور قیامت کے درمیان متواتر اور مسلسل ہوں گی۔ ہاں پہلی اور آخری شرط کے مابین کتنا وقت ہے۔ وہ نا معلوم ہے۔ ہم نے کتاب البعث والنشور میں وہ تمام اخبار و احادیث ذکر کر دی ہیں جو قیامت اور اس کی علامات کی بابت وارد ہوئی ہیں۔ جس کی وجہ سے یہاں ان کا اعادہ کرنا ضروری نہیں ہے۔\nہم نے شعیب بن حمزہ سے۔ ابی زناد سے۔ اعرج سے سیدنا ابو ہریرہ رضی اللہ عنہ سے روایت کیا ہے کہ سیدنا ابو ہریرہ فرماتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا تھا۔ قسم ہے اس ذات کی جس کے قبضہ قدرت میں میری جان ہے قیامت ضرور قائم ہوگی حالانکہ دو آدمی خرید و فروخت کرنے کے لئے کپڑے کے تھان کو پھیلائیں گے۔ وہ ابھی تک اس کا سودا کر کے تھان نہیں لپیٹ سکیں گے کہ قیامت قائم ہو جائے گی۔ قیامت ضرور قائم ہوگی۔ حالانکہ کوئی آدمی اپنے پانی کے حوض کو پلاستر کر رہا ہوگا وہ اس سے پانی نہیں پی سکے گا کہ قیامت قائم ہو جائے گی۔ اور قیامت ضرور قائم ہوگی۔ حالانکہ ایک آدمی اپنی اونٹنی کا دودھ نکال کر اونٹنی کے نیچے سے ہٹے گا وہ اسے پی نہیں سکے گا کہ قیامت قائم ہو جائے گی۔ کھانے پینے بیٹھا ہوا بندہ لقمہ منہ کی طرف اٹھائے گا وہ اسے کھا نہیں سکے گا کہ قیامت قائم ہو جائے گی۔"],[241,"ہمیں اس کی خبر دی ہے ابو عبد اللہ حافظ نے آخری دو روایتوں کے بارے میں انہوں نے کہا ہمیں حدیث بتائی ہے ابو العباس محمد بن یعقوب نے انہوں نے کہا ہمیں حدیث بتائی ہے۔ محمد بن خالد نے انہوں نے کہا ہمیں بات بتائی ہے بشر بن شعیب نے اپنے باپ سے پھر اس حدیث کو ذکر کیا ہے۔ اور بخاری نے اس کو صحیح بخاری میں ابوالیمان سے اس نے شعیب سے روایت کیا ہے۔ اور امام مسلم نے اس کو حدیث سفیان سے انہوں نے ابو زناد سے روایت کیا ہے۔ (1)","",{"k":"(1) آخر الجزء الثالث من المخطوط يتلوه إن شاء الله الجزء الرابع \"السامع من شعب الإيمان\" أبو الزناد: عبد الله بن ذكوان: والأعرج هو عبد الرحمن بن هرمز. أخرجه البخاري (۸۱/۱۳) فتح عن أبي اليمان به، ومسلم (۲۲۷۰/۴) عن زهير بن حرب عن سفيان بن عيينة عن أبي الزناد به. ﴿زعم الذين كفروا ان لن يبعثوا﴾ (تغابن ۷) ’’جو لوگ کافر ہیں ان کا اعتقاد ہے کہ وہ دوبارہ ہرگز نہیں اٹھائے جائیں گے۔‘‘ ﴿قل الله يحييكم ثم يميتكم﴾ (الجاثیہ ۲۶) ’’کہہ دیجئے کہ اللہ تعالیٰ ہی تمہیں جان بخشتا ہے پھر وہی تم کو موت دیتا ہے۔‘‘ ﴿افحسبتم انما خلقناكم عبثا وانكم الينا لا ترجعون﴾ (المؤمنون ۱۱۵) ’’کیا تم یہ خیال کرتے ہو کہ ہم نے تم کو بے فائدہ پیدا کیا ہے اور یہ کہ تم ہماری طرف لوٹ نہیں آؤ گے۔‘‘ حدیث سے استدلال ہم نے مطر الوراق سے روایت کیا ہے اس نے عبد اللہ بن بریدہ سے اس نے یحییٰ بن یعمر سے اس نے سیدنا ابن عمر سے انہوں نے سیدنا عمر بن خطاب رضی اللہ عنہ سے انہوں نے نبی کریم صلی اللہ علیہ وسلم سے حدیث ایمان کے بارے میں سیدنا عمر کہتے ہیں کہ سائل نے کہا یا رسول اللہ ایمان کیا چیز ہے؟ حضور صلی اللہ علیہ وسلم نے فرمایا ایمان یہ ہے کہ تو اللہ کے ساتھ ایمان لا اور اس کے فرشتوں اس کی کتابوں۔ اس کے رسولوں کے ساتھ اور مرنے کے بعد دوبارہ زندہ ہونے کے ساتھ اور پوری تقدیر کے ساتھ۔ ۲۵۶...... ہمیں خبر دی ہے ابو بکر احمد بن محمد اثنانی نے کہ خبر دی ہے ابوالحسن احمد بن محمد بن عبدوس سے اس نے کہا ہمیں حدیث بیان کی ہے عثمان بن سعید دارمی نے کہ ہمیں حدیث بیان کی ہے سلیمان بن حرب نے کہ ہمیں حدیث بیان کی ہے حماد بن زید نے مطر سے پھر اس نے مذکورہ حدیث ذکر کی ہے۔ اور وہ مسلم شریف میں منقول ہے۔ مر کر دوبارہ زندہ ہو کر اٹھنے کے عقیدے کی تشریح دوبارہ اٹھنے پر ایمان لانا یہ ہے کہ انسان یہ عقیدہ اور ایمان رکھے کہ اللہ تعالیٰ مردہ اجسام کے چورے کو اور ذرات کو دوبارہ زندہ کر کے لوٹائے گا۔ اور ان کے وہ ذرات جو دریاؤں اور سمندروں میں بکھر گئے تھے، جو درندوں وغیرہ کے پیٹوں میں چلے گئے تھے جمع کرے گا۔ حتیٰ کہ وہ انسان اپنی پہلی شکل و صورت پر کھڑا ہو جائے گا۔ پھر تمام انسانوں کو زندہ کر کے جمع کرے گا اسی طرح اللہ تعالیٰ کے حکم کے ساتھ تمام لوگ زندہ ہو کر اللہ تعالیٰ کے آگے کھڑے ہوں گے چھوٹے بھی بڑے بھی۔ یہاں تک کہ وہ کچے ضائع ہونے والے حمل بھی جن کی خلقت مکمل ہو چکی تھی اور روح پڑ چکی تھی۔ اور وہ بھی جن کی خلقت مکمل نہیں ہوئی تھی۔ یا روح نہیں پڑی تھی بالکل بھی وہ بھی اور تمام مردے اللہ تعالیٰ کے نزدیک ایک جیسے ہیں۔ أخرجه مسلم (۳۶/۱) من طريق عبد الله بن بريدة عن يحيى بن يعمر به. ﴿اوليس الذي خلق السماوات والارض بقادر على ان يخلق مثلهم﴾ (یس ۸۰) ’’کیا وہ ذات جس نے آسمان اور زمین (جیسی بڑی بڑی مخلوقات) پیدا فرمائیں کیا وہ اس بات پر قادر نہیں ہے کہ وہ ان انسانوں کو پہلے کی طرح پیدا کر ڈالے۔‘‘ اور ارشاد فرمایا: ﴿اولم يروا ان الله الذي خلق السموات والارض ولم يعي بخلقهن بقادر على ان يحيي الموتى بلى انه على كل شئ قدير﴾ (احقاف ۳۳) ’’کیا ان لوگوں نے دیکھا نہیں کہ وہ اللہ جس نے زمین آسمان بنائے اور وہ ان کو بنانے میں تھکا بھی نہیں وہ اس بات پر پوری قدرت رکھتا ہے کہ وہ مردوں کو زندہ کرے ہاں بے شک وہ ہر چیز پر قادر ہے۔‘‘ اس آیت میں اللہ تعالیٰ نے مردوں کو زندہ کرنے کے عمل کو اللہ تعالیٰ کے ارض و سماء کو پیدا کرنے کی تمثیل سے ثابت فرمایا ہے حالانکہ وہ اپنے جسم کے اعتبار سے انسانوں سے بہت بڑے ہیں (تو جو ذات اتنی بڑی مخلوق پیدا کر سکتی ہے اس کے لئے انسان کو دوبارہ پیدا کرنا کیا شکل ہو سکتا ہے۔ تخلیق اول سے دوسری تخلیق پر استدلال اور ارشاد ہے: ﴿قال من يحيي العظام وهي رميم قل يحييها الذي انشأها اول مرة وهو بكل خلق عليم﴾ (یس ۷۸)"}],[242,"§باب نمبر ۷\n§ایمان کا ساتواں شعبہ\n§موت کے بعد دوبارہ جی اٹھنے زمین سے نکل پڑنے پر ایمان\nدوبارہ جی اٹھنے کے بارے میں قرآنی آیات بکثرت ہیں، ان میں سے کچھ یہ ہیں۔ اللہ تعالیٰ کا ارشاد ہے۔\nقرآن سے استدلال واللہ اعلم۔\n§بہر حال اللہ تعالیٰ کا یہ فرمان۔ قیامت کی صفت کے بارے میں:\n§﴿ ان زلزلة الساعة شئ عظيم يوم ترونها تذهل كل مرضعة عما ارضعت وتضع كل ذات حمل حملها ﴾ [الحج ۱]\n’’بے شک قیامت کا زلزلہ بہت بڑی چیز ہے جس دن اس کو پہنچیں گے ہر دودھ پلانے والی ماں اپنے بچے کو بھول جائے گی اور ہر حمل والی اپنا حمل ساقط کر دے گی۔‘‘\n§تحقیق انیق\n(مصنف رحمۃ اللہ علیہ فرماتے ہیں) مذکورہ آیت میں مذکور حمل والیوں سے مراد وہ حمل والیاں ہیں۔ (جو حاملہ ہو گئی) تھیں اور ان کی دنیا میں وضع حمل نہیں ہوئی تھی۔ جب وہ زندہ کر کے اٹھائی جائیں گی تو قیامت کے ہولناکی کی وجہ سے اپنے ان حملوں کو ساقط کر بیٹھیں گی۔ پھر اگر وہ حمل دنیا میں زندہ تھے تو قیامت میں وہ ان کو زندہ ہی گرا دیں گی اور ان پر موت مکرر نہیں آئے گی اور اگر وہ حمل دنیا میں ایسے تھے کہ ابھی ان میں روح نہیں پڑی تھی تو مائیں ان کو مردہ ہی گرا دیں گی جیسے وہ دنیا میں بے جان تھے۔ اس لئے کہ زندہ کرنا حیات کا اعادہ کرنا ہے اس کی طرف جو زندہ تھا پھر مار دیا گیا۔ اور جس کا دنیا کی زندگی میں کوئی حصہ نہیں تھا اس کا آخرت کی زندگی میں بھی کوئی حصہ نہیں ہوگا۔\n§قرآن مجید سے زندہ ہو کر اٹھنے کا اثبات\nاللہ تعالیٰ نے قرآن مجید کی کئی آیات میں بعث بعد الموت کے اثبات کو ذکر فرمایا ہے ان میں سے ایک آیت یہ بھی ہے۔\nکہتا ہے کون زندہ کرے گا ہڈیوں کو حالانکہ وہ بوسیدہ ہو چکی ہے۔ آپ فرما دیجئے وہی ان کو زندہ کرے گا جس نے ان کو پہلی بار پیدا کیا تھا اور وہ ہر مخلوق کو خوب جانتا ہے۔\nاللہ تعالیٰ نے اس آیت میں پہلی تخلیق کو دوسری تخلیق کے لئے دلیل بنایا ہے کیونکہ یہ بالکل اسی جیسی ہے۔\n§پھر مزید ارشاد فرمایا:\nسرسبز درخت سے آگ کی تخلیق سے قدرت پر احیاء اموات پر استدلال۔\n§الذي جعل لكم من الشجر الاخضر ناراً فاذا انتم منه توقدون۔ (یسٓ ۸۰)\nاور وہ وہی ذات عالی ہے جس نے تمہارے لئے سرسبز درخت سے آگ پیدا فرمائی ہے اور تم اسی سے آگ جلاتے ہو۔ اللہ تعالیٰ نے اس درخت سے آگ کے ظہور کو آگ کی حرارت اور خشکی کے باوجود اور درخت کے سرسبز ہونے اور تروتازہ ہونے کے باوجود پیدا کرنے کو دلیل بنایا ہے پرانی اور بوسیدہ ہڈیوں میں نئی حیات پیدا کرنے کی اور اللہ تعالیٰ نے قرآن پاک کی کئی کئی آیات کے اندر مردوں کو زندہ کرنے پر زمین کی مثال دے کر ہم لوگوں کو متنبہ فرمایا ہے۔ کہ زمین زندہ ہوتی ہے اور پودے اور کھیت کی نشو و نما کرتی ہے اور پھل دار کرتی ہے، پھر وہ مر جاتی ہے اور ایسی ہو جاتی ہے کہ اب وہ بالکل کچھ نہیں اگائے گی اسی طرح ایک عرصہ تک لوگوں کے قدموں تلے روندی جاتی رہتی ہے پھر اس پر جب پانی پڑتا ہے تو پھولتی اور حرکت کرتی ہے اور پھر زندہ اور آباد ہو جاتی ہے اور پھر سب چیز کو اگاتی اور اس کی نشو و نما کرتی ہے۔ حالانکہ اس سارے عمل میں اس کی موت و حیات پھر مدت پھر حیات کا فاعل حقیقی وہی اللہ تعالیٰ ہے۔ جب وہ اس تسلسل پر قادر ہے تو اس کو کون سی چیز عاجز کر سکتی کہ وہ انسان کو مار دینے اور زندگی کے تمام آثار چھین لینے کے بعد پھر دوبارہ اس کو زندہ کر دے اور پھر ویسا ہی بنا دے جیسا کہ وہ پہلے سے تھا۔ اور اسی خالق و مالک نے ہمیں متنبہ فرمایا ہے نطفہ کے زندہ کرنے پر جو کہ بے جان تھا پھر اس نے اس سے زندہ اور چلتا پھرتا انسان بنا دیا لہذا اسی طرح وہ مردوں کو زندہ کرنے پر بھی قادر ہے۔\n§اور ارشاد فرمایا:\nكيف تكفرون بالله وكنتم امواتاً فاحياكم۔ (البقرہ ۲۸) تم اللہ کے ساتھ کیسے کفر کرو گے حالان کہ تم بے جان تھے سو اسی نے تمہیں جان بخش دی۔\nیعنی باپ کی پشتوں اور ماں کے رحموں میں نطفے تھے اس سے تمہیں اس نے چلتے پھرتے کام کاج کرتے انسان بنا دیا۔\n§اور ارشاد فرمایا:\nالم نخلقكم من ماء مهين فجعلناه في قرار مكين الى قدر معلوم۔ فقدرنا فنعم القادرون۔ (المرسلت ۲۰-۲۳) کیا ہم نے تمہیں ایک حقیر سے پانی سے نہیں بنایا؟ ہم نے اس پانی کو ایک محفوظ جگہ میں ایک خاص وقت تک ٹھہرایا سو ہم نے (اس کے تمام مراحل) کا ایک خاص اندازہ مقرر فرمایا اور ہم ہی بہتر اندازے اور قدرت کے مالک ہیں۔ اس نے انسانوں کو آگاہ کر فرمایا کہ جب وہ باپ کی پشت سے نطفے کو نکالتا ہے تو وہ بے جان ہوتا ہے مردہ ہوتا ہے۔ پھر وہ اس کو رحم مادر میں زندہ کرتا ہے۔ جس کو پیدا کرنا ہوتا ہے اس سے پیدا کرتا ہے اور اس میں حیات کی ترکیب کرتا ہے، یہ مردہ اور بیجان کو زندہ کرنا روزمرہ کے لوگوں کے مشاہدہ میں ہے جو ذات اس زندگی عطا کرنے پر قادر ہے۔ وہ اس بات سے عاجز نہیں ہے کہ وہ اس کو موت دے دے پھر وہ اس کو دوبارہ زندہ کر دے۔ پھر اللہ تعالیٰ نے اسی مضمون کو ایک دوسری آیت میں ذرا تفصیل کے ساتھ بیان فرمایا ہے۔ اور ارشاد ہوا۔\n§تخلیق انسان، اور تخلیق شجر اور کھیت سے مسئلہ بعث بعد الموت پر استدلال\nالم يك نطفة من مني يمنى۔ ثم كان علقة فخلق فسوى۔ فجعل منه الزوجين الذكر والانثى۔ اليس ذلك بقادر على ان يحيي الموتى۔ (القیامہ ۳۷-۴۰)\nکیا انسان (پانی کی بوند یعنی) نطفہ نہیں تھا منی کا جو پکایا گیا؟ پھر وہ خون کی پھٹکی تھا سو اس کو اللہ تعالیٰ نے متناسب اعضا والا بنایا۔ پھر اس سے مرد اور عورت کے جوڑے بنائے کیا وہ اللہ (جو ان تمام امور پر قادر ہے) کیا وہ اس بات پر قادر نہیں ہے کہ وہ مردوں کو زندہ کرے۔\nاور اللہ تعالیٰ نے ہم لوگوں کو اس مسئلہ بعث بعد الموت پر دانہ اور گٹھلی کی پیدائش کے ساتھ متنبہ فرمایا۔ ارشاد ہوا۔\n§ان الله فالق الحب والنوى۔ يخرج الحي من الميت۔ (انعام ۹۵)\nجب کہ اللہ تعالیٰ دانہ اور گٹھلی کو (اگانے کے لئے) چیرتا ہے، وہی زندہ چیز کو بے جان چیز سے پیدا کرتا ہے۔ اس کی تفصیل اس طرح ہے کہ دانہ جب پورا ہو جاتا اور پک کر سوکھ جاتا ہے اور اس کے بڑھنے کے چانس ختم ہو جاتے ہیں یہی حال گٹھلی کا ہے کہ وہ بھی جب بڑی ہو کر بڑھنے سے رک جاتی ہے اور سوکھ جاتی ہے تو یہ دونوں چیزیں مردہ اور بے جان ہوتی ہیں، پھر جب دونوں کو زندہ اور تازہ زمین میں امانت رکھا جاتا ہے تو انہیں سے لمبے لمبے کھجور کے درخت اور لہلہاتے کھیت پیدا ہوتے ہیں جو کہ بڑھتے اور نشوونما پاتے ہیں یہاں تک کہ اپنی حد انتہا کو پہنچ جاتے ہیں۔ اسی تمثیل میں داخل ہے انڈا بھی کہ وہ جب انڈا دینے والی چیز سے جدا ہو جاتا ہے تو اس پر بھی موت کا اور بے جان ہونے کا حکم لگ جاتا ہے۔ پھر اللہ تعالیٰ اسی مردہ و بے جان انڈے سے زندہ اور جاندار پیدا کر دیتا ہے۔ آپ نے کبھی غور فرمایا کہ یہ کہ یہ سب کچھ کیا ہے یہی ہے مردہ کو زندہ کرنا بے جان کو جاندار بنانا اور یہ امر ایسا ہے جو سب کے نظروں کے سامنے ہے سب کے مشاہدے میں ہے اور اس کا علم یہ یہی ہے جس سے کسی کو انکار کی مجال نہیں ہے۔ یہی دلیل ہے اس بات کی کہ جو ذات یہ مذکورہ تصرف کرتی ہے وہی ذات تمام انسانوں کو قیامت میں دوبارہ زندہ کر کے حساب و کتاب کے لئے اپنے سامنے لا کھڑا کرے گی جس طرح اس کے لئے یہ مذکورہ امور کچھ مشکل نہیں ہیں بلکہ آسان ہیں اسی طرح اس کے لئے انسانوں کو دوبارہ پیدا کرنا اور زندہ کرنا بھی کچھ مشکل نہیں بلکہ آسان ہے۔\n§ابراہیم علیہ السلام کے واقعہ سے مسئلہ بعث پر استدلال\nاسی طرح اللہ تعالیٰ نے ہم لوگوں کو مردوں کے زندہ کرنے پر اس واقعہ کے ساتھ آگاہ فرمایا ہے جب اس نے ابراہیم علیہ السلام کو مردہ چیزوں کو زندہ کر کے دیکھایا تھا اللہ تعالیٰ نے اس واقعہ کی اطلاع ہم لوگوں کو قرآن مجید میں دی ہے۔ اور اس واقع کو تمام اہل ملل نے نقل کیا ہے۔\n§مسئلہ بعث بعد الموت پر حضرت عزیر علیہ السلام کے واقعہ سے استدلال\nاسی طرح اللہ تعالیٰ نے مسئلہ بعث بعد الموت کو حضرت عزیر علیہ السلام کے واقعہ کے ساتھ مطلع فرمایا ہے جب وہ ایک ویران اور تباہ شدہ بستی سے گزرے تھے اور وہ بستی اپنی چھتوں پر گر چکی تھی۔ از راہ تعجب یہ کہا کہ اللہ تعالیٰ کہاں؟ اس کو زندہ کریں گے؟ تو اللہ تعالیٰ نے ان کو سو سال تک موت کی نیند سلا دیا۔ پھر ان کو زندہ کر کے اٹھایا۔\n§مسئلہ بعث بعد الموت قوم عمالقہ کے ہزاروں افراد کی موت پھر زندگی سے استدلال\nاسی طرح اللہ تعالیٰ نے مسئلہ بعث بعد الموت کو ہمارے لئے اس واقعہ کی تفصیل بیان فرما کر واضح فرمایا کہ جب بنی اسرائیل یا قوم عمالقہ کے ہزاروں لوگ موت کے خوف سے اپنے گھروں کو چھوڑ کر بھاگے تھے (مگر موت نہیں ملتی اپنے وقت پر آ جاتی ہے) اللہ تعالیٰ نے حکم فرمایا کہ تم سب مر جاؤ لہذا وہ مر گئے پھر اللہ نے اس کو زندہ کیا۔ اللہ تعالیٰ نے اس واقعہ سے یہ واضح فرمایا جیسے میں نے ان ہزاروں کو زندہ کیا اسی طرح تمام اموات کو زندہ کروں گا۔\n§مسئلہ بعث بعد الموت پر موسیٰ علیہ السلام کے عصا کے واقعہ سے استدلال\nاس طرح اللہ تعالیٰ نے مسئلہ بعث بعد الموت پر ہمیں آگاہی فرمائی ہے موسیٰ علیہ السلام کے ساحروں کے ساتھ مناظرے والے واقعہ کے ساتھ کہ موسیٰ علیہ السلام کا عصا لکڑی تھی اللہ نے اس کو سانپ بنا دیا۔ پھر پھر اللہ کے حکم سے اس کو موسیٰ علیہ السلام نے پکڑا تو وہ لکڑی بن گئی۔ یعنی لکڑ کا سانپ کے ساتھ بدل جاتا پھر سانپ کا لکڑی سے بدل جانا پھر جادوگروں کے مقابلے کے وقت اس کا سانپ بن جانا اس کے بعد اس کا لکڑی بن جانا۔ اس واقعہ کو نقل کرنے میں تمام اہل ملک شریک ہیں۔ اللہ تعالیٰ نے واضح فرمایا کہ جو اللہ ایک چیز کی ماہیت بدل دینے پر قادر ہے وہ مردے کو زندہ کرنے پر کیوں قادر نہیں ہو سکتا؟\n§بعث بعد الموت پر واقعہ اصحاب کہف سے استدلال\nاور اسی طرح اللہ تعالیٰ نے اصحاب کہف کے واقعہ سے مسئلہ بعث بعد الموت پر دلیل قائم فرمائی ہے۔ جن کے کانوں پر اللہ تعالیٰ نے تین سو سال کے عرصہ سے زیادہ عرصہ تک مہر مار دی (یعنی موت کی نیند سلا دیا) پھر ان کو زندہ کیا تا کہ ان کی قوم ان کے حالات پر مطلع ہونے کے بعد اس بات پر دلیل پکڑیں کہ وہ ان کو جس مسئلہ بعث بعد الموت سے ڈراتے رہے وہ حق ہے اور لاریب ہے۔ ہم نے اپنی کتاب ’’البعث والنشور‘‘ کے شروع میں اس مسئلہ کی شرح و تفصیل میں بہت سے ارشاد بھی نقل کر دیئے ہیں۔\n§باب نمبر ۸\n§ایمان کا آٹھواں شعبہ\n§ایمان بالحشر\n§قبروں سے اٹھائے جانے کے بعد لوگوں کا دھرتی کے اس مقام پر جمع ہونا جو ان کے لئے مقرر ہے (اس کے ساتھ ایمان)\nجب تک اللہ تعالیٰ چاہے گا لوگ میدان حشر میں کھڑے رہیں گے۔ جب وہ وقت آ جائے گا جب اللہ تعالیٰ ان سے حساب لینے کا ارادہ فرمائیں گے تو اللہ تعالیٰ حکم دیں گے اور تمام اعمال نامے لائے جائیں گے جو کراماً کاتبین نے لکھے تھے لوگوں کے اعمال کے بارے میں۔ اور وہ لوگوں کو اس طرح دیئے جائیں گے کہ بعض کو سیدھے ہاتھ میں اور بعض کو الٹے ہاتھ میں یا پیٹھ کے پیچھے سے جن کو سیدھے ہاتھ میں اعمال نامے ملیں گے وہ سعید اور خوش نصیب ہوں گے۔ اور جن جن کو بائیں ہاتھ میں یا پیٹھ کے پیچھے سے ملیں گے وہ شقی اور بدنصیب ہوں گے اللہ تعالیٰ کا ارشاد ہے:\n§الا يظن اولئك انهم مبعوثون ليوم عظيم يوم يقوم الناس لرب العالمين۔ (المطففین ۳-۵)\nکیا یہ لوگ نہیں جانتے کہ اٹھائے بھی جائیں گے یعنی ایک بڑے سخت دن میں جس دن تمام لوگ رب العالمین کے سامنے کھڑے ہوں گے۔ اس آیت میں اللہ تعالیٰ نے یہ خبر دی ہے کہ قیامت کے دن لوگ اپنے قدموں پر کھڑے ہوں گے اور واضح فرمایا کہ اس دن قیام کے علاوہ ان کی اور کوئی حالت نہ ہوگی۔\n§قیامت میں لوگوں کا پسینے میں ڈوبنا\nہمیں حدیث بیان کی ہے حسن علوی نے، خبر دی ہے ہمیں ابو حامد نے اور وہ ابن شرقی ہیں۔ وہ کہتے ہیں ہمیں حدیث بیان کی محمد بن یحییٰ ذھلی نے۔ انہوں نے کہا ہمیں حدیث بیان کی ہے یعقوب بن ابراہیم بن سعد نے کہ ہمیں حدیث بیان کی ہے میرے والد نے صالح بن کیسان سے، انہوں نے کہا ہمیں حدیث بیان کی ہے نافع نے یہ کہ عبد اللہ بن عمر نے فرمایا کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا تھا:\nيقوم الناس يوم القيامة لرب العالمين حتى يغيب احدهم في رشحه الى انصاف اذنيه\nقیامت کے دن لوگ رب العالمین کے سامنے کھڑے ہوں گے۔ یہاں تک کہ انسان اپنے کانوں کے نصف تک اپنے پسینے میں ڈوب جائے گا۔\nامام مسلم نے صحیح میں حدیث یعقوب سے اس کو روایت کیا ہے۔ (1)","",{"k":"(1) أخرجه مسلم (۲۱۹۶/۴) من طريق يعقوب۔ به۔"}],[243,"§قیامت میں سورج کا قریب ہو جانا\nہمیں خبر دی ہے ابو عبد اللہ حافظ نے کہ مجھے خبر دی ہے ابو بکر بن عبد اللہ نے کہ ہمیں خبر دی ہے حسن بن سفیان نے۔ ہمیں حدیث بیان کی حکم بن موسیٰ نے ہمیں حدیث بیان کی یحییٰ بن حمزہ نے عبد الرحمن بن یزید بن جابر سے، اس نے کہا مجھے حدیث بیان کی ہے سلیم بن عامر نے، انہوں نے کہا مجھے حدیث بیان کی مقداد بن اسود نے، انہوں نے کہا کہ میں نے سنا رسول اللہ صلی اللہ علیہ وسلم سے، فرماتے ہیں کہ قیامت کے دن سورج لوگوں کے قریب کر دیا جائے گا یہاں تک کہ ان کے قریب ہوگا جیسے ایک تہائی فرسنگ یا جیسے سرمہ کی سلائی۔ سلیم بن عامر نے کہا اللہ کی قسم میں نہیں جانتا کہ آپ نے میل سے کیا چیز مراد لی ہے لیکن زمین کی مسافت یا سرمہ کی سلائی جس سے آنکھ میں سرمہ لگایا جاتا ہے۔ فرمایا کہ لوگ اپنے پسینے میں اپنے اعمال کے حساب سے غرق ہوں گے۔ بعض ان میں سے اپنے ٹخنوں تک بعض گھٹنوں تک بعض اپنی کمر تک اور بعض لگام لگائے جائیں گے یعنی منہ تک پسینے میں ڈوبے ہوں گے۔ مقداد نے فرمایا کہ رسول اللہ صلی اللہ علیہ وسلم نے منہ تک پسینے کا اشارہ کیا، اس کو مسلم نے صحیح میں حکم بن موسیٰ سے روایت کیا ہے۔\nاور ہم نے اس سلسلے میں تمام احادیث کتاب البعث میں ذکر کر دی ہیں۔\nاللہ تعالیٰ کا ارشاد ہے:\nاعمال نامہ سب کے گلے میں لٹکا ہوا ہے\nوكل انسان الزمناه طائره في عنقه ونخرج له يوم القيامة كتاباً يلقاه منشوراً اقرأ كتابك كفى بنفسك اليوم عليك حسيباً۔ (سورۃ اسرائیل ۱۳-۱۴)\nہر انسان کے اعمال کا پرچہ (بصورت کتاب) ہم نے اس کی گردن میں لٹکا دیا ہے۔ ہم اس کے لئے قیامت کے دن ایک تحریر (وہ کتاب) نکالیں گے، جسے وہ کھلی ہوئی پائے گا۔ کہا جائے گا پڑھ لے تو اپنی کتاب تیرے نفس کے ساتھ تو ہی آج حساب کرنے والا کافی ہے۔\nاعمال لکھنے کے لئے فرشتے مقرر ہیں\nایک اور ارشاد ہے:\nان عليكم لحافظين كراماً كاتبين يعلمون ما تفعلون۔ (انفطار ۱۰)\nبے شک تمہارے اوپر محافظ مقرر ہیں جو عزت والے منشی ہیں، وہ جانتے ہیں تم جو کچھ کر رہے ہو۔\nہر بات کو فرشتے لکھتے ہیں\nعن اليمين وعن الشمال قعيد ما يلفظ من قول الا لديه رقيب عتيد۔ (ق ۱۷-۱۸)\nدائیں اور بائیں جانب بیٹھتے ہیں لکھ رہے ہیں۔ انسان کسی بھی بات کا تلفظ نہیں کرتا مگر اس کے پاس نگران تیار بیٹھا ہے۔\nاعمال نامے میں ہر چھوٹا بڑا عمل لکھا ہوا ہے\nاور ارشاد ہے:\nهذا كتابنا ينطق عليكم بالحق انا كنا نستنسخ ما كنتم تعملون۔ (الجاثیہ ۲۹)\nیہ (کتاب) ہماری تحریر ہے جو تمہارے اوپر سچ سچ بولتی ہے۔ بے شک ہم لکھا لیا کرتے تھے جو کچھ تم عمل کرتے تھے۔\nاور اللہ تعالیٰ نے اس بات کی بھی خبر دی ہے کہ جو لوگ اپنے اعمال نامے پڑھیں گے تو وہ یہ کہیں گے:\nما لهذا الكتاب لا يغادر صغيرة ولا كبيرة الا احصاها۔ (الکہف ۴۹)\nکیا ہوا اس کتاب کو نہ کسی چھوٹی کو چھوڑتی ہے نہ کسی بڑی بات کو بلکہ سب کو اس نے محفوظ کر رکھا ہے۔\nاعمال نامہ سیدھے ہاتھ میں ملا تو حساب آسان ہو گا ورنہ مشکل ہوگا\nجس کو نامہ اعمال دائیں ہاتھ میں ملے گا وہ کہے گا:\nهاؤم اقرؤا كتابيه اني ظننت اني ملاق حسابيه فهو في عيشة راضية في جنة عالية۔ (الحاقہ ۱۹-۲۳)\nآؤ میرا اعمال نامہ پڑھو میں یقین رکھتا ہوں کہ میں اپنے حساب کو ملنے والا ہوں۔ پس وہ شخص خوشی کی زندگی میں بہشت بریں میں ہوگا۔\nواما من اوتي كتابه بشماله فيقول ياليتني لم اوت كتابيه ولم ادر ما حسابيه ياليتها كانت القاضية۔ (الحاقہ ۲۵-۲۷)\nبہر حال جس شخص کو کتاب (اعمال نامہ) بائیں ہاتھ میں دیا جائے گا وہ کہے گا ہائے افسوس کہ میرا اعمال نامہ نہ دیا جاتا اور میں یہ بھی نہ جان سکتا ہے کہ میرا حساب کیا ہے؟ اے کاش وہی موت ہی مجھ سے نمٹ لیتی۔ (یعنی ہمیشہ ہمیشہ کے لئے مر چکا ہوتا)۔\nفاما من اوتي كتابه بيمينه فسوف يحاسب حساباً يسيراً وينقلب الى اهله مسروراً۔ واما من اوتي كتابه وراء ظهره فسوف يدعو ثبوراً۔ ويصلى سعيراً۔ (انشقاق ۷-۱۲)\nبہر حال جو شخص کہ اپنا اعمال نامہ اس کو سیدھے ہاتھ میں دیا گیا عنقریب آسان حساب لیا جائے گا اور وہ اپنے گھر والوں کی طرف خوش خوش لوٹے گا۔ بہر حال جس شخص کو اعمال نامہ اس کی پیٹھ کے پیچھے سے دیا گیا وہ عنقریب ہلاکت (موت) کو پکارے گا اور وہ جہنم میں داخل ہو گا۔\nلوگ جب ان صحیفوں کے ذریعے اپنے اپنے اعمال پر مطلع ہو جائیں گے تو انہیں کے ذریعے سے حساب لئے جائیں گے۔ یہ شاید اس لئے ہوگا کہ لوگ جب قبروں سے اٹھیں گے تو انہیں اپنے اپنے اعمال یاد نہیں ہوں گے۔ اس لئے اللہ تعالیٰ فرماتے ہیں:\nيوم يبعثهم الله جميعاً فينبئهم بما عملوا احصاه الله ونسوه۔ (مجادلہ ۶)\nجس دن اللہ تعالیٰ ان سب کو قبروں سے اٹھائے گا پس خبر دے گا ان کو اس کی جو کچھ انہوں نے اعمال کئے تھے۔ اللہ نے ان کو یاد اور محفوظ کر رکھا تھا اور وہ اس کو بھول چکے تھے۔ لہذا جب وہ ان اعمال کو یاد کر کے ان سے واقف ہو جائیں گے، ان کے بارے میں حساب لئے جائیں گے۔\nاور محاسبہ کی کیفیت کے بارے میں کئی احادیث وارد ہوئی ہیں، جنہیں ہم نے اپنی کتاب البعث والنشور میں ذکر کر دیا ہے۔ بعض ان میں سے یہ ہیں: (1)","",{"k":"(1) سليم بن عامر هو: أبو يحيى الخبائري۔ أخرجه مسلم (۲۱۹۶/۴)، والترمذي (۲۴۲۱) من طريق عبد الرحمن بن يزيد بن جابر۔ به وقال الترمذي صحيح۔"}],[244,"§لوگو آگ سے بچو اگر چہ آدھی کھجور سے ہو\nہمیں خبر دی ہے ابو الحسین بن بشران نے، انہوں نے کہا ہمیں خبر دی ہے ابو جعفر محمد بن عمرو رزاز نے کہ انہیں حدیث بیان کی ہے عبد اللہ بن محمد بن شاکر نے، انہوں نے کہا ہمیں حدیث بیان کی ہے ابو اسامہ نے، انہوں نے کہا ہمیں حدیث بیان کی ہے اعمش نے چشمہ بن عبد الرحمن سے، انہوں نے عدی بن حاتم سے، انہوں نے کہا کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: تم میں سے ہر انسان کے ساتھ اللہ تعالیٰ کلام فرمائیں گے۔ اللہ کے اور بندے کے درمیان نہ کوئی پردہ حائل ہوگا اور نہ ہی کوئی ترجمان ہوگا۔ چنانچہ انسان اپنے دائیں طرف دیکھے گا مگر کچھ بھی نظر نہیں آئے گا۔ سوائے اس عمل کے جو آگے بھیجا تھا۔ پھر بائیں جانب دیکھے گا مگر کچھ بھی نظر نہیں آئے گا سوائے اس عمل کے جو آگے بھیجا تھا۔ آگے دیکھے گا تو آگ ہی آگ نظر آئے گی۔ لوگو آگ سے بچو اگر چہ کھجور کے آدھے دانے کے ساتھ ہی سہی۔ اس کو بخاری نے صحیح میں یوسف بن ابی موسیٰ بن ابی اسامہ نے نقل کیا ہے۔\nاس حدیث میں اس بات کی دلیل ہے کہ اللہ تعالیٰ تمام مکلفین کا حساب خود لے گا اور سب کو ایک ساتھ مخاطب کرے گا۔ ایک کے بعد ایک اور باری باری خطاب نہیں کرے گا اور نبی کریم صلی اللہ علیہ وسلم کی تمام احادیث بھی اس پر دلالت کرتی ہیں۔ ہاں اہل رحمت کے ساتھ اس کی ہمکلامی ان کی بشارت و کرامت میں اضافہ کرے گا اور اہل عذاب کے ساتھ ہمکلامی ان کی حسرت اور ان کے خسارے میں اضافہ کرے گی۔\nارشاد باری تعالیٰ ہے:\nالم اعهد اليكم يا بني ادم ان لا تعبدوا الشيطان انه لكم عدو مبين۔ (یسٓ ۶۰)\nاے اولاد آدم کیا میں نے تم سے عہد نہیں لیا تھا کہ تم شیطان کی عبادت نہ کرنا وہ تمہارا واضح دشمن ہے۔\nعلاوہ اس کے جتنے کتاب وسنت میں ارشادات آئے ہیں۔ اور یہ بھی کہا گیا ہے کہ اللہ تعالیٰ فرشتوں کو مخلوق کے محاسبہ کرنے کا حکم دیں گے وہ اللہ کے حکم کے ساتھ حساب لیں گے اور یہ بھی کہا گیا ہے کہ اہل ایمان کے حساب کی ذمہ داری اللہ تعالیٰ اپنے ذمہ لیں گے اور کفار کا حساب فرشتوں کے ذمے لگائیں گے۔ اور ظاہر کتاب وسنت جس چیز پر دلالت کرتے ہیں وہ وہی ہے جو ہم ذکر کر چکے ہیں اور اس بارے میں تمام اقوام میں سے صحیح ترین قول کی طرف اشارہ کر چکے ہیں۔\nجب حساب و کتاب مکمل ہو جائے گا تو پھر اعمال کا وزن کیا جائے گا۔ اس لئے کہ وزن کرنا جزا عطا کرنے کے لئے ہے۔\nابو یوسف زاہد کا قول:\nہمیں خبر دی ہے ابو عبد اللہ حافظ نے کہ میں نے سنا ابو اسحاق ابراہیم بن محمد بن یحییٰ سے، انہوں نے کہا کہ میں نے سنا عبد اللہ سعد بن ابراہیم عبدوی سے، وہ کہتے تھے میں نے سنا ابراہیم بن ابی طالب سے، وہ کہتے تھے میں نے سنا اسحاق بن ابراہیم بن مخلد حنظلی سے، وہ کہتے تھے میں نے سنا اپنے والد سے، وہ کہتے تھے میں نے سنا ابو سفیان زاہد سے:\nوہ کہتے تھے میں یہ پسند نہیں کروں گا کہ ہمارے حساب کی ذمہ داری غیر اللہ کے ذمہ ہے۔ اس لئے کہ کریم ذات ہی درگزر کرے گی۔\nفرشتے کیا معاف کر سکتے ہیں؟ (1)","",{"k":"(1) أخرجه البخاري (۱۲۲/۹) عن يوسف بن موسى۔ به۔"}],[245,"ہمیں خبر دی ہے ابو الحسین بن بشران نے کہ ہمیں خبر دی حسین بن صفوان نے، انہوں نے کہا ہمیں حدیث بتائی ہے، اس نے کہا مجھے حدیث بتائی ہے حسین بن عمرو نے یحییٰ بن ہمان سے، انہوں نے کہا سفیان ثوری نے کہا:\nمیں یہ پسند نہیں کروں گا کہ میرا حساب میرے والد کے سپرد ہو، اس لئے کہ میرا رب میرے لئے میرے والد سے بہتر ہے۔\n’’امام بیہقی کا قول‘‘:\nامام بیہقی فرماتے ہیں:\nمذکورہ مفہوم ایک مسند حدیث میں مروی ہے۔ لیکن قوی خیال ہے کہ وہ موضوع روایت ہے۔ میں نے اس کے نقل کرنے کی جسارت نہیں کی تھی۔ پھر میں نے اسے مذکورہ حضرات کے ہاں شہرت کی بناء پر نقل کیا ہے۔ میں اس کی ذمہ داری سے بری ہوں۔ (1)","",{"k":"(1) أخرجه البيهقي في الشعب (۲۱۹/۲ ب) من طريق ابن أبي الدنيا أيضاً۔"}],[246,"§ایک متروک الحدیث راوی سے اعرابی کا واقعہ\nہمیں خبر دی ہے ابو عبد اللہ حافظ نے ’’التاریخ‘‘ میں کہ ہمیں بات بیان کی ہے ابو محمد حسن بن محمد بن الحق ازہری نے، اس نے کہا ہمیں بات بیان کی ہے محمد زکریا غلابی نے، اس نے کہا ہمیں حدیث بیان کی ہے عبد اللہ بن محمد عمی نے، انہوں نے کہا ہمیں بات بتائی ہے میرے والد نے اپنے چچا سے، انہوں نے ربیعہ بن ابو عبد الرحمن سے، انہوں نے سعید بن مسیب سے، انہوں نے ابو ہریرہ سے کہ انہوں نے کہا کہ ایک اعرابی نے کہا یا رسول اللہ مخلوق کا حساب کون لے گا قیامت کے دن؟ حضور صلی اللہ علیہ وسلم نے اسے خوب جواب دیا کہ اللہ تعالیٰ حساب لے گا۔ اعرابی نے سوال کیا واقعی اللہ تعالیٰ حساب لے گا؟ حضور صلی اللہ علیہ وسلم نے جواب دیا، ہاں اللہ تعالیٰ حساب لے گا۔ تو اعرابی نے کہا، رب کعبہ کی قسم پھر ہم نجات پا جائیں گے۔ حضور صلی اللہ علیہ وسلم نے سوال کیا، اعرابی وہ کیسے؟ اعرابی نے جواب دیا، اس لئے کریم جب قادر ہے تو وہ معاف کر دے گا۔ (1)","",{"k":"(1) أخرجه ابن النجار كما في كنز العمال (۳۹۷۴۹) عن أبي هريرة۔"}],[247,"ہمیں خبر دی ہے ابو الحسن بن علی بن علی بن محمد مقری اسفرائنی نے اس کے بارے میں کہا ہے کہ ہمیں حدیث بیان کی ہے حسن بن محمد بن الحق نے، پھر اس نے اپنی اسناد کے ساتھ مذکور کی مثل بات ذکر کی ہے۔ اس میں محمد بن زکریا غلابی کا تفرد ہے۔ عبید اللہ بن محمد بن عائشہ سے اور غلابی خود بھی متروک الحدیث ہے۔\nارشاد باری تعالیٰ:\nاللہ تعالیٰ نے ارشاد فرمایا ہے کہ محاسبہ انبیاء اور شہداء کی شہادت کے ساتھ ہوگا۔\nارشاد فرمایا:\nوجئ بالنبيين والشهداء وقضي بينهم بالحق وهم لا يظلمون۔ (الزمر ۶۹)\nانبیاء اور شہداء کو لایا جائے گا اور لوگوں کے مابین انصاف کے ساتھ فیصلہ کیا جائے گا۔ ان پر ظلم نہیں ہو گا۔\nقیامت میں رسولوں اور امتیوں سے ایک دوسرے کی بابت سوال ہونا ہے\nایک اور مقام پر ارشاد ہے:\nفكيف اذا جئنا من كل امة بشهيد وجئنا بك على هؤلاء شهيداً۔ (النساء ۴۱)\nاس وقت کیا حال ہوگا جب ہم ہر امت سے ایک گواہ لائیں گے اور (اے محمد صلی اللہ علیہ وسلم) آپ کو ان پر بطور گواہ لائیں گے۔\nاس دوسری آیت میں لفظ شہید یعنی گواہ سے مراد نبی کریم صلی اللہ علیہ وسلم ہیں، اس لئے کہ ہر امت کا گواہ اس امت کا اپنا نبی ہوگا اور پہلی آیت میں شہداء یعنی گواہوں سے مراد ظاہر یہی ہے کہ اعمال کے لکھنے والے فرشتے و کاتب مراد ہیں۔ ہر امت اور اس کا رسول حاضر کیا جائے گا اور قوم سے سوال کیا جائے گا کہ:\nماذا اجبتم المرسلين؟\nتم لوگوں نے رسولوں کو کیا جواب دیا تھا؟\nاور رسولوں سے پوچھا جائے گا کہ:\nماذا اجبتم؟\nتمہیں امتیوں سے کیا جواب ملا تھا۔\nاللہ کے رسول جواب دیں گے:\nلا علم لنا انك انت علام الغيوب۔ (المائدہ ۱۰۹)\nہمیں کوئی علم نہیں، بے شک تو ہی غیب کو جانے والا ہے۔\n(اس آیت کا مطلب ہے کہ گویا کہ انبیاء و رسول بھول چکے ہوں گے کہ لوگوں نے ان کو کیا کیا جواب دیئے تھے اور ان کے دلوں کی گہرائیوں میں اللہ تعالیٰ کی ہیبت بیٹھ چکی ہوگی۔ لہذا اسی ساعت میں وہ جواب بھول جائیں گے۔ پھر اللہ تعالیٰ اپنی رحمت سے ان کو مضبوط اور ثابت قدم بنائیں گے اور ان کے لئے یادداشت بیان فرمائیں گے، لہذا پھر وہ اس بات کی شہادت دیں گے جو ان کی امتوں نے ان کو جواب دیئے تھے۔\nامام بیہقی فرماتے ہیں:\nبے شک بعض امت اپنے رسول کو جھٹلا دے گی اور کہے گی ہمارے پاس کوئی ڈرانے والا نہیں آیا تھا۔ (1)","",{"k":"(1) ميزان الاعتدال (۵۵۰/۳ رقم ۷۵۳۷) قال الذهبي: محمد بن زكريا الغلابي البصري الأخباري أبو جعفر عن عبد الله بن رجاء الغداني وأبي الوليد والطبقة وعنه أبو القاسم الطبراني وطائفة وهو ضعيف وقد ذكره ابن حبان في كتاب الثقات وقال: يعتبر بحديثه إذا روى عن ثقة وقال ابن منده تكلم فيه وقال الدارقطني يضع الحديث۔"}],[248,"§امت محمدیہ اور حضرت نوح علیہ السلام کی تائید\nہمیں خبر دی ہے ابو عبد اللہ حافظ نے کہ ہمیں حدیث بیان کی ہے ابو عبد اللہ محمد بن یعقوب نے، انہوں نے کہا ہمیں بات بیان کی ہے محمد بن عبد الوہاب فراء نے، انہوں نے کہا ہمیں خبر دی ہے جعفر بن عون نے، انہوں نے کہا ہمیں حدیث بیان کی ہے اعمش نے ابو صالح سے، انہوں نے سیدنا ابو سعید خدری رضی اللہ عنہ سے، انہوں نے کہا کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا:\nکہ حضرت نوح علیہ السلام قیامت کے دن بلائے جائیں گے اور ان سے پوچھا جائے گا کہ کیا آپ نے اللہ کا پیغام لوگوں کے پاس پہنچا دیا تھا۔ وہ عرض کریں گے، جی ہاں، میں نے پہنچا دیا تھا۔ لہذا آپ کی امت کو طلب کیا جائے گا اور ان سے پوچھا جائے گا کہ کیا نوح علیہ السلام نے تم لوگوں کو اللہ کا پیغام پہنچایا تھا؟ وہ جواب دیں گے کہ ہمارے پاس نہ ہی کوئی ڈرانے والا آیا تھا اور نہ ہی کوئی ہمارے پاس آیا تھا۔ حضور صلی اللہ علیہ وسلم نے فرمایا کہ حضرت نوح علیہ السلام سے سوال ہوگا کہ آپ کے گواہ کون ہے؟ حضور صلی اللہ علیہ وسلم نے فرمایا کہ نوح علیہ السلام جواب دیں گے کہ میرے گواہ محمد صلی اللہ علیہ وسلم ہیں اور ان کی امت ہے۔ پھر (حضور صلی اللہ علیہ وسلم نے فرمایا) کہ تم لوگوں کو (اے امت محمدیہ) لایا جائے گا اور تم لوگ یہ گواہی دو گے کہ حضرت نوح علیہ السلام نے اللہ کا پیغام اپنی امت کو پہنچایا تھا، یہی بات مذکور ہے اللہ تعالیٰ کے اس ارشاد کے اندر:\nوكذلك جعلناكم امة وسطاً لتكونوا شهداء على الناس ويكون الرسول عليكم شهيداً۔ (البقرہ ۱۴۳)\nاسی طرح ہم نے تمہیں بہترین امت بنایا ہے تا آنکہ تم لوگوں پر گواہ ہو جاؤ اور رسول تمہارے اوپر گواہ ہو جائے۔\nبخاری نے اس کو روایت کیا ہے اسحاق بن منصور سے جعفر بن عون سے۔ اور اسی مفہوم کے ساتھ اس کو روایت کیا ہے ابو اسامہ نے اعمش سے اور روایت کیا ہے اس کو ابو معاویہ نے اعمش سے۔ انہوں نے حدیث میں فرمایا:\nکوئی نبی قیامت کے دن ایسا بھی آئے گا کہ اس کے ساتھ صرف تین امتی ہوں گے اور بعض کے ساتھ چار امتی ہوں گے۔ بعض کے ساتھ صرف دو امتی ہوں گے۔ یہاں تک کہ کوئی نبی ایسا بھی آئے گا جس کے ساتھ ایک بھی امتی نہیں ہوگا۔ ان نبیوں سے پوچھا جائے گا کہ کیا آپ لوگوں نے اللہ کا پیغام پہنچایا تھا؟ وہ کہیں گے، جی ہاں، ہم نے پیغام پہنچایا تھا۔ حضور صلی اللہ علیہ وسلم نے فرمایا کہ پھر ان کی قوم کو بلایا جائے گا، ان سے پوچھا جائے گا کہ کیا ان نبیوں نے تمہیں اللہ کا پیغام دیا تھا۔ وہ منع کر دیں گے۔ حضور صلی اللہ علیہ وسلم نے فرمایا کہ پھر نبیوں سے پوچھا جائے گا کون تمہارے بارے میں گواہی دیتا ہے کہ آپ نے اللہ کا پیغام پہنچایا تھا؟ نبی جواب دیں گے کہ امت محمد صلی اللہ علیہ وسلم گواہی دے گی۔ حضور صلی اللہ علیہ وسلم نے فرمایا کہ پھر امت محمد صلی اللہ علیہ وسلم بلائی جائے گی اور آپ صلی اللہ علیہ وسلم کی امتی گواہی دیں گے کہ ان نبیوں نے اللہ کا پیغام پہنچایا تھا اس لئے کہ یہ امت قرآن مجید میں تمام نبیوں کے تبلیغ کرنے کی وضاحت پڑھ چکے تھے حضور صلی اللہ علیہ وسلم نے فرمایا کہ پھر اس امت کے لوگوں سے پوچھا جائے کہ تمہیں اس بات کا کیسے علم ہے کہ نبیوں نے اپنی امتوں کو اللہ کا پیغام پہنچایا تھا؟ لہذا محمد صلی اللہ علیہ وسلم کے امتی جواب دیں گے کہ ہمارے پاس ہمارے رسول (صلی اللہ علیہ وسلم) کتاب لے کر آئے تھے اور انہوں نے ہمیں یہ خبر دی تھی کہ نبیوں نے اللہ کا پیغام اپنی امتوں کو دیا تھا۔ لہذا ہم نے اس کی تصدیق کی تھی۔ حضور صلی اللہ علیہ وسلم نے فرمایا کہ ان سے کہا جائے گا کہ تم لوگوں نے سچ کہا۔ حضور صلی اللہ علیہ وسلم نے فرمایا کہ یہی بات اللہ کی کتاب میں اس آیت میں ہے:\nوكذلك جعلناكم امة وسطاً لتكونوا شهداء على الناس ويكون الرسول عليكم شهيداً۔ (البقرہ ۱۴۳)\nاسی طرح ہم نے تمہیں امت معتدل بنایا ہے تا کہ تم لوگوں پر گواہ بنو اور پیغمبر آخر الزمان تم پر گواہ بنیں۔ (1)","",{"k":"(1) أخرجه البخاري (۳۱۶/۱۳) فتح عن إسحاق۔ به۔"}],[249,"ہمیں اس کی خبر دی ہے محمد بن عبد اللہ حافظ نے کہ ہمیں حدیث بیان کی ہے ابو العباس محمد بن یعقوب نے، انہوں نے کہا ہمیں حدیث بیان کی ہے احمد بن عبد الجبار نے، انہوں نے کہا ہمیں حدیث بیان کی ہے ابو معاویہ نے، پھر اس حدیث کو ذکر کیا ہے۔\nاعمال کے صحیفے اور فرشتے گواہ ہوں گے\nیہ تو وہ تفصیل تھی جو نبیوں اور ان کی امتوں کے مابین سوال و جواب اور شہادت اور گواہوں کے بارے میں تھے۔ باقی رہا ہر قوم کا انفرادی طور پر معاملہ تو ہر امت اور ہر قوم پر انفرادی طور پر گواہ ان کے اعمال کا صحیفہ ہوگا اور اس کے کاتب فرشتے یعنی اعمال لکھنے والے گواہ ہوں گے۔ اس لئے کہ ہر شخص کو دنیا میں یہ بتا دیا گیا تھا کہ اس پر دو فرشتے مقرر ہیں، جو اس کے اعمال کی حفاظت کرتے ہیں اور ان کو لکھ لیتے ہیں۔ (لہذا وہ فرشتے گواہی دیں گے اور ان کی وہ تحریر اور اعمال نامے کے صحیفے شہادت دیں گے)۔ اس کے علاوہ انسانی اعضاء و جوارح بھی اپنے خلاف گواہی دیں گے۔ اپنے اعضاء کے انسان کے خلاف شہادت دینے کی خبر اللہ تعالیٰ نے قرآن مجید میں دی ہے۔\nارشاد ہوا:\nانسان کے خلاف اس کے اپنے اعضاء گواہی دیں گے\nيوم تشهد عليهم السنتهم وايديهم وارجلهم بما كانوا يعملون۔ (النور ۲۴)\n(قیامت کا دن وہ ہو گا) جس دن (لوگوں کے خلاف) ان کی زبانیں اور ان کے ہاتھ اور ان کے پیر گواہی دیں گے جو کچھ وہ عمل کر رہے تھے۔\nنیز ارشاد باری ہے:\nوما كنتم تسترون ان يشهد عليكم سمعكم ولا ابصاركم ولا جلودكم ولكن ظننتم ان الله لا يعلم كثيراً مما تعملون۔ (فصلت ۲۲)\nاور تم اس بات کے خوف سے تو پردہ نہیں کرتے تھے کہ تمہارے کان اور تمہاری آنکھیں اور تمہارے چمڑے تمہارے خلاف شہادت دیں گے، بلکہ تم یہ خیال کرتے تھے کہ اللہ کو تمہارے بہت سے عملوں کی خبر نہیں ہے۔\nوقالوا لجلودهم لم شهدتم علينا قالوا انطقنا الله الذي انطق كل شيء۔ (فصلت ۲۱)\nوہ اپنے چمڑوں (یعنی اپنے اعضاء) سے کہیں گے کہ تم نے ہمارے خلاف کیوں شہادت دی ہے؟ وہ کہیں گے کہ جس اللہ نے سب چیزوں کو گویائی بخشی، اسی نے ہم کو بھی گویائی دی (اور گواہی دینے کا حکم دیا)۔\nاليوم نختم على افواههم وتكلمنا ايديهم وتشهد ارجلهم بما كانوا يكسبون۔ (یسٓ ۶۵)\nآج ہم ان کے مونہوں پر مہر لگا کر بند کر دیں گے اور ہم ان کے ہاتھوں کو بلوائیں گے اور ان کے پیر گواہی دیں گے اس کی جو کچھ وہ عمل کرتے تھے۔\nہم نے حضرت ثابت کی روایت میں سیدنا انس بن مالک سے روایت کیا ہے کہ ہم رسول اللہ صلی اللہ علیہ وسلم کے ساتھ تھے۔ آپ ہنس پڑے۔ پھر خود فرمایا تمہیں معلوم ہے کہ میں کیوں ہنسا؟ ہم نے کہا کہ اللہ اور اس کا رسول بہتر جانتے ہیں۔ فرمایا کہ بندے کے اپنے رب سے مخاطب ہونے سے، بندہ کہے گا کہ اے میرے رب کیا آپ مجھے ظلم سے پناہ دیں گے؟ اللہ تعالیٰ فرمائیں گے، جی ہاں ضرور۔ بندہ کہے گا میں اپنے نفس پر بخششیں نہیں کرتا مگر گواہ کے ساتھ جو مجھ سے ہوا۔ اللہ تعالیٰ فرمائیں گے:\nكفى بنفسك اليوم عليك شهيداً وبالكرام الكاتبين شهوداً\nتو آج اپنا آپ ہی کافی ہے گواہ اور کراماً کاتبین فرشتے گواہ ہیں۔\nپھر اس کے مکنہ پر مہر لگا دی جائے گی اور اس کے اعضاء سے کہا جائے گا کہ تم بولو، سو وہ اس کے اعمال کے بارے میں بولیں گے۔ پھر بندے اور کلام کے مابین تخلیہ کر دیا جائے گا۔ پھر بندہ کہے گا دوری ہو، دوری ہو، میں تمہارا ہی تو دفاع کرتا تھا۔"],[250,"ہمیں خبر دی ہے ابو عبد اللہ حافظ نے کہ ہمیں حدیث بیان کی ہے ابو العباس بن یعقوب نے کہ ہمیں حدیث بیان کی ہے محمد بن الحق صنعانی نے، وہ کہتے ہیں کہ مجھے حدیث بیان کی ہے ابو بکر بن ابو نضر نے اجھی سے، انہوں نے سفیان سے، انہوں نے عبید بن مکتب سے، انہوں نے فضیل بن عمرو سے، انہوں نے شعبی سے، انہوں نے انس بن مالک سے، پھر اس نے مذکورہ روایت ذکر کی ہے۔ امام مسلم نے اس کو صحیح مسلم میں ابو بکر بن نضر سے روایت کیا ہے۔\nہم نے سیدنا ابو ہریرہ رضی اللہ عنہ کی حدیث میں نبی کریم صلی اللہ علیہ وسلم سے حدیث رؤیت میں روایت کیا ہے کہ آپ صلی اللہ علیہ وسلم نے فرمایا: اللہ تعالیٰ بندے سے ملیں گے اور فرمائیں گے کہ اے فلاں بن فلاں، کیا میں نے تجھے عزت نہیں بخشی؟ اور تجھے سرداری دی، تجھے جوڑا بنایا، تیرے اونٹ اور گھوڑے تابع فرماں کر دیئے، جن کی گردن جھکا کر تم ان پر سوار ہوتے ہو اور اس سے اپنی حفاظت کا سامان کرتے ہو۔ بندہ جواب دے گا، جی ہاں یا رب۔ پھر اللہ تعالیٰ فرمائیں گے تیرا کیا یہ یقین تھا کہ تو مجھ سے ملاقات کرے گا؟ بندہ عرض کرے گا کہ نہیں، میرا یہ خیال نہیں تھا۔ لہذا اللہ تعالیٰ فرمائیں گے کہ آج میں تجھے اس طرح بھلا دیتا ہوں جس طرح تو نے مجھے بھلا دیا تھا۔ پھر دوسرے شخص سے ملیں گے اور اس کے ساتھ بھی پہلے جیسے سوال و جواب کریں گے۔ وہ بھی اسی طرح جواب دے گا۔ پھر تیسرے شخص سے ملاقات کریں گے اور اس کے ساتھ بھی پہلے دو کی طرح سوال و جواب کریں گے، مگر وہ میں یہ کہے گا کہ اے اللہ میں تیرے ساتھ ایمان لایا اور تیری کتاب کے ساتھ اور تیرے رسول کے ساتھ اور میں نے نمازیں پڑھیں، روزے رکھے، صدقے کئے۔ اس سے کہا جائے گا کہ اب ہم تیرے اوپر اپنا گواہ اٹھائیں گے۔ وہ انسان دل ہی دل میں سوچے گا کہ کون میرے اوپر کوئی شہادت دے گا۔ پھر اس کے منہ پر مہر کر دی جائے گی اور اس کی ران سے کہا جائے گا تو بول۔ لہذا اس کی ران بولے گی اور اس کا گوشت اور اس کی ہڈی اس کے عمل کے بارے میں کہ اس نے کیا کیا۔ یہ اس لئے کہ وہ اپنے نفس سے مجبور ہو جائے اور یہ وہی منافق ہوگا اور یہ وہی شخص ہو گا جس پر اللہ تعالیٰ ناراض ہوگا۔ (1)","",{"k":"(1) أخرجه مسلم (۲۲۸۰/۴) عن أبي بكر بن النضر بن أبي النضر۔ به۔"}],[251,"ہمیں اس کی خبر دی ہے محمد بن عبد اللہ نے کہ ہمیں حدیث بیان کی ہے ابو بکر بن اسحاق نے کہ ہمیں حدیث بیان کی ہے بشر بن موسیٰ نے، انہوں نے کہا ہمیں حدیث بیان کی ہے حمید نے کہ ہمیں حدیث بیان کی ہے سفیان نے کہ ہمیں حدیث بیان کی ہے سہیل بن ابی صالح نے اپنے باپ سے، انہوں نے ابو ہریرہ رضی اللہ عنہ سے، انہوں نے نبی کریم صلی اللہ علیہ وسلم سے وہی مذکورہ حدیث۔ اور یہی حدیث مسلم میں بھی ہے۔\nاس حدیث میں اس بات پر دلالت ہے کہ قیامت میں بعض لوگوں کے خلاف ان کی زبانیں شہادت دیں گی (اور بعض لوگ اپنے غلط اعمال سے انکار کریں گے تو ان کے منہ پر مہر کر دی جائے گی اور ان کے خلاف ان کے اعضاء و جوارح گواہی دیں گے۔ عین ممکن ہے کہ یہ انکار منافقین کی طرف سے ہو اور جیسے کہ سیدنا ابو ہریرہ رضی اللہ عنہ کی روایت میں ہے اور یہ بھی عین ممکن ہے کہ منافقوں کی طرف سے ہو اور تمام کافروں کی طرف سے ہو جن کے باری میں اللہ چاہے گا کہ جب وہ دیکھیں گے قیامت کے دن اللہ تعالیٰ اہل اخلاص کے گناہوں کو معاف فرما رہے ہیں اور اللہ تعالیٰ کے لئے کوئی گناہ بڑا نہیں ہے جس کو وہ نہ بخشیں، سوائے شرک کے تو یہ لوگ آپس میں کہیں گے کہ ہمارا رب گناہوں کو معاف فرما رہا ہے، لیکن شرک معاف نہیں کر رہا، لہذا سب آ جاؤ ہم مل کر کہیں گے کہ ہم لوگ گناہگار تھے لیکن مشرک نہیں تھے۔ جب وہ شرک کو چھپائیں گے تو اللہ تعالیٰ حکم دیں گے کہ ان کے منہ پر مہر کر دو، لہذا ان کے منہ سیل بمہر کر دیے جائیں گے۔ پھر ان کے ہاتھ بولیں گے اور ان کے پیر شہادت دیں گے کہ وہ شرک کرتے تھے اور فلاں فلاں عمل کرتے تھے۔ اب مشرک سمجھ جائیں گے کہ اللہ تعالیٰ سے کوئی بات چھپ نہیں سکتی، یہی ارشاد باری ہے اس آیت میں:\nيومئذ يود الذين كفروا وعصوا الرسول لو تسوى بهم الارض ولا يكتمون الله حديثاً۔ (النساء ۴۲)\nقیامت کے دن کافر اور رسول کے نافرمان چاہیں گے کہ کاش کہ ان پر زمین برابر کر دی جاتی اور وہ اللہ تعالیٰ سے کوئی بات نہیں چھپا سکیں گے۔\nاور یہی مفہوم ہے اس حدیث کا جسے ہم نے روایت کیا ہے سعید بن حبیب سے ابن عباس سے کہ وہ اس بارے میں سوال کئے گئے تھے تو انہوں نے یہی ذکر فرمایا۔\nگناہگاروں کے گناہ کے بارے میں زمین گواہی دے گی\nاور اللہ تعالیٰ نے سورۃ زلزلت میں ارشاد فرمایا کہ:\nيومئذ تحدث اخبارها۔ (زلزلہ ۴)\nقیامت کے دن زمین اپنی خبریں بیان کر دے گی۔\nہم سیدنا ابو ہریرہ رضی اللہ عنہ سے مرفوعاً روایت کر چکے ہیں کہ ان سے اس آیت کے بارے میں پوچھا گیا تھا تو انہوں نے فرمایا کہ ہر مرد اور عورت کے بارے میں زمین اس عمل کی شہادت دے گی جو اس کی پیٹھ پر کیا تھا، لہذا وہ اس طرح کہے گی کہ اس انسان نے فلاں فلاں دن فلاں فلاں کام کیا تھا، یہی ہیں اس کی خبریں جن کے بیان کرنے کی خبر قرآن نے دی ہے۔\nاور حضور صلی اللہ علیہ وسلم کی بہت سی احادیث ایسی ہیں جو اس امر پر دلالت کرتی ہیں کہ اہل ایمان کی کثیر تعداد جنت میں بغیر حساب کتاب کے داخل ہوں گے اور کثیر تعداد بڑا آسان حساب لئے جائیں گے اور کثیر تعداد سخت حساب لئے جائیں گے۔ (1)","",{"k":"(1) أخرجه مسلم (۲۲۷۹/۴-۲۲۸۰) عن محمد بن أبي عمر عن سفيان۔ به۔ وقوله (أي قل) قال النووي معناه أي فلان وهو ترخيم على خلاف القياس وقيل هي لغة بمعنى فلان حكاها القاضي۔"}],[252,"§وہ ستر ہزار خوش نصیب جو بغیر حساب کتاب جنت میں داخل ہوں گے\nہمیں خبر دی ہے محمد بن عبد اللہ حافظ نے کہ خبر دی ہے ابو جعفر بن علی بن دحیم شیبانی نے کہ ہمیں حدیث بیان کی ہے احمد بن حازم بن ابی غرزہ نے کہ ہمیں حدیث بیان کی ہے عبد اللہ بن محمد بن ابی شیبہ نے کہ ہمیں حدیث بیان کی ہے محمد بن فضیل نے کہ ہمیں حدیث بیان کی ہے حصین نے کہ میں نے سنا تھا سعید بن جبیر رضی اللہ عنہ سے، انہوں نے سیدنا ابن عباس رضی اللہ عنہ سے، انہوں نے رسول اللہ صلی اللہ علیہ وسلم سے کہ آپ نے فرمایا تھا:\nکہ میری امت کے ستر ہزار لوگ بغیر حساب کے جنت میں داخل کئے جائیں گے۔ اس کے بعد آپ گھر میں چلے گئے اور ان کے بارے میں کوئی وضاحت نہ فرمائی۔ لوگوں نے اپنی اپنی قیاس آرائیاں کیں اور بولے کہ ہم لوگ اللہ پر ایمان لائے ہیں، ہم نے اللہ کے رسول کی اتباع کی ہے، وہ لوگ ہم میں ہوں گے یا ہماری وہ اولادیں ہوں گی جو اسلام میں پیدا ہوئیں، ہم تو جاہلیت کے دور میں پیدا ہوئے تھے۔ یہ باتیں آپ صلی اللہ علیہ وسلم تک پہنچیں تو آپ صلی اللہ علیہ وسلم نے فرمایا کہ وہ لوگ وہ ہوں گے جنہوں نے کبھی داغ نہیں دلوائیں ہوں گے، جنہوں نے کبھی جادو منتر نہیں کروائے ہوں گے، جنہوں نے کبھی بدشگونی و بدفالی نہیں پکڑی ہوگی بلکہ محض اپنے رب پر توکل کئے ہوں گے۔ (یہ سن کر) سیدنا عکاشہ بن محصن نے عرض کی یا رسول اللہ صلی اللہ علیہ وسلم کیا میں ان میں سے ہوں گا؟ آپ صلی اللہ علیہ وسلم نے فرمایا، جی ہاں تو ان میں سے ہوگا۔ پھر ایک اور آدمی نے کہا، کیا میں بھی ان میں سے ہوں گا یا رسول اللہ؟ آپ صلی اللہ علیہ وسلم نے فرمایا عکاشہ تم سے اس اعزاز کے ساتھ سبقت لے گئے ہیں۔\nمسلم نے اس حدیث کو اپنی صحیح میں ابو بکر بن ابی شیبہ سے روایت کیا ہے۔\nاور بخاری نے اس حدیث کو عمران بن میسرہ سے، انہوں نے ابن الفضیل سے روایت کیا ہے۔\nحضور صلی اللہ علیہ وسلم کی دعا کی برکت سے ستر ہزار میں سے ہر ایک فرد کے ساتھ ستر ہزار کا داخلہ\nاور ہم نے اس حدیث کو عمرو بن حزم سے، انہوں نے نبی کریم صلی اللہ علیہ وسلم سے روایت کیا ہے کہ نبی کریم صلی اللہ علیہ وسلم لوگوں سے تین دن تک نظروں سے اوجھل رہے۔ صرف فرض نماز کے لئے باہر آتے تھے، آپ سے اس بارے میں دریافت کیا گیا تو آپ صلی اللہ علیہ وسلم نے فرمایا کہ میرے رب نے مجھ سے وعدہ فرمایا کہ میری امت میں سے ستر ہزار لوگوں کو بغیر حساب و کتاب کے جنت میں داخل کریں گے۔ میں گزشتہ تین روز میں مزید لوگوں کو بغیر حساب کے جنت میں داخلہ کی التجا کی ہے تو میں نے اپنے رب کو، پالنے والا، مجد و بزرگی والا اور کرم کرنے والا پایا ہے۔ اللہ تعالیٰ نے مجھے ستر ہزار میں سے ہر ایک بندے کے ساتھ ستر ستر ہزار کی تعداد جنت میں بغیر حساب کے داخلہ کے لئے دیئے ہیں۔ آپ صلی اللہ علیہ وسلم نے فرمایا کہ میں نے عرض کی اے رب میری امت اتنی بڑی تعداد کو پہنچ جائے گی؟ اللہ تعالیٰ نے فرمایا میں تیرے لئے یہ تعداد اہل دیہات سے مکمل کروں گا۔\nہم نے اس روایت کو کتاب البعث والنشور میں بھی درج کیا ہے۔ (1)","",{"k":"(1) أخرجه مسلم (۲۰۰/۱) عن ابن أبي شيبة۔ به۔ وأخرجه البخاري (۱۵۵/۱۰) فتح عن عمران بن ميسرة عن ابن فضيل۔ به۔"}],[253,"§جس سے مناقشہ کیا گیا وہ تباہ ہو جائے گا\nہمیں خبر دی ہے ابو عبد اللہ حافظ نے کہ ہمیں حدیث بیان کی ہے ابو بکر بن الحق نے بطور املاء کے کہ ہمیں حدیث بیان کی ہے ابو مسلم اور یوسف بن یعقوب نے، ان دونوں نے کہا کہ ہمیں حدیث بیان کی ہے سلیمان بن حرب نے، انہوں نے کہا ہمیں حدیث بیان کی ہے حماد بن زید نے ایوب سے، انہوں نے ابن ابی ملیکہ سے، انہوں نے سیدہ عائشہ رضی اللہ عنہا سے کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا:\nمن حوسب عذب\nجو شخص حساب لیا گیا وہ عذاب میں مبتلا کیا گیا۔\n(اس پر سیدہ عائشہ رضی اللہ عنہا نے سوال کیا) یا رسول اللہ صلی اللہ علیہ وسلم اللہ تعالیٰ کے اس فرمان کا پھر کیا مطلب ہوگا:\nفاما من اوتي كتابه بيمينه فسوف يحاسب حساباً يسيراً۔ (انشقاق ۷-۸)\nبہر حال جو شخص اپنا اعمال نامہ اپنے سیدھے ہاتھ میں دیا گیا، عنقریب وہ آسان حساب لیا جائے گا۔\nنبی کریم صلی اللہ علیہ وسلم نے جواباً ارشاد فرمایا کہ حساب یسیر سے مراد ہے صرف حساب پیش کرنا یا صرف بندے کا پیش ہونا ہے۔ لیکن جو شخص مناقشہ کیا گیا وہ ہلاک ہو گیا۔ (یعنی جس سے کیوں کے ساتھ سوال کیا گیا وہ ہلاک ہو جائے گا) اس لئے کہ کیوں کا جواب کسی کے پاس نہیں ہے۔ اس کو بخاری نے اپنی صحیح میں سلیمان سے روایت کیا ہے۔ اور مسلم نے اس کو ابو الربیع سے حماد سے روایت کیا ہے۔ (1)","",{"k":"(1) أخرجه البخاري (۶۹۷/۸) فتح عن سليمان بن حرب۔ به۔ ومسلم (۲۲۰۴/۴) عن أبي الربيع العتكي وأبي كامل قالا حدثنا حماد بن زيد۔ به۔"}],[254,"§آسان حساب اور مناقشہ کی وضاحت\nہمیں خبر دی ہے ابو عبد اللہ حافظ نے کہ ہمیں حدیث بیان کی ہے ابو العباس محمد بن یعقوب نے کہ ہمیں حدیث بیان کی ہے ابو زرعہ رازی الدمشقی نے کہ ہمیں حدیث بیان کی ہے احمد بن خالد وہمی نے کہ ہمیں حدیث بیان کی ہے محمد بن الحق نے۔ ہمیں خبر دی ہے ابو عبد اللہ حافظ نے کہ خبر دی ہے احمد بن جعفر قطیعی نے کہ ہمیں حدیث بیان کی ہے عبد اللہ بن احمد نے کہ مجھے حدیث بیان کی ہے میرے والد نے کہ ہمیں حدیث بیان کی ہے اسماعیل بن ابراہیم نے کہ ہمیں حدیث بیان کی ہے محمد بن اسحاق نے کہ مجھے حدیث بیان کی ہے عبد الواحد بن حمزہ بن عبد اللہ بن زبیر نے عباد بن عبد اللہ بن زبیر سے، انہوں نے سیدہ عائشہ رضی اللہ عنہا سے وہ فرماتی ہیں کہ میں نے سنا رسول اللہ صلی اللہ علیہ وسلم سے کہ آپ اپنی بعض نماز میں دعا کرتے تھے:\nاللهم حاسبني حساباً يسيراً\nاے اللہ میرا آسان حساب کیجیو۔\nفلما انصرف قلت يارسول الله ما الحساب اليسير؟\nآپ جب نماز پڑھ چکے تو میں نے عرض کی یا رسول اللہ! آسان حساب کیا ہوتا ہے؟\nآپ صلی اللہ علیہ وسلم نے فرمایا کہ کسی انسان کے نامہ اعمال کو دیکھ کر اس سے درگزر کر لیا جائے گا اور جس کے حساب میں کیوں؟ پوچھ لیا گیا وہ ہلاک ہو جائے گا۔ ہاں ہر وہ تکلیف جو کسی مومن کو پہنچتی ہے اللہ تعالیٰ اس کو اس انسان کے لئے کفارہ بنا دیتے ہیں حتی کہ وہ کانٹا جو اس کو چھبتا ہے وہ بھی کفارہ بنتا ہے۔ (1)","",{"k":"(1) أخرجه عبد الله بن أحمد (۴۸/۶)، الحاكم (۵۷/۱) من طريق أحمد بن حنبل بن إسماعيل۔ به وصححه الحاكم على شرط مسلم ووافقه الذهبي۔"}],[255,"§اللہ تعالیٰ کی طرف سے بندے کے ساتھ سرگوشی اور معافی\nہمیں خبر دی ہے ابو عمرو محمد بن عبد اللہ ادیب نے کہ خبر دی ہے ابو بکر اسماعیلی نے کہ مجھے خبر دی ہے حسن بن سفیان نے کہ ہمیں حدیث بیان کی ہے حدیہ بن خالد نے کہ ہمیں حدیث بیان کی ہے ھمام بن یحییٰ نے کہ ہمیں حدیث بیان کی ہے قتادہ نے صفوان بن محرز سے، انہوں نے کہا کہ میں سیدنا عبد اللہ بن عمر کے ہاتھ پکڑے ہوئے تھا ان کے پاس ایک آدمی آیا اور کہا آپ نے کیا سنا تھا رسول اللہ صلی اللہ علیہ وسلم سے کہ آپ بخوبی اور سرگوشی کے بارے میں کیا فرماتے تھے۔ آپ نے فرمایا میں نے یہ فرماتے ہوئے سنا تھا:\nاللہ تعالیٰ قیامت کے دن بندے کو اپنے قریب کریں گے۔ یہاں تک کہ اس پر اتنا سایہ رکھیں گے اور اس کو دیگر لوگوں سے چھپا دیں گے۔ پھر فرمائیں گے اے میرے بندے، کیا تم اپنا فلاں فلاں گناہ جانتے ہو؟ بندہ عرض کرے گا جی ہاں اے اللہ یہاں تک کہ جب اس سے اس کے گناہوں کا اقرار کرا لیں گے اور وہ دل ہی دل میں سوچے گا کہ آج وہ نہیں بچے گا، بس آج تو وہ تباہ ہو ہی گیا۔ اتنے میں اللہ تعالیٰ فرمائیں گے بندے میں نے دنیا میں تیرے گناہوں پر پردہ ڈالا تھا اور آج میں ان گناہوں کو معاف کر دیتا ہوں تیرے واسطے۔ اس کے بعد اس کو اپنے حساب کی کتاب دیا جائے گا۔ جہاں تک کافر اور منافق کا تعلق ہے تو ان کے بارے میں تو گواہ یہ کہیں گے یہی ہیں وہ لوگ جنہوں نے اپنے رب پر جھوٹ باندھے تھے۔ خبر دار اللہ کی لعنت ہے ظالموں پر۔\nاس کو بخاری نے روایت کیا ہے موسیٰ بن اسماعیل سے، انہوں نے ہمام سے اور بخاری و مسلم نے اس کو دوسرے طریقہ سے حضرت قتادہ سے بھی روایت کیا ہے۔\nامام بیہقی کا قول:\nامام بیہقی رحمۃ اللہ علیہ نے فرمایا کہ:\nمؤمن کو اللہ قریب کرے گا کا مطلب ہے اپنی خاص عنایت سے اور اپنے خاص کرم سے بندے کو مقرب بنا دے گا اور اس پر اپنا سایہ کر دے گا۔ مطلب ہے اپنا میلان اپنی شفقت اور اپنی رعایت مراد ہے۔\nحضرت ابن عطیہ کا ارشاد: (1)","",{"k":"(1) أخرجه البخاري (۹۶/۵) فتح عن موسى بن إسماعيل عن همام۔ به۔ وأخرجه البخاري (۳۵۳/۸) من طريق سعيد وهشام قال حدثنا قتادة۔ به۔ وأخرجه مسلم (۲۱۲۰/۴) من طريق هشام الدستوائي عن قتادة۔ به۔"}],[256,"ہمیں خبر دی ہے ابو سعید ابن ابی عمرو نے کہ خبر دی ہے ابو عبد اللہ صفار نے کہ ہمیں حدیث بیان کی ہے ابو بکر بن ابو الدنیا نے کہ ہمیں حدیث بیان کی ہے عبد الرحمن بن صالح نے کہ ہمیں حدیث بیان کی ہے جریر نے اشعث سے کہ ہمیں حدیث بیان کی ہے شمر بن عطیہ نے اللہ کے اس قول کے بارے میں:\n﴿ ان ربنا لغفور شكور ﴾ [فاطر ۳۴]\n’’بے شک ہمارا رب البتہ معاف کرنے والا، قبول کرنے والا ہے۔‘‘\nدراصل یہ اللہ تعالیٰ نے اہل جنت کا مقولہ بیان فرمایا ہے کہ وہ جنت میں داخلے کے بعد یہ کہیں گے، ابن عطیہ نے فرمایا کہ آیت کا مطلب ہے کہ اللہ تعالیٰ نے ان کے وہ عمل جو انہوں نے گناہ کئے تھے معاف کر دیئے ہیں اور ان کی وہ خیر قبول کر لی ہے جو اللہ تعالیٰ نے ان کو بتائی تھی اور انہوں نے اس پر عمل کئے تھے۔ لہذا اللہ تعالیٰ نے ان کو ان کے عمل کا ثواب دیا ہے۔\nسیدنا عبد اللہ بن عمر رضی اللہ عنہ کا ارشاد: (1)","",{"k":"(1) عزاه السيوطى فى الدر المنثور (۲۵۳/۵) لسعيد بن منصور وعبد بن حميد وابن أبى الدنيا وابن أبى حاتم والمصنف عن شمر بن عطية به."}],[257,"اور ہمیں خبر دی ہے ابو سعید نے کہ ہمیں حدیث بیان کی ہے ابو عبد اللہ نے کہ ہمیں حدیث بیان کی ہے ابن ابی الدنیا نے کہ ہمیں حدیث بیان کی ہے اسحاق بن ابراہیم نے کہ ہمیں حدیث بیان کی ہے سفیان بن عیینہ نے عمرو بن دینار سے، انہوں نے طاؤس سے، وہ کہتے ہیں میں نے سنا ہے سیدنا ابن عمر رضی اللہ عنہ سے، وہ فرماتے تھے:\nكل ابن ادم خطاء الا ما رحم الله\n’’آدم کی ساری اولاد گناہگار ہے، مگر جس پر اللہ نے رحم کیا۔ یعنی اللہ کی رحمت سے کوئی بچ گیا تو بچ گیا ورنہ سب گناہگار ہیں۔ (مترجم)‘‘\nحضرت حسن بصری رحمۃ اللہ علیہ کا ارشاد:"],[258,"فرمایا کہ خبر دی ہے ابن ابی الدنیا نے کہ ہمیں حدیث بتائی ہے سعدویہ نے ابن مبارک بن فضالہ سے، انہوں نے حسن سے، وہ کہتے تھے کہ:\nاللہ تعالیٰ اپنے بندے کو اس کے گناہ کی جزا نہیں دیتے، اللہ کی قسم اللہ تعالیٰ نے ہرگز کسی بندے کو خیر اور شر کی جزا اور بدلہ نہیں دیا مگر وہ ہلاک ہو گیا۔ لیکن جب اللہ تعالیٰ کسی بندے کے ساتھ بھلائی کا ارادہ کرتے ہیں تو اس کی نیکیاں دوگنی کر دیتے ہیں اور اس کی غلطیاں اس سے ساقط کر دیتے ہیں۔\nشیخ حلیمی کا ارشاد:\nشیخ حلیمی رحمۃ اللہ علیہ نے فرمایا کہ اہل ایمان میں سے جو شخص اللہ کی رحمت سے قریب تر ہوگا اس کو بغیر حساب کتاب کے جنت میں داخل کر دیں گے اور کچھ بعید نہیں ہے کہ کفار میں سے بھی کوئی شخص اللہ کی ناراضگی کے قریب تر ہو لہذا اس کو بھی بغیر حساب کے جہنم میں داخل کر دیں۔\nامام بیہقی کا قول:\nامام بیہقی رحمۃ اللہ علیہ فرماتے ہیں کہ اللہ تعالیٰ کا ارشاد ہے:\n﴿ ولا يسئل عن ذنوبهم المجرمون ﴾ [القصص ۷۸]\n’’کہ مجرم اپنے گناہوں کی بابت نہیں پوچھے جائیں گے۔ (یعنی ان سے ان کے گناہوں کے بارے میں سوال نہیں ہوگا)۔‘‘\nاور دوسری آیت میں ارشاد ہے:\n﴿لو كان من عند غير الله لوجدوا فيه اختلافاً كثيراً﴾\n’’اگر قرآن غیر اللہ کی طرف سے ہوتا تو اس میں بہت اختلاف ہوتا۔ یعنی اس میں کوئی اختلاف و تضاد نہیں ہے۔‘‘\nلہذا امام بیہقی رحمۃ اللہ علیہ نے یہ آیات نقل کرنے کے بعد ان میں تطبیق یعنی باہم مطابقت ہونا بیان فرمایا ہے اور نظام تضاد کو رفع فرمایا ہے۔ (مترجم)\nفرماتے ہیں کہ:\nان آیات میں کوئی اختلاف نہیں ہے۔ ان آیات کے مفہوم میں جمع و تطبیق کی صورت وہ ہے جو ہم نے روایت نقل کی ہے علی بن ابی طلحہ سے۔ انہوں نے ابن عباس سے کہ انہوں نے فرمایا تھا کہ جن آیات میں سوال نہ کیا جانا مذکور ہے ان سے مراد یہ ہے کہ اللہ تعالیٰ ان سے ان کے گناہوں کے بارے میں یہ نہیں پوچھے گا کہ وہ کیا کیا تھے، کیونکہ اللہ تعالیٰ ان کے گناہوں کی تفصیل ان سے بھی زیادہ جانتا ہے بلکہ ان سے پوچھنے کی بجائے ان سے کہے گا کہ تم نے ایسے ایسے گناہ کئے تھے لہذا تمہیں پیشانی اور قدموں سے پکڑ کر جہنم میں ڈالا جائے گا۔\nسیدنا ابن عباس رضی اللہ عنہ کی ایک اور روایت:\nہم نے کلبی سے ابی صالح سے سیدنا ابن عباس کی روایت اللہ تعالیٰ کے اس قول کے بارے میں نقل کی ہے:\n﴿ ولا يسئل عن ذنوبهم المجرمون ﴾ [قصص ۷۸]\n’’کہ مجرم اپنے جرائم کے بارے میں نہیں پوچھے جائیں گے۔‘‘\nاس کا مطلب یہ ہے کہ کافروں سے ان کے گناہ کے بارے میں سوال نہیں ہوگا بلکہ ہر کافر اپنی خاص علامات سے پہچانا ہوا ہوگا اور معروف ہوگا کہ یہ کافر ہے۔ اس پہچان کی بناء پر اس کے لئے جہنم میں داخل ہوگا۔ جرم کی تفصیل پوچھنے کی ضرورت نہ ہوگی۔ (مترجم) یعنی اس روایت کے مطابق ابن عباس رضی اللہ عنہ کے بقول یہ آیت کافروں پر محمول ہے۔\nاور سورۃ الرحمن کی آیت:\n﴿ فيومئذ لا يسئل عن ذنبه انس ولا جان ﴾ [الرحمن ۳۹]\n’’کہ اپنے گناہ کے بارے میں کسی جن و انس سے سوال نہیں ہوگا۔‘‘\nیعنی جس دن آسمان پھٹ جائے گا اور لپیٹ دیا جائے گا اس دن کسی جن و انس سے اس کے گناہ کے بارے میں نہیں پوچھا جائے گا اور یہ عمل حساب و کتاب سے فارغ ہو جانے کے بعد ہوگا۔ علاوہ ازیں ہر ایک مصروف بھی ہوگا۔ لہذا مجرم اپنی اپنی نشانیوں سے پہچانے جائیں گے۔ کافر اپنے چہرے کی سیاہی سے اور آنکھوں کے نیل گوں ہونے سے اور مؤمن وضو کے اثر سے ہاتھوں اور چہرے کے روشن ہونے سے۔ (1)","",{"k":"(1) ﴿فاذا انشقت السماء فكانت وردة كالدهان﴾ (الرحمن ۳۷) ’’جب آسمان پھٹ پڑے گا اور رنگے ہوئے چمڑے کی طرح سرخ ہو جائے گا۔‘‘ ﴿فيومئذ لا يسئل عن ذنبه انس ولا جان﴾ (الرحمن ۳۹) ’’اس دن کوئی انسان اور نہ کوئی جن سے اس کے گناہوں کے بارے میں سوال نہیں کیا جائے گا۔‘‘ ﴿يعرف المجرمون بسيماهم فيؤخذ بالنواصي والاقدام﴾ (الرحمن ۴۱) ’’مجرم اپنی اپنی نشانیوں سے پہچانے جائیں گے، لہذا اپنی پیشانیوں اور قدموں سے پکڑے (اور گھسیٹے جائیں گے)‘‘ ان مذکورہ تینوں آیات کا ظاہر مفہوم یہی ہے کہ قیامت میں گناہگاروں سے ان کے گناہوں کے بارے میں سوال و جواب نہیں کیا جائے گا۔ یعنی حساب و کتاب نہیں ہوگا بلکہ ان کی پیشانیوں سے پہچان کر ان کو پیشانیوں اور قدموں سے گھسیٹ کر جہنم میں ڈالا جائے گا۔ جبکہ آنے والی چند آیات سے معلوم ہوتا ہے کہ سب کا حساب ہوگا، پوچھ کچھ ہوگی۔ (مترجم) اور ارشاد باری تعالیٰ ہے: ﴿احشروا الذين ظلموا وازواجهم وما كانوا يعبدون من دون الله فاهدوهم الى صراط الجحيم وقفوهم انهم مسئولون﴾ (الصافات ۲۲-۲۴) ’’جمع کرو ظالموں (گناہگاروں) کو اور ان کے ہم جنسوں کو اور (اللہ کے سوا) جن کی وہ عبادت کرتے تھے پھر ان کو جہنم کے راستے پر روانہ کر دو۔ اور ہاں روک لو ان کو بے شک ان سے سوال و جواب ہوگا۔‘‘ ﴿فوربك لنسئلنهم اجمعين عما كانوا يعملون﴾ (الحجر ۹۲-۹۳) ’’پس قسم ہے تیرے رب کی، ہم ان سب سے ضرور پوچھیں گے اس کے بارے میں جو کچھ وہ عمل کرتے تھے۔‘‘ ان آیات میں واضح طور پر موجود ہے کہ گناہگاروں سے ضرور پوچھا جائے گا بلکہ کلام میں زور اور تاکید کے علاوہ اللہ تعالیٰ نے اس بات پر قسم بھی کھائی ہے کہ ضرور سوال ہوگا۔ سورۃ قصص اور سورۃ رحمن کی مذکورہ آیات سے سوال و جواب کی نفی ثابت ہو رہی ہے اور صافات اور حجر کی آیات سے اثبات ہو رہا ہے۔ بظاہر آیات کے مفہوم میں تضاد اور اختلاف ہے، جبکہ قرآن نے واضح طور پر اس بات کو مسترد کر دیا ہے۔ سورۃ النساء میں کہ:"}],[259,"ہمیں خبر دی ہے ابو عبد الرحمن دحان نے کہ خبر دی ہے حسین بن محمد ہارون نے کہ خبر دی ہے کلباد نے کہ ہمیں حدیث بیان کی ہے یوسف بن بلال نے کہ ہمیں حدیث بیان کی ہے محمد بن مروان نے کلبی سے، پھر اس نے مذکورہ روایت ذکر کی ہے۔\nمذکورہ آیات کے بارے میں شیخ حلیمی کا قول:\nشیخ حلیمی نے فرمایا کہ مجرم اپنے گناہوں کے بارے میں نہیں پوچھے جائیں گے اور اس دن اپنے گناہ کے بارے میں کسی جن اور انسان سے سوال نہیں ہوگا کا مطلب یہ ہے کہ مؤمن اور کافر کی تمیز کرنے کا اور فرق سمجھنے اور واضح کرنے کا سوال نہیں ہوگا۔ یعنی فرشتوں کو اس بات کی ضرورت اور احتیاج نہیں ہوگی کہ وہ قیامت کے دن کسی کے بارے میں سوال کریں اور کہیں کہ تیرا گناہ کیا تھا؟ اور تو دنیا میں کیا کرتا تھا؟ بلکہ ہر شخص اپنے بارے میں خود یہ خبر دے گا کہ وہ مؤمن تھا یا کافر تھا۔\nعلاوہ ازیں مؤمن تر و تازہ چہروں والے شرح صدر والے اور مطمئن ہوں گے جبکہ ان کے مقابلے میں مشرک منہ کالے، آنکھیں گندی اور کبیدہ خاطر ہوں گے۔ جب فرشتوں کو حکم ہوگا مجرموں کو آگ کی طرف ہانکنے کا اور موقف پر ان کو اہل ایمان سے علیحدہ کرنے کا تو ان کے مناظر ان کے گناہوں کو سمجھنے اور جاننے کے لئے کافی ہوں گے۔ (ان سے سوال کرنے کی ضرورت نہ ہوگی۔ مترجم)\nامام بیہقی کا قول:\nامام بیہقی فرماتے ہیں:\nیہ ہے وہ تفصیل جو شیخ حلیمی نے ذکر فرمائی ہے عین ممکن ہے کہ یہ اسی روایت سے ماخوذ ہے جو ہم نے تفسیر کلبی سے نقل کی ہے اور اس کے معنی کے ساتھ اس کو ذکر کیا ہے مقاتل بن سلیمان نے آخری آیت کے بارے میں۔ مگر انہوں نے حساب سے فراغت کا ذکر نہیں کیا اور ولا يسئل عن ذنوبهم المجرمون کے بارے میں کہا ہے کہ اس کا مطلب یہ ہے کہ کفار مکہ یہ کہتے تھے کہ اگر ہمارے پاس ذکر ہوتا یعنی پہلے لوگوں کی خبر ہوتی اور اطلاع ہوتی کہ وہ کس وجہ سے ہلاک کئے گئے ہیں تو ہم اللہ کے مخلص بندے بن جاتے۔\nلہذا اللہ تعالیٰ نے یہ آیت نازل فرمائی کہ مجرم ان کے گناہوں کے بارے میں نہیں پوچھے جائیں گے۔ مطلب یہ ہے کہ اس امت کے مجرم امم سابقہ کے مجرموں کے بارے میں نہیں پوچھے جائیں گے جو دنیا میں عذاب میں مبتلا کئے گئے تھے اس لئے کہ اللہ تعالیٰ نے ان کے اعمال خبیثہ کو اور ان کے علم کو خود محفوظ کر لیا ہے۔"],[260,"ہمیں خبر دی ہے استاذ ابو الحق نے، انہوں نے کہا ہمیں حدیث بتائی ہے عبد الخالق بن حسن نے خبر دی ہے عبد اللہ بن ثابت نے کہ خبر دی ہے مجھے میرے والد نے مذیل سے، اس نے مقاتل سے پھر اس سے مذکورہ روایت ذکر کی ہے۔"],[261,"ہمیں خبر دی ہے ابو عبد اللہ حافظ نے کہ خبر دی ہے عبد الرحمن بن حسن قاضی نے کہ ہمیں حدیث بیان کی ہے ابراہیم بن حسین نے کہ ہمیں حدیث بیان کی ہے آدم نے کہ ہمیں حدیث بیان کی ہے ورقاء نے ابن ابی نجیح سے، انہوں نے مجاہد سے اس آیت کے بارے میں کہ کوئی جن و انس اپنے گناہ کے بارے میں نہیں پوچھا جائے گا۔\nمجاہد نے کہا کہ اللہ تعالیٰ فرماتا ہے کہ فرشتے مجرم کے بارے میں سوال نہیں کریں گے، نہ کسی انسان سے اور نہ ہی کسی جن سے، بلکہ ان کو ان کی علامتوں سے پہچانیں گے۔ یعنی مجاہد کے بقول عدم سوال کا تعلق فرشتوں کے ساتھ ہے۔ (مترجم)\nامام بیہقی کا قول:\nامام بیہقی فرماتے ہیں کہ جس نے یہ گمان کیا ہے کہ کفار اسلامی شرائع کے مخاطب نہیں ہیں، اس نے یہ بھی گمان کیا ہے کہ وہ ان امور کے بارے میں نہیں پوچھے جائیں گے جو کچھ وہ جانتے ہیں۔ ان کی ملتیں جس امر کو تقاضا کرتی ہیں اگر چہ وہ امور اسلام میں گناہ ہوں، ہاں البتہ وہ اللہ تعالیٰ کے بارے میں اور اس کے رسولوں کے بارے میں اور فی الجملہ ایمان کے بارے میں پوچھے جائیں گے اور ہم نے اہل تفسیر سے جو کچھ نقل کیا ہے وہ زیادہ صحیح ہے۔ واللہ اعلم۔ (1)","",{"k":"(1) قال السيوطى فى الدر المنثور (۱۴۵/۶) أخرجه آدم وعبد بن حميد وابن جرير وابن المنذر والمصنف فى الشعب. ﴿ونضع الموازين القسط ليوم القيمة فلا تظلم نفس شيئًا﴾ (الانبیاء ۴۷) ’’ہم قیامت کے دن انصاف کے ترازو رکھیں گے، کسی نفس پر ذرا سا بھی ظلم نہیں کیا جائے گا۔‘‘ اعمال کا وزن کیا جانا حق ہے ارشاد باری تعالیٰ ہے: ﴿والوزن يومئذ الحق﴾ (اعراف ۸) ’’قیامت کے دن اعمال کا تولنا حق ہے اور سچ ہے۔‘‘ جس کے اعمال کا پلہ بھاری ہوا وہ کامیاب ہو گیا ﴿فمن ثقلت موازينه فاولئك هم المفلحون﴾ (اعراف ۸) ’’جن اشخاص کے اعمال والے پلڑے بھاری ہو گئے بس وہی لوگ کامیاب ہوں گے۔‘‘ جن لوگوں کے پلڑے ہلکے پڑ گئے وہ لوگ خسارے میں ہوں گے ﴿ومن خفت موازينه فاولئك الذين خسروا انفسهم بما كانوا باياتنا يظلمون﴾ (اعراف ۸-۹) ’’جن لوگوں کے پلڑے اور ترازو ہلکے ہو گئے بس وہی لوگ ہیں جنہوں نے اپنے آپ کو خسارے میں ڈالا تھا، اس وجہ سے کہ وہ ہماری آیات کے ساتھ ظلم کرتے تھے۔‘‘ قیامت کا سائرن بجتے ہی لوگ تمام رشتے ناتے خوف کے مارے ختم کر بیٹھیں گے ارشاد باری ہے: ﴿فاذا نفخ في الصور فلا انساب بينهم يومئذ ولا يتساءلون﴾ (المؤمنون ۱۰۱) ’’جب صور پھونکا جائے گا تو ان کے درمیان رشتے ناتے نہیں رہیں گے اور نہ ہی وہ ایک دوسرے کو پوچھیں گے۔‘‘ جن کے پلڑے اعمال کے بھاری ہوئے وہ کامیاب ہوں گے ﴿فمن ثقلت موازينه فاولئك هم المفلحون﴾ (المؤمنون ۱۰۲) ﴿ومن خفت موازينه فاولئك الذين خسروا انفسهم في جهنم خلدون﴾ (المؤمنون ۱۰۳) ’’جن کے (نیکیوں کے) پلڑے ہلکے ہو گئے وہی لوگ تھے جنہوں نے اپنے آپ کو خسارے میں رکھا تھا، وہ جہنم میں ہمیشہ رہیں گے۔‘‘ ہلکے پلڑے والے جہنم میں جھلس جائیں گے اور ارشاد باری ہے: ﴿تلفح وجوههم النار وهم فيها كالحون﴾ (المؤمنون ۱۰۴) ’’ان کے چہروں کو آگ جھلس دے گی اور وہ اس میں بدشکل بنے ہوں گے۔‘‘ ﴿فاما من ثقلت موازينه فهو في عيشة راضية﴾ (القارعہ ۶/۷) الى آخره ’’جس کے اعمال کے وزن بھاری نکلیں گے وہ دلپسند عیش میں ہوگا۔‘‘ ﴿واما من خفت موازينه فامه هاويه (۹) وما ادراك ماهيه (۱۰)﴾ ’’اور جس کے وزن ہلکے نکلیں گے اس کا ٹھکانہ ھاویہ ہے، تم کیا سمجھے کہ حاویہ کیا چیز ہے۔‘‘ ﴿نار حامية﴾ (۱۱) ’’وہ دھکتی ہوئی آگ ہے۔‘‘ وزن اعمال کا اثبات حدیث سے میزان کا ذکر حدیث ایمان میں وارد ہوا ہے۔ لہذا اعمال کے وزن کے ساتھ ایمان لانا اسی طرح ضروری ہے اور لازم ہے جس طرح دوبارہ اٹھائے جانے کے ساتھ اور جنت اور جہنم کے ساتھ ضروری اور لازم ہے۔ میزان کے ساتھ ایمان کو دیگر تمام ایمان والی چیزوں میں ذکر فرمایا ۲۷۸...... ہمیں خبر دی ہے ابو عبد اللہ حافظ نے کہ ہمیں حدیث بیان کی ہے ابو العباس بن یعقوب نے کہ ہمیں حدیث بیان کی ہے محمد بن عبد اللہ منادی نے کہ ہمیں حدیث بیان کی ہے یونس بن محمد نے کہ ہمیں حدیث بیان کی ہے معتمر بن سلیمان نے اپنے باپ سے، انہوں نے یحییٰ بن یعمر سے، انہوں نے ابن عمر رضی اللہ عنہ سے، انہوں نے سیدنا عمر رضی اللہ عنہ سے، انہوں نے نبی کریم صلی اللہ علیہ وسلم سے ایمان کے بارے کہ حضور صلی اللہ علیہ وسلم نے فرمایا: ایمان یہ ہے کہ تو اللہ کے ساتھ ایمان لا اور اس کے فرشتوں اور اس کی کتابوں، اس کے رسولوں کے ساتھ اور تو ایمان لا جنت کے ساتھ اور جہنم کے ساتھ اور میزان کے ساتھ اور تو ایمان لا موت کے بعد اٹھنے پر اور تو ایمان لا تقدیر کے ساتھ اچھی ہو یا بری ہو۔ اس کے بعد اس نے کہا یعنی سائل نے کہ جب میں یہ کام کروں گا تو کیا میں مؤمن ہوں گا۔ (آپ نے فرمایا، جی ہاں۔ (سائل نے) کہا کہ آپ نے سچ فرمایا۔ معلوم ہوا کہ ایمان بالمیزان دیگر تمام ان چیزوں کی طرح ہے جن کے ساتھ ذکر ہوا ہے۔ (مترجم) ﴿الذين ضل سعيهم في الحيواة الدنيا وهم يحسبون انهم يحسنون صنعا﴾ (کہف ۱۰۴) ’’یہ وہ لوگ ہیں جن کی ساری سعی دنیا کی زندگی میں برباد ہو گئی ہے، حالانکہ وہ یہ سمجھتے ہیں کہ اچھے کام کر رہے ہیں۔‘‘ ﴿اولئك الذين كفروا بايات ربهم ولقائه فحبطت اعمالهم فلا نقيم لهم يوم القيمة وزنا﴾ (کہف ۱۰۵) ’’یہ وہی لوگ ہیں جنہوں نے اپنے رب کی آیات کے ساتھ کفر کیا ہے اور اس کی ملاقات کے ساتھ بھی کفر کیا ہے۔ لہذا ان کے اعمال ضائع ہو گئے ہیں اور ہم قیامت کے دن ان کے لئے کچھ بھی وزن قائم نہیں کریں گے۔‘‘ قرآن مجید کی یہ آیات نص صریح ہیں اس بات پر کہ کفار و مشرکین کے اعمال دنیا کی زندگی میں ہی برباد ہو چکے ہیں اور قیامت میں ان کا وزن بھی نہیں کیا جائے گا۔ لہذا اس پر ان کو ثواب بھی نہیں ملے گا اور نہ ہی کوتاہی پر سزا ہوگی۔ یہ سب اعمال ایمان کے تابع رہیں گے۔ (از مترجم) امام بیہقی کی وضاحت: امام بیہقی رحمۃ اللہ علیہ سلسلہ کلام جاری رکھتے ہوئے فرماتے ہیں: اہل علم نے اعمال کے وزن کرنے کی کیفیت میں اختلاف کیا ہے۔ کچھ لوگ اس طرف گئے ہیں کہ کافر بھی صلہ رحمی بھی کرتے ہیں۔ لوگوں کے ساتھ غمخواری بھی کرتے ہیں، کمزور پر شفقت بھی کرتے ہیں، پریشان حال کی فریاد رسی بھی کرتے ہیں، مظلوم کا دفاع بھی کرتے ہیں، غلام آزاد بھی کرتے ہیں وغیرہ وغیرہ۔ ایسے اعمال میں کہ اگر وہ ایک مسلم کی جانب سے ہوتے تو ضرور وہ نیکی اور طاعت شمار ہوتے تو جس کافر کے پاس اس قسم کی بھلائیاں ہوں گی وہ جمع کر کے اس کے میزان میں رکھی جائیں گی۔ اس لئے کہ اللہ تعالیٰ فرماتے ہیں فلا تظلم نفس شيئا (انبیاء ۴۷) کہ کسی نفس پر ذرہ بھر بھی ظلم نہیں کیا جائے گا۔ یعنی ایسا نہیں کہ اس کے ترازو اور وزن میں سے کچھ لے لیا جائے اور کم کر لیا جائے۔ لیکن جب اس کے کفر کا اس کے اچھے اعمال سے مقابلہ ہوگا تو وہ اچھائیوں سے بھاری ہو جائے گا اور ادھر اللہ تعالیٰ نے جنت کو کافروں کے لئے حرام کر رکھا ہے (جنت تو ان کو مل نہیں سکتی) لہذا اس کے خیراتی امور کی جزا اس کو اس طرح دی جائے گی، اس سے عذاب ہلکا کر دیا جائے گا، لہذا اس کو عذاب دیگر کفار کے مقابلے میں نسبتاً کم دیا جائے گا جنہوں نے ان خیرات میں سے کچھ بھی نہیں کیا تھا۔ ۲۷۹...... ہمیں خبر دی ہے ابو عبد اللہ حافظ نے کہ مجھے خبر دی ہے ابو الولید نے کہ خبر دی ہے حسن بن سفیان نے کہ ہمیں حدیث بیان کی ہے محمد أخرجه البخارى (۵۹۲/۱۰ فتح) عن موسى بن إسماعيل، مسلم (۱۹۴/۱) عن محمد بن أبى بكر المقدمى."}],[262,"§فصل:...... اعمال کا وزن کرنا\nجب حساب و کتاب کا مرحلہ گزر چکے گا تو اس کے بعد اعمال وزن کئے جائیں گے اور ایک خاص ترازو میں تولے جائیں گے۔ یہ وزن اجر اور جزا دینے کے لئے ضروری ہے۔ اس کے مناسب یہی ہے کہ یہ وزن کا معاملہ محاسبہ کے بعد ہو کیونکہ حساب تو اعمال ثابت کرنے کے لئے ہے اور وزن ان کی مقدار میں واضح کرنے کے لئے تاکہ اجر و ثواب اسی اندازے اور مقدار کے مطابق دیا جائے۔\n§وزن اعمال کا اثبات قرآن مجید سے\n§ارشاد باری تعالیٰ ہے:\n§’’جس کے (نیکیوں) کے پلڑے بھاری ہوں گے وہ کامیاب ہوں گے۔‘‘\n§جن کے ترازو ہلکے ہوں گے وہ ہمیشہ جہنم میں رہیں گے امام بیہقی کا قول:\n§امام بیہقی رحمۃ اللہ علیہ نے فرمایا کہ:\nجو آیت ہم نے درج کی ہے اس سے معلوم ہوتا ہے کہ کفار کے اعمال بھی وزن کئے جائیں گے، اس لئے کہ دوسری آیت میں الفاظ ہیں:\n§﴿ بما كانوا باياتنا يظلمون ﴾ [اعراف ۹]\n§’’وہ لوگ خسارے میں اس لئے ہوں گے کہ وہ ہماری آیات کے ساتھ ظلم و نا انصافی کرتے تھے۔‘‘\nاور اللہ کی آیات کے ساتھ ظلم ان کے ساتھ استہزاء کرنا ہے اور ان کا یقین نہ کرنا ہے۔\n§اور ایک آیت میں یہ بھی کہ:\n§اور اسی تسلسل میں یہ بھی ہے کہ:\n§﴿ في جهنم خالدون ﴾ [مؤمنون ۱۰۳]\n§’’کہ وہ جہنم میں ہمیشہ رہیں گے۔‘‘\n§﴿ الم تكن آياتي تتلى عليكم فكنتم بها تكذبون ﴾ [مؤمنون ۱۰۵]\n§’’کیا تم لوگوں پر میری آیات پڑھی نہیں جاتی تھیں مگر تم ان کی تکذیب کرتے تھے۔‘‘\n§(اس سے معلوم ہوا کہ کفار کے اعمال کا وزن ہوگا) اور ایک آیت میں یہ بھی ہے کہ:\n§﴿ فامه هاويه وما ادراك ماهيه نار حاميه ﴾ [القارعہ ۹-۱۱]\n§’’جس کے وزن اعمال ہلکے ہوں گے ان کا ٹھکانہ جہنم ہے، تم کیسے جانوں کہ وہ کیا ہے، وہ آگ ہے دھکائی ہوئی۔‘‘\n§یہ وعید اور دھمکی مطلقاً کفار کے لئے ہی ہے۔ جب اس آیت اور آنے والی آیت کے مفہوم کو ملا کر غور کیا جائے۔ یعنی:\n§﴿ وان كان مثقال حبة من خردل اتينا بها ﴾ [الانبیاء ۴۷]\n§’’اگر چہ کوئی عمل رائی کے دانے کے برابر ہو تو ہم اس کو بھی لائیں گے۔‘‘\nدونوں آیات کے مفہوم کو ملا کر غور کرنے سے ثابت ہوتا ہے کہ کفار سے ہر اس بات کا سوال ہوگا جس میں انہوں نے دین کے اصول یا فروع میں سے حق کی مخالفت کی تھی۔ کیوں کہ اگر وہ نہ پوچھے جاتے ان باتوں کے بارے میں جن میں انہوں نے موافقت کی تھی اپنی اصل دین داری میں مثلاً مختلف قسم کا باہم دینا لینا ان کا اور اس کا حساب بھی نہ کئے جاتے تو وزن میں اس کا شمار بھی نہ ہوگا۔ جس وقت وہ اعمال وزن کے وقت تولے گئے تو یہ بات دلالت کرتی ہے کہ وہ ان تمام باتوں اور تمام چیزوں کے بارے میں بھی پوچھے جائیں گے۔ حساب کے موقف میں یہ تحقیق اور یہ فیصلہ اس شخص کے قول پر ہے جو یہ کہتا ہے کہ کفار بھی شرائع کے مخاطب ہیں اور مکلف ہیں اور وہ صحیح ہے، اس لئے اللہ تعالیٰ کا فرمان ہے:\n§﴿ فويل للمشركين الذين لا يؤتون الذكاة ﴾ [فصلت ۶]\n§’’پس ہلاکت مشرکوں کے لئے جو زکوٰۃ ادا نہیں کرتے۔‘‘\nاللہ تعالیٰ نے کفار و مشرکین کو زکوٰۃ نہ دینے پر دھمکی دی ہے (اس سے معلوم ہوا کہ وہ لوگ احکام شریعت کے مکلف ہیں)۔ اور اللہ تعالیٰ نے مجرموں کے بارے میں خبر دیتے ہوئے فرمایا ہے کہ قیامت میں ان سے سوال ہو گا:\n﴿ ما سلككم في سقر؟ قالوا لم نك من المصلين ولم نك نطعم المسكين وكنا نخوض من الخائضين وكنا نكذب بيوم الدين حتى اتانا اليقين ﴾ [المدثر ۴۳-۴۷]\n’’تمہیں جہنم میں کیا چیز لے گئی؟ وہ کہیں گے ہم لوگ نماز نہیں پڑھتے تھے اور مسکین کو کھانا نہیں کھلاتے تھے اور اہل باطل کے ساتھ مل کر حق کا انکار کرتے تھے اور روز جزا کو ہم جھٹلاتے تھے۔ یہاں تک کہ ہمیں موت آ گئی۔‘‘\nان آیات سے واضح ہوا کہ مشرکین بھی ایمان بالبعث مر کر اٹھنے، نماز قائم کرنے، زکوٰۃ ادا کرنے کے مخاطب ہیں اور مکلف ہیں ان چیزوں کا سوال ہوگا اور ان چیزوں میں سے جس کے ساتھ وہ کوتاہی کریں گے اس کی ان کو سزا دی جائے گی۔ واللہ اعلم۔\n§احناف کا مسلک\nاحناف کا مسلک اس کے برعکس یہ ہے کہ کفار و مشرکین جب تک ایمان و اسلام قبول نہ کر لیں اس وقت تک وہ شرعی احکامات کے مکلف و مخاطب نہیں ہیں۔ ان سے ان اعمال وغیرہ کا سوال نہیں ہوگا بلکہ ان سے ایمان باللہ اور ایمان بالرسول ایمان بالقرآن کا سوال ہو گا اور ان کے اعمال کا وزن بھی نہیں کیا جائے گا اور اس پر ان کو اجر و ثواب بھی نہیں ملے گا بلکہ ان کے سارے اعمال دنیا میں ہی اکارت ہو گئے ہیں۔\n§اللہ تعالیٰ نے کفار و مشرکین کے اعمال کے بارے میں واضح طور پر ارشاد فرمایا ہے:\nبن ابی بکر مقدمی نے، ابو الولید نے کہا خبر دی ہے عبد اللہ بن محمد نے انہوں نے کہا ہمیں حدیث بیان کی ہے محمد بن عبد الملک بن ابی شوارب نے، وہ دونوں کہتے ہیں کہ ہمیں حدیث بیان کی ہے ابو عوانہ نے عبد الملک بن عمیر سے، انہوں نے عبد اللہ بن حارث بن نوفل سے، انہوں نے عباس بن عبد المطلب سے، وہ کہتے ہیں کہ میں نے کہا یا رسول اللہ کیا آپ نے ابو طالب (چچا) کو کچھ فائدہ دیا، وہ آپ کی حفاظت کیا کرتا تھا اور آپ کے لئے لوگوں سے ناراضگی مول لیتا رہتا تھا۔ آپ صلی اللہ علیہ وسلم نے فرمایا، جی ہاں، وہ جہنم میں ٹخنوں ٹخنوں تک ہوگا۔ اگر میں نہ ہوتا تو وہ جہنم کے سب سے نچلے طبقے میں ہوتا۔ اس کو بخاری نے صحیح میں موسیٰ بن اسماعیل سے ابو عوانہ سے روایت کیا ہے اور اس کو مسلم نے محمد بن ابی بکر اور ابن شوارب سے روایت کیا ہے۔\n§امام بیہقی کا قول:\n§امام بیہقی رحمۃ اللہ علیہ فرماتے ہیں کہ:\nکچھ لوگ اس طرف گئے ہیں کہ کافر کی اچھائیاں اس لئے نہیں تولی جائیں گی تاکہ وہ ان کے ساتھ عذاب میں تخفیف کی صورت میں جزا اور اجر دیا جائے بلکہ اس کی حجت ختم کرنے کے لئے تولی جائیں گی یہاں تک کہ تولنے کے بعد جب ان کے ساتھ اس کو تولا جائے گا تو وہ ان پر بھاری ہو کر ان کو تباہ کر دے گا۔ یا سرے سے بالکل تولی ہی نہیں جائیں گی۔ بلکہ اس کافر اور اس کی دیگر تمام سیئات ایک ہی پلڑے میں رکھ دی جائیں گی۔ پھر اس سے کہا جائے گا کہ کیا تیرے پاس کوئی طاعت یعنی اللہ کی فرمانبرداری بھی ہے جسے ہم دوسرے پلڑے میں رکھیں۔ چنانچہ وہ اس کے پاس نہیں ہوگی۔ لہذا ترازو کا یہی پلڑہ بھاری ہو جائے گا اور خالی پلڑا اٹھ جائے گا اور بھرا ہوا پلڑا اپنی جگہ باقی رہے گا۔ یہی ہوگا اس کا ہلکا پلڑہ ہو جانا۔ باقی اس کی اچھائیاں وہ کفر کے ہوتے ہوئے کچھ بھی شمار نہیں کی جائیں گی۔ ارشاد باری تعالیٰ ہے:\n§﴿ ومامنا الى ما عملوا من عمل فجعلناه هباء منثورا ﴾ [الفرقان ۲۳]\n’’ہم متوجہ ہوں گے کفار کے اعمال کی طرف پس کر دیں گے ہم ان کو اڑتا ہوا غبار۔ یعنی کفر کے ہوتے ہوئے کوئی اچھے عمل بھی مقبول نہیں ہوں گے۔ (مترجم)‘‘\n§ابن جدعان کو کچھ نہ ملا\nاور ہم نے سیدہ عائشہ رضی اللہ عنہا سے روایت کی ہے، وہ فرماتی ہیں انہوں نے عرض کی یا رسول اللہ صلی اللہ علیہ وسلم ایک شخص ابن جدعان تھا، جاہلیت کے دور میں وہ صلہ رحمی کرتا تھا اور مسکین کو کھانا دیتا تھا، کیا یہ کام اس کو فائدہ دیں گے؟ آپ صلی اللہ علیہ وسلم نے فرمایا کہ اس کو کوئی فائدہ نہیں دیں گے، اس لئے کہ اس نے ایک دن بھی نہیں کہا تھا:\n§رب اغفر لي خطيئتي يوم الدين\n§’’اے میرے رب قیامت میں میری خطا معاف کر دینا۔‘‘\n§حاتم کو کچھ نہ ملنا\nاور ہم نے عدی بن حاتم سے روایت کیا ہے کہ اس نے حضور صلی اللہ علیہ وسلم سے اپنے والد حاتم کے بارے میں پوچھا تھا۔ آپ صلی اللہ علیہ وسلم نے جواب دیا تھا کہ:\nان اباك طلب امراً فادركه بے شک تیرے والد نے جو کچھ طلب کیا تھا اس نے اس کو پالیا تھا۔\nاس سے آپ تذکرہ اور شہرت مراد لے رہے تھے۔ یعنی وہ چاہتا تھا کہ میرا نام ہو میرا چرچا ہو، شہرت ہو کہ بڑائی ہو۔ وہ اس نے پالیا ہے۔ اب آخرت میں اس کو کیا ملتا ہے۔ (مترجم)\n§مؤمن کو دنیا و آخرت میں جبکہ کافر کو صرف دنیا میں اجر ملتا ہے\n§ہم نے سیدنا انس بن مالک رضی اللہ عنہ سے روایت کیا ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا:\nبے شک اللہ تعالیٰ کسی مؤمن پر ظلم نہیں کرتا بلکہ اس کی ایک نیکی پر اسے دنیا میں بھی ثواب دیتا ہے اور آخرت میں بھی اس پر جزا دے گا بہر حال۔ رہا کافر تو وہ اپنی نیکیوں کا بدلہ دنیا میں دے دیا جاتا ہے۔ جب وہ آخرت کی طرف لوٹتا ہے تو اس کی کوئی نیکی باقی نہیں ہوتی۔ جس پر اس کو کوئی خیر عطا کی جائے۔\nہمیں اس کی خبر دی ہے ابو الحسن بن فضل قطان نے خبر دی ہے احمد بن محمد بن زیاد ابو سہل قطان نے کہ ہمیں حدیث بیان کی ہے اسحق بن حسن حربی نے، انہوں نے کہا کہ ہمیں حدیث بیان کی ہے عفان سے، انہوں نے کہا ہمیں حدیث بیان کی ہے ہمام نے قتادہ سے، انہوں نے سیدنا انس رضی اللہ عنہ سے یہ کہ نبی کریم صلی اللہ علیہ وسلم نے فرمایا کہ بے شک اللہ عز و جل...... پھر مذکورہ حدیث ذکر کی ہے۔ اس کو مسلم نے نقل کیا ہے صحیح میں ہمام کی روایت سے۔\nامام بیہقی کا قول:\nامام بیہقی رحمۃ اللہ علیہ فرماتے ہیں:\nجو لوگ پہلی توجیہ کے قائل ہوئے ہیں انہوں نے یہ خیال کیا ہے کہ آیات اور احادیث کی مراد و مطلب یہ ہے کہ کافر کی نیکیاں اس کو جہنم سے بچانے اور جنت میں داخل کرانے کے لئے کوئی کام نہیں آتیں، ہاں بھی یہ جائز ہوتا ہے کہ اس کی سیئات کی وجہ سے اس کے لئے جو عذاب واجب ہو چکا تھا وہ ہلکا ہو جاتا ہے اس کی نیکیوں کی وجہ سے۔\nاور یہ ایک مرفوع حدیث میں آ چکا ہے۔ (1)","",{"k":"(1) أخرجه مسلم (۲۱۲۲/۴) عن أبى بكر بن أبى شيبة وزهير بن حرب قالا حدثنا يزيد بن هارون عن همام بن يحيى به."}],[263,"§اللہ تعالیٰ کی کرم نوازی\nہمیں حدیث بیان کی ہے امام ابو الطیب سہل بن محمد بن سلیمان نے خبر دی ہے ابو عبد اللہ محمد بن یزید جوزی نے کہ ہمیں حدیث بیان کی ہے زکریا بن یحییٰ بزاز نے کہ ہمیں حدیث بیان کی ہے زید بن اخرم طائی نے کہ ہمیں حدیث بیان کی ہے عامر بن مدرک نے کہ ہمیں حدیث بیان کی ہے عقبہ بن یقظان نے قیس بن مسلم سے، انہوں نے طارق بن شہاب سے، انہوں نے سیدنا عبد اللہ بن مسعود رضی اللہ عنہ سے، انہوں نے کہا کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا تھا:\nما احسن من محسن كافر او مسلم الا اثابه الله عز وجل\n’’کوئی بھی نیکی کرنے والا جو نیکی کرتا ہے مسلم ہو یا کافر ہو اللہ تعالیٰ اس کو ثواب دیتا ہے۔‘‘\nہم نے کہا یا رسول اللہ صلی اللہ علیہ وسلم اللہ تعالیٰ کا کافر کو ثواب دینا کیسا ہوگا؟ آپ صلی اللہ علیہ وسلم نے فرمایا کہ اگر وہ صلہ رحمی کرتا تھا یا صدقہ کرتا تھا یا کوئی نیک عمل کرتا تھا اللہ تعالیٰ اس کو ثواب دیتا ہے اور اس کو مخصوص ثواب یہ ہے کہ اس کو مال دیتا ہے، صحت دیتا ہے اور اس کی مثل کچھ اور بھی۔ ہم نے عرض کی کہ کافر کو آخرت میں ثواب کیسے دیا جائے گا؟ آپ صلی اللہ علیہ وسلم نے فرمایا زیادہ عذاب کے مقابلے میں کم عذاب دیا جائے گا۔ اس کے بعد آپ صلی اللہ علیہ وسلم نے یہ آیت پڑھی:\n﴿ ادخلوا آل فرعون اشد العذاب ﴾ [مؤمن ۴۶]\n’’فرعونیوں کو سخت ترین عذاب میں داخل کر دو۔‘‘\nجس سے معلوم ہوتا ہے کہ کچھ کفار کم عذاب اور کچھ کو کمترین عذاب بھی دیا جائے گا۔ (مترجم)\nاس روایت کو نقل کرنے کے بعد امام بیہقی تبصرہ کرتے ہیں کہ اگر یہ روایت ثابت ہو جائے تو اس میں حجت و دلیل ہے۔ اگر ثابت نہ ہو تو پھر دلیل بھی نہیں ہے۔ اس لئے کہ اس کی اسناد میں وہ راوی بھی ہے جس کے ساتھ حجت نہیں پکڑی جاتی۔ اور ابو طالب کے واقعہ والی حدیث صحیح ہے۔ باقی شیخ حلیمی کے اس حدیث کا انکار کرنے کا کچھ مطلب نہیں ہے۔ میں نہیں جانتا کہ اس حدیث کی صحت ان سے کیونکر اوجھل رہی ہے۔ وہ تو کئی وجوہ سے مروی ہے۔ عبد الملک بن عمیر سے اور ایک اور صحیح طریقہ سے سیدنا ابو سعید خدری سے بھی نبی کریم صلی اللہ علیہ وسلم سے اسی حدیث کے مفہوم میں مروی ہے۔\nاور اس روایت کو صاحب صحیح نے بھی نقل کیا ہے اور ان دونوں کے علاوہ کئی ائمہ نے اپنی صحاح کتب میں نقل کیا ہے۔ جو شخص کافر کی نیکیوں کی بابت مذہب ثانی کی طرف گیا ہے اس کے لئے صحیح ہے کہ وہ یہ کہے کہ حدیث ابو طالب خاص ہے صرف اس کے عذاب کی تخفیف کے لئے۔ اس نے جو رسول اللہ صلی اللہ علیہ وسلم کے ساتھ سلوک کیا تھا اس کی وجہ سے اس تخفیف کے ساتھ ابو طالب مختص کیا گیا تھا۔ حضور صلی اللہ علیہ وسلم کی تالیف قلب کے لئے اور آپ کوئی نفع و ثواب دینے کے لئے ابو طالب کے لئے نہیں اس لئے کہ ابو طالب کی نیکیاں اس کے کفر کی وجہ سے اس کی مغفرت پر اڑتا ہوا غبار ہو گئی تھیں۔\nرحمۃ للعالمین کی وجہ سے ابو لہب کو پانی کا گھونٹ ملنا\nاسی حدیث ابو طالب کی مثل ہے حدیث عروہ بن زبیر جس میں ابو لہب کی طرف سے رسول اللہ صلی اللہ علیہ وسلم کی ولادت کی خوشی میں اپنی لونڈی ثوبیہ کو آزاد کرنا اور ثوبیہ کا رسول اللہ صلی اللہ علیہ وسلم کو دودھ پلانا مذکور ہے۔ جب ابو لہب کا انتقال ہو گیا تو اس کے گھر والوں میں سے کسی ایک کو وہ خواب میں دکھایا گیا۔ بڑی بری حالت میں اور ناکامی میں تھا۔ اس نے اس سے پوچھا تیرے ساتھ کیا سلوک کیا گیا۔ ابو لہب نے کہا کہ میں نے تم لوگوں سے جدا ہونے کے بعد مکمل مایوسی دیکھی، امید کی کہیں کوئی صورت نہیں تھی۔ ہاں ثوبیہ کو آزاد کرنے کے بدلے میں مجھے اتنا سا گھونٹ پلایا گیا ہے (یعنی تھوڑا سا) اس نے انگوٹھے اور شہادت کی انگلی کے درمیان جو فاصلہ یا سوراخ بنتا ہے اسی کا اشارہ کر کے دکھایا۔ یہ بات بھی ایسی ہی ہے اس لئے کہ اس واقعہ میں بھی احسان کا مرجع وہی ذات رسالت ہے، لہذا وہ نیکی ضائع نہ کی گئی۔ بہر حال اہل ایمان کا حساب لیا جائے گا اور ان کے اعمال کا وزن کیا جائے گا اور وہ دو گروہ ہوں گے۔\nپہلا گروہ:\nمؤمن متقی جو کبیرہ گناہوں سے بچتے رہتے تھے۔ ان کی نیکیاں روشنی کے پلڑے میں رکھی جائیں گی اور ان کے صغیرہ گناہ اگر ہوئے تو وہ دوسرے پلڑے میں رکھے جائیں گے۔ اللہ پاک ان صغیرہ گناہوں کا کوئی وزن نہیں بنائیں گے۔ لہذا روشنی والا پلڑا اٹھ جائے گا۔ جیسے فارغ اور خالی اٹھ جاتا ہے۔ پھر ان کے لئے جنت کا حکم ہو جائے گا اور ان میں سے ہر ایک کو اس کی حسنات اور طاعت کے بقدر ثواب دیا جائے گا۔ جیسے ہم ونضع الموازین والی آیت بیان کر چکے ہیں۔\nدوسرا گروہ:\nمؤمن خطا کاروں کا ہوگا۔ یہ وہ لوگ ہوں گے جو قیامت میں کبیرہ گناہوں اور فواحش اور بے حیائیوں کی سزا دیے جائیں گے۔ مگر وہ شرک نہیں کرتے ہوں گے۔ ان کی نیکیاں بھی روشنی کے پلڑے میں رکھی جائیں گی اور ان کے گناہ اور سیئات تاریک پلڑے میں رکھے جائیں گے۔ آج ان کے ان کبیرہ گناہوں کا جو وہ لائے ہوں گے بھی بوجھ ہوگا اور ان کی نیکیوں کا بھی بوجھ ہو گا۔ مگر نیکیاں ہر حال میں بھاری ہوں گی۔ اس لئے کہ ان کے ساتھ اصل ایمان بھی ہوگا۔ جبکہ سیئات اور گناہوں میں کفر نہیں ہوگا۔ اس لئے کہ ایک ہی شخص میں ایمان بھی ہو اور کفر بھی یہ محال ہے۔\nاور دوسری یہ وجہ بھی ہے کہ حسنات اور نیکیوں کا مقصد اور منشاء صرف اللہ کی رضا تھا۔ جبکہ اس کے مقابلے میں گناہوں کا مقصد اللہ کی مخالفت کرنا یا اللہ سے بغض نہیں تھا بلکہ وہ محض نفسانی خواہشات کی بناء پر تھا۔ جس کے ساتھ ساتھ اللہ کا خوف اللہ کے غضب سے ڈرنا بھی ساتھ تھا۔ لہذا یہ تو محال ہوگا کہ سیئات بھی برابر ہو جائیں، اگر چہ زیادہ بھی ہوں۔ تاہم نیکیوں کے برابر نہیں ہوں گی۔ لہذا لا محالہ گناہوں کا بوجھ تو ہو گا اور ان کے ساتھ ترازو بھی جھکے گا۔ یہاں تک کہ بعض سیئات کا بوجھ بعض حسنات کے بوجھ کی طرح ہوگا۔ سو اس وقت وہی معاملہ ہوگا جو قرآن میں مذکور ہو۔ آیت ونضع الموازين القسط میں مذکور ہے کہ کوئی نفس ذرہ برابر ظلم نہ کیا جائے گا اور محمد مصطفیٰ صلی اللہ علیہ وسلم کی سنت بھی دلالت کرتی ہے اس کی تفصیلات کے بارے میں۔\nاور اس کا خلاصہ اللہ تعالیٰ کا یہ فرمان ہے:\n﴿ ان الله يغفر الذنوب جميعا ﴾ [الزمر ۵۳]\n’’بے شک اللہ تعالیٰ سارے کے سارے گناہ بخش دے گا۔‘‘\nاور ارشاد باری تعالیٰ ہے:\n﴿ ويغفر ما دون ذالك لمن يشاء ﴾ [النساء ۱۱۶]\n’’جس کے لئے چاہے گا شرک کے علاوہ گناہ معاف کر دے گا۔‘‘\nجس کو چاہے گا اپنے فضل سے بخش دے گا اور جس کے لئے چاہے گا اپنی اجازت کے ساتھ شفاعت کرا کے قبول کرے گا اور جس کو چاہے گا اس کے گناہ کی مقدار عذاب دے گا۔ پھر اس کو جہنم سے اپنی رحمت کے ساتھ جنت میں داخل کرے گا۔ جیسے کہ اس بارے میں خبر صادق وارد ہوئی ہے۔\nاور کتاب اللہ دلالت کرتی ہے مؤمنوں کے ملے جلے اعمال کے وزن ہونے پر اور وہ یہی ارشاد ہے:\n﴿ ونضع الموازين القسط ليوم القيامه فلا تظلم نفس شيئا وان كان مثقال حبة من خردل اتينا بها وكفى بنا حاسبين ﴾ [الانبیاء ۴۷]\n’’ہم انصاف کے ترازو قائم کریں گے قیامت کے روز لہذا کوئی نفس ذرہ برابر ظلم نہیں کیا جائے گا۔ اگر چہ کسی کی کوئی نیکی رائی کے دانے‘‘\nکے برابر ہوگی تو ہم اس کو بھی ضرور لے آئیں گے اور ہم حساب کرنے کے لئے کافی ہیں۔\nاللہ تعالیٰ کی اس آیت میں مراد یہ ہے کہ کسی انسان کی کوئی نیکی چھوڑی نہیں جائے گی۔ بلکہ وہ تولی جائے گی۔ یہ ان مؤمن کا جس کے ملے جلے اعمال ہوں گے، کیونکہ اگر اس کی کوئی نیکی چھوڑی جائے اور اس کا وزن رہ جائے تو اس کی جگہ اس کے گناہ کا وزن زیادہ ہو جائے گا اور یہ زیادتی اس کے لئے عذاب کو واجب کر سکتی ہے۔\nوزن اعمال کی کیفیت\nبہر حال وزن اعمال کیسے ہوگا؟ اس کی دو صورتیں ہیں۔\nپہلی صورت:\nیہ ہے کہ نیکیوں کے صحیفے ایک روشن پلڑے میں رکھے جائیں گے اور گناہوں کے صحیفے تاریک پلڑے میں کیونکہ اعمال ایک ہی صحیفے میں نہیں لکھے جاتے اور ان کا لکھنے والا بھی ایک نہیں ہے۔ جو فرشتہ دائیں طرف ہوتا ہے وہ نیکیوں کو لکھتا ہے اور جو بائیں طرف ہوتا ہے وہ برائیوں اور گناہوں کو لکھتا ہے۔ لہذا دونوں اپنے اپنے صحیفے لکھنے میں الگ الگ ہوتے ہیں۔ جب وزن کرنے کا وقت آئے گا تو وہی صحیفے میزان اور ترازو میں رکھے جائیں گے۔ سو جس کو بھاری کرنے کا حق ہوگا اللہ تعالیٰ اس کو بھاری کر دیں گے اور جس کو ہلکا کرنے کا حق ہوگا اس کو ہلکا کر دیں گے۔\nدوسری صورت:\nیہ ہے کہ ممکن ہے کہ اللہ تعالیٰ کچھ مخصوص اجسام پیدا فرما دیں جو حسنات اور سیئات کی تعداد کے مطابق ہوں اور وہ سب ایک دوسرے سے ایسی صفات کے ساتھ ممتاز اور نمایاں ہوں جن کے ذریعے وہ پہچانے جا سکیں۔ پھر وہی اجسام وزن کئے جائیں۔ جیسے دنیا میں بعض اجسام بعض کے ساتھ وزن کئے جاتے ہیں۔ واللہ اعلم۔ اور وزن اعمال میں اعتبار اس بات کا ہوگا کہ اللہ کی رضا اور اللہ کی ناراضگی جس جگہ واقع ہو۔ اہل تفسیر اس میزان کو دو پلڑوں والا ثابت کرنے کی طرف گئے ہیں اور احادیث میں بھی اس پر دلالت آئی ہے اور کلبی نے ابو صالح سے، انہوں نے سیدنا ابن عباس رضی اللہ عنہا سے روایت کیا ہے کہ انہوں نے فرمایا:\nمیزان ایسی ہوگی کہ اس کی ایک زبان ہوگی اور اس کی دو ہتھیلیاں یا دو پلڑے ہوں گے۔ اس میں نیکیاں اور بدیاں تولی جائیں گی۔ نیکیاں خوبصورت شکل میں لائی جائیں گی اور میزان کے پلڑے میں رکھ دی جائیں گی اور وہ گناہوں اور غلطیوں کا بھاری ہو جائیں گی۔ ابن عباس رضی اللہ عنہ نے فرمایا کہ پھر وہ اٹھا کر جنت میں ان کے ٹھکانوں کے پاس رکھ جائیں گی۔ پھر مؤمن سے کہا جائے گا۔ آپ اپنے عمل کے ساتھ لاحق ہو جائیے۔ فرمایا کہ پھر وہ جنت کی طرف چلے گا اور اپنے اپنے ٹھکانے کو اپنے اپنے عمل سے پہچان لے گا۔\nاور انہوں نے فرمایا کہ برائیاں بدترین صورت میں لائی جائیں گی اور میزان کے پلڑے میں رکھ دی جائیں گی اور وہ ہلکی پڑ جائیں گی۔ اس لئے کہ باطل ہلکا اور بے وزن ہوتا ہے۔ پھر وہ اٹھا کر جہنم میں ان کے ٹھکانے پر رکھ دی جائیں۔ پھر اس بندے سے کہا جائے گا کہ آپ اپنے عمل کے ساتھ جہنم میں لاحق ہو جائے۔ فرمایا کہ پھر وہ انسان جہنم کی طرف آئے گا اور اپنے عمل کے ذریعے اپنا ٹھکانہ پہچان لے گا اور اس کو بھی جو اللہ نے اس کے لئے مختلف اور رنگ رنگ اور قسم قسم کے عذاب تیار کر رکھے ہوں گے۔ سیدنا ابن عباس رضی اللہ عنہ نے فرمایا کہ وہ سب لوگ اپنے اپنے اعمال کی وجہ سے اپنے اپنے منازل کو اور مقامات کو سب سے زیادہ پہچانے والے ہوں گے وہ جمع ہونے کے دن جائیں گے۔ اپنے اپنے مقامات کی طرف رجوع کرنے والے ہوں گے۔ (1)","",{"k":"(1) أخرجه الحاكم في المستدرک (۲۵۳/۲) من طريق زيد بن أخرم الطائى به وقال الحاكم صحيح الإسناد ولم يخرجاه وقال الذهبى في التلخيص: عتبة واه."}],[264,"ہمیں خبر دی ہے ابو عبد الرحمن دحان نے کہ خبر دی ہے حسین بن محمد ہارون نے کہ ہمیں حدیث بیان کی ہے احمد بن محمد بن نصر نے کہ ہمیں حدیث بیان کی ہے یوسف بن بلال نے کہ ہمیں حدیث بیان کی ہے محمد بن مروان نے کلبی سے، پھر اس نے مذکورہ حدیث کو ذکر کیا ہے۔"],[265,"ہمیں بیان کی ہے ابو عبد اللہ حافظ نے کہ خبر دی ہے عبد اللہ بن حسین قاضی نے کہ ہمیں حدیث بیان کی ہے حارث بن ابی اسامہ نے کہ ہمیں حدیث بیان کی ہے یونس بن محمد نے کہ ہمیں حدیث بیان کی ہے لیث بن سعد نے کہ مجھے حدیث بیان کی ہے عامر بن یحییٰ نے انہوں نے ابو عبد الرحمن معافری حبلی سے، انہوں نے کہا کہ میں نے سنا تھا عبد اللہ بن عمرو بن العاص سے، انہوں نے کہا کہ نبی کریم صلی اللہ علیہ وسلم نے فرمایا:\nبے شک اللہ تعالیٰ سب لوگوں کے سامنے قیامت کے دن ایک انسان کے ساتھ خصوصی بات چیت کریں گے اور اس کے آگے ننانوے رجسٹر کھول کر رکھ دیں گے۔ رجسٹر ڈ تاحد نظر تک لمبا ہوگا۔ پھر اللہ تعالیٰ پوچھیں گے کیا تو اس تحریر کی کسی ایک شے سے انکار کر سکتا ہے؟ کیا میرے محافظ کاتبوں نے تجھ پر ظلم و زیادتی کی ہے؟ وہ بندہ کہے گا نہیں یا رب۔ پھر اللہ تعالیٰ سوال کریں گے کیا تیرے پاس اس کے برعکس کوئی عذر ہے؟ بندہ کہے گا نہیں یا رب۔ پھر اللہ تعالیٰ فرمائیں گے ہاں ہماری پاس تیری ایک نیکی بھی ہے اور آج تیرے اوپر کوئی ظلم نہیں ہوگا۔ چنانچہ ایک پرچہ نکالا جائے گا۔ اس میں لکھا ہوگا اشھد ان لا الہ الا اللہ واشھد ان محمد عبدہ ورسولہ۔ وہ بندہ عرض کرے گا اے میرے رب یہ چھوٹا سا پرچہ اتنے بڑے طوماروں کے مقابلے میں کیا ہے؟ یعنی کچھ بھی تو نہیں ہے۔ اس سے کہا جائے گا کہ تجھ پر ظلم نہیں ہوگا۔ حضور صلی اللہ علیہ وسلم نے فرمایا وہ شہادتین والا پرچہ ایک پلڑے میں رکھ دیا جائے گا اور وہ رجسٹر یا طومار دوسرے پلڑے میں رکھے جائیں گے۔ لہذا وہ دفتر ہلکے پڑ جائیں گے اور وہ شہادتین والا پرچہ بھاری ہو جائے گا اور اللہ کے نام کے مقابلے میں کوئی شے بھاری نہیں ہو سکتی۔ اس کو روایت کیا ہے عبد اللہ بن صالح نے لیث سے اسی اسناد کے ساتھ اور انہوں نے کہا کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا، قیامت کے دن ایک بندے کو پکارا جائے گا تمام لوگوں کے سامنے اور اس کے سامنے ننانوے رجسٹر کھولے جائیں گے۔ پھر آگے حدیث ذکر کی ہے۔ (1)","",{"k":"(1) أخرجه الحاكم (۶/۱) بنفس الإسناد وصححه على شرط مسلم ووافقه الذهبى. وأخرجه الترمذى (۲۳۹۹) من طريق الليث به. وقال حسن غريب."}],[266,"§فصل:...... بڑے بڑے گناہ اور چھوٹے چھوٹے گناہ اور بے حیائیاں\n§گناہوں میں حد سے بڑھ جانا فحش اور فواحش کہلاتا ہے\n§ارشاد باری تعالیٰ ہے:\n§﴿ قل انما حرم ربي الفواحش ما ظهر منها وما بطن ﴾ [الاعراف ۳۳]\n’’فرما دیجئے اے پیغمبر کہ میرے رب نے بے حیائیوں کو حرام قرار دیا ہے۔ خواہ وہ ظاہر ہوں خواہ وہ پوشیدہ اور باطنی ہوں اور ارشاد فرمایا:‘‘\n§﴿ ان تجتنبوا كبائر ما تنهون عنه نكفر عنكم سيئاتكم ﴾ [النساء ۳۱]\n§’’اور تم کبیرہ گناہوں سے پرہیز کرو گے جن سے تمہیں منع کیا گیا ہے۔ مٹا دیں گے ہم تم سے تمہاری غلطیاں۔‘‘\n§اور ارشاد ہے:\n§﴿ والذين يجتنبون كبائر الاثم والفواحش الا اللمم ﴾ [النجم ۳۲]\n’’جو لوگ کبیرہ گناہوں سے اجتناب کرتے ہیں اور بے حیائیوں سے سوائے چھوٹی چھوٹی باتوں کے اور کبائر کی تعداد احادیث نبوی صلی اللہ علیہ وسلم وارد ہوئے ہیں۔‘‘\n§سات ہلاکت خیز جرائم\nہمیں خبر دی ہے ابو زکریا بن ابو اسحاق مزکی نے کہ خبر دی ہے ابو الحسین احمد بن عثمان آدمی نے، انہوں نے کہا ہمیں حدیث بیان کی ہے ابو اسماعیل ترمذی نے کہ ہمیں حدیث بیان کی ہے اویسی نے کہ ہمیں حدیث بیان کی ہے سلیمان بن بلال نے ثور بن زید سے، انہوں نے ابو الغیث سے، انہوں نے سیدنا ابو ہریرہ رضی اللہ عنہ کہ رسول اللہ صلی اللہ علیہ وسلم فرمایا تھا:\nاجتنبوا السبع الموبقات قالوا يا رسول الله وماهن؟ قال الشرك بالله والسحر وقتل النفس التي حرم الله الا بالحق واكل الربا واكل مال اليتيم والتولى يوم الزحف وقذف المحصنات المؤمنات الغافلات\n’’سات ہلاک کرنے والی چیزوں سے بچو۔ لوگوں نے عرض کیا یا رسول اللہ صلی اللہ علیہ وسلم وہ سات چیزیں کونسی ہیں؟ آپ صلی اللہ علیہ وسلم نے فرمایا:‘‘\nبیعت کرنا یعنی پکا عہد کرنا برے کاموں سے بچنے کے لئے سنت ہے\nاور ثابت کی روایت میں سیدنا عبادہ بن صامت رضی اللہ عنہ سے کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا جبکہ آپ صلی اللہ علیہ وسلم کے اردگرد آپ کے صحابہ کی جماعت تھی تم لوگ میرے ہاتھ پر اس بات کی بیعت کرو کہ اللہ کے ساتھ کسی چیز کو شریک نہیں ٹھہراؤ گے اور چوری نہیں کرو گے، زنا یعنی بدکاری نہیں کرو گے۔ اپنی اولاد کو قتل نہیں کرو گے۔ کسی پر بہتان نہیں باندھو گے اور اچھے کام میں نافرمانی نہیں کرو گے۔\nفائدہ:...... ابو ہریرہ رضی اللہ عنہ کی روایت میں سات کبیرہ گناہ، عبید بن عمیر کی روایت میں نو کبیرہ گناہ، انس بن مالک رضی اللہ عنہ کی روایت میں پانچ کبیرہ گناہ، عبداللہ بن عمر رضی اللہ عنہ کی روایت میں تین کبیرہ گناہ، سیدنا ابن عمر رضی اللہ عنہ کی دوسری روایت میں اپنے والدین کو اور دوسرے کے والدین کو گالی دینا کبیرہ گناہ، عبداللہ بن مسعود کی روایت میں تین کبیرہ گناہ۔ عبادہ بن صامت کی روایت میں چھ کبیرہ گناہ مذکور ہیں۔ (مترجم)\nقرآن مجید میں وارد ہونے والی محرمات\nکتاب اللہ میں مندرجہ ذیل کی تحریم وارد ہوئی ہے۔\nتو محرمات کثیر ہیں۔ ہم نے یہ امور اس لئے ذکر کئے ہیں۔ تانکہ ہم صغائر اور کبائر کا جامع بیان کریں۔ ہم اس بارے میں اللہ کے حکم سے تمام ضروری چیزوں کو ذکر کریں گے۔\nکی مجبوری ہو تو اس صورت میں یہی کبیرہ گناہ ہو گی اگرچہ اس چیز کی چوری سے چور پر حد واجب نہیں ہو گی۔ (۱۲)...... اور لوگوں کا مال ناحق لے لینا کبیرہ گناہ ہے۔ اگر لیا ہوا مال مالک کی ضرورت اور مجبوری ہو یا مالک لینے والے کا باپ ہو یا اس کی ماں ہو یا لینے والا جبر و قہر سے لے لے تو یہ فاحشہ ہے اور اسی طرح اگر وہ لینا بطور قمار و جوئے کے ہو تو بھی فاحشہ ہے اور اگر حقیر چیز ہو اور مالک غنی ہو جس کو اس کے لے لینے سے کوئی پریشانی نہ ہو تو یہ صغائر میں سے ہو گا۔ (۱۳)...... شراب نوشی کبیرہ گناہوں میں سے ہے۔ اگر شراب پینے والا زیادہ پی لے یہاں تک کہ نشہ میں ہو جائے یا اس کی وجہ سے برہنہ ہو جائے تو یہ فواحش میں سے ہے۔ اگر شراب میں برابر وزن پانی ملا دیا ہے اور اس کی شدت اور نشہ ختم ہو گیا ہے اور پیتا ہے تو یہ صغیرہ گناہ ہے۔ (۱۴)...... نماز ترک کرنا کبیرہ گناہوں میں سے ہے۔ اگر ترک کرنے کی عادت ہو جائے تو یہ فواحش میں سے ہے۔ اگر نماز تو قائم کرتا ہے مگر اس کا حق نہیں دیتا یعنی خشوع و خضوع سے نہیں پڑھتا اور نماز میں ادھر ادھر متوجہ ہوتا ہے یا انگلیاں چٹخاتا ہے یا نماز میں لوگوں کی باتوں کی طرف کان لگاتا ہے یا نماز میں کنکریاں سیدھی کرتا ہے یا بلا ضرورت کنکریوں وغیرہ کو بلا عذر چھوتا رہتا ہے تو یہ کبیرہ گناہوں میں سے ہے اور اگر اس کو عادت بنا لیتا ہے تو یہ فواحش میں سے ہے۔ (۱۵)...... اگر جماعت ترک کرتا ہے تو یہ صغیرہ گناہوں میں سے ہے اور ترک جماعت کی عادت بنا لیتا ہے اور اس سے وہ جماعت سے دوری اور جدائی رکھنے کی نیت رکھتا ہے یا ان سے الگ تھلگ رہنے کا قصد و نیت کرتا ہے تو یہ کبیرہ گناہ ہے۔ اگر کوئی بستی والے اس عمل پر اتفاق کر لیں یا کوئی شہر والے تو یہ فواحش میں سے ہے۔ (۱۶)...... زکوٰۃ روک لینا ادا نہ کرنا اور سائل کو خالی لوٹا دینا یہ صغیرہ گناہ ہے۔ پس اگر زکوٰۃ کے روک لینے پر لوگ اکٹھے ہو جائیں یا منع کرنا ایک آدمی کی طرف سے ہو مگر منع کرنے کے ساتھ ساتھ وہ ڈانٹ ڈپٹ اور سخت گوئی کا اضافہ بھی کر دے تو یہ بات کبیرہ گناہ ہے۔ اور اسی طرح سے اگر کوئی حاجتمند کسی ایسے آدمی کو دیکھتا ہے جو کھانا دینے کی وسعت رکھتا ہے اور حاجتمند کا دل اس کی طرف مائل ہو جاتا ہے اور وہ اس سے سوال کرتا ہے اور وہ اس کو خالی لوٹا دیتا ہے تو یہ کبیرہ گناہ ہے۔\nشیخ حلیمی نے فرمایا:\nاصل اس باب میں یہ ہے کہ ہر حرام کی ہوئی چیز کسی ذاتی مفہوم اور حقیقت کی وجہ سے ممنوع ہوتی ہے۔ بے شک کسی محرم اور ممنوع چیز (یا کام) کا ایسے طریقہ پر ارتکاب کرنا جس طریقہ سے حرمت کی دو یا زیادہ وجوہ اکٹھی ہو جائیں (وہ کام صرف ممنوع نہیں بلکہ) وہ فاحشہ ہوتا ہے۔ اور اس ممنوع اور محرم کام یا چیز کا ارتکاب ایسے طریقہ پر جس طریقہ سے وہ منصوص کے مرتبہ سے قاصر ہو یا اس کا ارتکاب ماسوائے منصوص کے جو کہ منصوص کے مفہوم کو پورا نہ کر سکے یا منصوص کا ارتکاب جس سے ممانعت ہے اس لئے کہ دوسرے کے لئے ذریعہ نہ ہو، پس یہ (مذکورہ امور) سب کے سب صغائروں میں سے ہیں۔\nاور صغیرہ گناہ کا ارتکاب کرنا ایسے طریقہ پر جو طریقہ حرمت کی دو وجوہ کی یا زیادہ وجوہ کو جمع کرے کبیرہ گناہ بن جاتا ہے۔ اس کی مثال اس تفصیل میں موجود ہے جس کا ذکر ابھی پیچھے گذرا ہے اور اس کا یہاں پر اعادہ بھی (شیخ نے) فرمایا ہے اور جو کچھ ذکر کیا ہے (شیخ نے) اس میں ذریعہ بننے کو زیادہ کیا ہے۔ مثلاً یہ کوئی شخص کسی آدمی کو کسی مطلوب پر دلالت و رہنمائی کرے تانکہ ناحق قتل کرے یا قاتل کو چھری لا کر دے (اس قسم کے فعل کا ارتکاب کرنا) حرام ہے (اور یہ حرمت اس) ارشاد باری تعالیٰ سے ثابت ہے:\n﴿ ولا تعاونوا على الاثم والعدوان ﴾ [المائدہ ۲]\nکہ ایک دوسرے کا تعاون نہ کرو گناہ کے کام پر اور سرکشی کے کام پر لیکن اس کے باوجود وہ صغائر میں سے ہے۔ اس لئے کہ اس کے بارے میں جو نہی ہے اس لئے ہے تاکہ ظلم کے لئے ذریعہ نہ ہو اور وہ اپنے ظلم پر قدرت نہ حاصل کر سکے۔ (اور اسی مذکورہ حکم میں ہے) کسی آدمی کا دوسرے آدمی کو جس پر کہنے والے کی اطاعت لازم بھی نہیں یہ کہنا کہ تو فلاں آدمی کو قتل کر دے یہ کہنا کبیرہ گناہ نہیں ہے۔ اس لئے کہ اس میں دوسرے کی ہلاکت کا ارادہ ہے، فعل قتل و ہلاکت میں شرکت نہیں ہے۔ واللہ اعلم۔\nامام بیہقی رحمۃ اللہ علیہ کا قول:\nامام بیہقی رحمۃ اللہ علیہ فرماتے ہیں کہ ہم (کتاب اللہ میں) پاتے ہیں کہ لفظ فاحشہ کا اطلاق اور وقوع زنا پر ہوا ہے۔ اگرچہ اس کی طرف حرمت کی زیادتی نہیں ملی، لیکن جب اللہ تعالیٰ نے دیکھا کہ کبائر اور فواحش میں فرق ہے ذکر میں تو اللہ تعالیٰ نے دونوں کے مابین فرق کیا ہے۔ پس ہر وہ چیز جس کا ذکر بھی زیادہ فحش ہے اس کو کبیرہ پر زیادہ کیا ہے۔ واللہ اعلم۔\nمقاتل بن سلیمان کا قول:\nمقاتل بن سلیمان نے وضاحت کی ہے کہ کبیرہ گناہ وہ ہیں جن پر جہنم کی دھمکی ہے یا جن کا انجام جہنم ہے اور فواحش وہ گناہ ہیں جن پر دنیا میں حد قائم کی جائے۔ تحقیق شیخ حلیمی اور ان کے ائمہ کا کلام دلالت کرتا ہے کہ صغیرہ گناہ پر اصرار کرنا کبیرہ گناہ بن جاتا ہے۔ تحقیق ایسی احادیث اور حکایات وارد ہوئی ہیں جو صغیرہ گناہوں سے اجتناب کرنے پر ابھارتی ہیں۔ اس بات کے ڈر کے لئے کہ کہیں ان پر اصرار کے نتیجے میں وہ کبیرہ گناہ نہ بن جائے۔ (1)","",{"k":"(1) اللہ کے ساتھ شرک کرنا۔ جادو کرنا۔ ناحق کسی نفس کو قتل کرنا جس کو اللہ نے حرام کیا ہے مگر حق کے ساتھ۔ سود کھانا۔ یتیم کا مال کھانا۔ میدان جہاد سے فرار ہونا۔ پاکدامن مؤمنہ گناہ سے بے خبر عورتوں کو ناحق تہمت لگانا۔ اس کو بخاری نے اپنی صحیح میں عبد العزیز بن عبد اللہ اویسی سے روایت کیا ہے اور مسلم نے اس کو دوسرے طریق سے سلیمان سے روایت کیا ہے۔ امام احمد بن حنبل رحمۃ اللہ علیہ کا قول: امام احمد رحمۃ اللہ علیہ نے فرمایا کہ کبیرہ گناہوں کو سات کی تعداد میں مقید کرنے کا مطلب سات میں بند کرنا نہیں اور سات سے زیادہ کو منع کرنا مقصد نہیں ہے۔ صرف اس میں ان سے بچنے کی تاکید مقصود ہے۔ پھر آپ صلی اللہ علیہ وسلم نے ان کے ساتھ ان کے علاوہ کو بھی ان میں شامل کیا تھا۔ اور ہم نے عبید بن عمیر سے، انہوں نے اپنے باپ سے، انہوں نے نبی کریم صلی اللہ علیہ وسلم سے روایت کیا ہے کہ الکبائر تسع۔ کبیرہ گناہ نو ہیں۔ پھر سات مذکورہ اور دو مزید کا ذکر فرمایا ہے۔ وہ یہ ہیں: أخرجه البخارى (۱۲/۴) عن عبد العزيز بن عبد الله الأويسى به. وأخرجه مسلم (۹۲/۱) من طريق ابن وهب عن سليمان بن بلال به. ایک والدین کی نافرمانی کرنا۔ بیت الحرام کی بے حرمتی کرنا۔ عقوق الوالدين، واستحلال البيت الحرام اور حضرت ثابت کی روایت میں سیدنا انس بن مالک رضی اللہ عنہ سے مروی ہے کہ نبی کریم صلی اللہ علیہ وسلم سے کبیرہ گناہوں کے بارے میں پوچھا گیا تو آپ صلی اللہ علیہ وسلم نے فرمایا: الشرك بالله. وقتل النفس. وعقوق الوالدين. وقال الا انبئكم باكبر الكبائر. قوله الزها او قال شهادة الزور بدل اقول الزور اللہ کے ساتھ شرک کرنا۔ کسی نفس کو قتل کرنا۔ والدین کی نافرمانی کرنا۔ پھر آپ صلی اللہ علیہ وسلم نے فرمایا کیا میں تمہیں سب کبیروں سے بڑا کبیرہ گناہ نہ بتا دوں۔ وہ ہے جھوٹی بات کرنا فرمایا تھا جھوٹی گواہی دینا، جھوٹی بات کی جگہ کہا تھا۔ اور حدیث ثابت میں سیدنا عبداللہ بن عمر رضی اللہ عنہ سے روایت ہے کہ انہوں نے فرمایا کہ ایک دیہاتی رسول اللہ صلی اللہ علیہ وسلم کی خدمت میں آیا اور عرض کرنے لگا کہ کبیرہ گناہ کون کون سے ہیں؟ آپ صلی اللہ علیہ وسلم نے جواب دیا: اللہ کے ساتھ شرک کرنا۔ اس نے پوچھا اس کے بعد کونسا؟ آپ صلی اللہ علیہ وسلم نے فرمایا: والدین کی نافرمانی کرنا۔ اس نے پوچھا اس کے بعد کیا؟ آپ صلی اللہ علیہ وسلم نے فرمایا: جھوٹی قسم کھانا۔ کسی کے والدین کو برا کہنا ایسے ہے جیسے اپنے والدین کو گالی دینا اور ثابت کی روایت میں سیدنا عبداللہ بن عمر رضی اللہ عنہ نبی کریم صلی اللہ علیہ وسلم سے روایت فرماتے ہیں کہ آپ صلی اللہ علیہ وسلم نے فرمایا کہ کبیرہ گناہوں میں سے ہے کہ کوئی انسان اپنے والدین کو گالیاں دے۔ لوگوں نے پوچھا اے اللہ کے رسول صلی اللہ علیہ وسلم اپنے ماں باپ کو بھی کوئی بھلا گالیاں دیتا ہے؟ آپ صلی اللہ علیہ وسلم نے فرمایا، ہاں دیتا ہے کہ یہ کسی کے باپ کو گالیاں دیتا ہے اور وہ بھی اس کے باپ کو یہ کسی کی ماں کو گالی دیتا ہے اور وہ جواب میں اس کی ماں کو گالی دیتا ہے۔ تین کبیرہ گناہ اور اسی طرح ثابت کی روایت میں عبداللہ بن مسعود رضی اللہ عنہ سے کہ انہوں نے فرمایا کہ میں نے عرض کیا اے اللہ کے رسول صلی اللہ علیہ وسلم اللہ کے نزدیک سب سے بڑا گناہ کونسا ہے؟ آپ صلی اللہ علیہ وسلم نے فرمایا کہ سب سے بڑا گناہ یہ ہے کہ تو اللہ کا شریک ٹھہرائے حالانکہ اس نے تجھے پیدا کیا ہے۔ پھر میں نے پوچھا کہ اس کے بعد کونسا گناہ بڑا ہے۔ آپ صلی اللہ علیہ وسلم نے فرمایا کہ تو اپنے بیٹے کو اس لئے قتل کرے وہ تیرا کھائے گا۔ میں نے عرض کیا اس کے بعد کونسا بڑا گناہ ہے؟ آپ صلی اللہ علیہ وسلم نے فرمایا کہ تو اپنے پڑوسی کی بیوی سے زنا کرے۔ مری ہوئی چیز کی حرمت۔ خون کی حرمت۔ سور کے گوشت کی حرمت اور ان کے ساتھ مذکورہ تمام چیزوں کی حرمت ان میں یہ بھی مذکور ہیں: شراب کی حرمت۔ جوئے کی حرمت اور اس میں یہ بھی وارد ہوئی ہے۔ یتیم کا ناحق مال کھانے کی حرمت۔ باطل طریقہ سے لوگوں کے مال کھانے کی حرمت۔ ناحق قتل نفس کی حرمت۔ زنا کی حرمت۔ چوری کی حرمت وغیرہ۔ یہ تمام امور اپنی اپنی جگہ مذکور ہیں۔ جبکہ سنت میں سیدنا جابر بن عبداللہ کی روایت میں نبی کریم صلی اللہ علیہ وسلم سے مروی ہے: ليس بين العبد وبين الشرك الا ترك الصلاة بندے اور مشرک کے مابین فرق نماز نہ پڑھنا ہے۔ اس سے شاید آپ صلی اللہ علیہ وسلم کی مراد صلوٰۃ کی تخصیص ہے۔ وجوب قتل کے لئے اس کی ترک کے ساتھ۔ قول شیخ حلیمی: شیخ حلیمی رحمۃ اللہ علیہ اس سلسلے میں وہی امور لائے ہیں جنہیں ہم نے ذکر کیا ہے۔ اس کے بعد فرمایا کہ کتاب وسنت میں جب جستجو کی جائے ہم کہتے ہیں کہ ناحق کسی نفس کو قتل کرنا کبیرہ گناہ ہے۔ اگر مقتول باپ ہو یا بیٹا یا فی الجملہ وہ قریبی رشتہ دار ہو یا بالکل غیر ہو، حرمت ہو یا محترم بوجہ اشہر حرام ہو۔ یہ گناہ کبیرہ ہے۔ فاحشہ اور بے حیائی ہے بال نوچنا اور ڈنڈے سے پیٹنا وغیرہ ایک بار یا دو بار یہ صغیرہ گناہوں میں سے ہے۔ (۲)...... اور زنا (بدکاری) گناہ کبیرہ ہے۔ اگر وہ پڑوسی کی عزت سے ہو یا کسی اور عزت والی، حرمت والی سے ہو یا ان دونوں سے تو نہ ہو، لیکن اگر یہ فعل بلاد الحرام یعنی مکہ اور مدینہ میں یا ماہ رمضان میں ہو تو پھر یہ فاحشہ اور بے حیائی ہے۔ ارشاد باری تعالیٰ ہے: ﴿ومن يرد فيه بالحاد بظلم نذقه من عذاب اليم﴾ (الحج ۲۵) ’’جو شخص حرم میں بے دینی کا ارادہ کرے ظلم کے ساتھ ہم اس کو درد دینے والا عذاب دکھائیں گے۔‘‘ بہر حال زنا موجب للحد کے سوا باقی فعل صغیرہ گناہوں میں سے ہے۔ اگرچہ باپ کی منکوحہ سے ہو یا بیٹے کی بیوہ سے ہو۔ اجنبی یعنی غیر رانڈ بیوہ سے ہو لیکن اگر بالجبر ہو گا تو پھر وہ کبیرہ گناہ ہو گا۔ (۴)...... اور پاکدامن عورت کو جھوٹی زنا کی تہمت لگانا کبیرہ گناہ ہے۔ اگر تہمت لگنے والی خاتون ماں ہو (تہمت لگانے والے کی) یا بہن ہو یا اس کی بیوہ ہو زانیہ ہو تو پھر یہ تہمت فحاشی اور بے حیائی ہو گی۔ (۵)...... نابالغ لڑکی کو تہمت لگانا، لونڈی کو لگانا، آزاد عورت جس کی عزت اتر چکی ہو، یہ سب صغائر میں سے ہیں۔ (۶)...... خیانت، جھوٹ اور چوری کی تہمت کا بھی یہی حال ہے۔ (۷)...... میدان جہاد سے فرار کبیرہ گناہ ہے۔ اگر فرار ہونے والا ایک اکیلے کو یا دو کمزوروں کو چھوڑ کر فرار ہوا ہے جبکہ یہ دونوں سے قوی اور طاقتور تھا یا دونوں یا ایک بغیر ہتھیار کے رہے اور فرار ہونے والا مسلح تھا اور اسلحہ سمیت بھاگا تو یہ فحش کام بھی ہو گا۔ (۸)...... والدین کی نافرمانی کبیرہ گناہ ہے۔ اگر نافرمانی کے ساتھ ساتھ گالی گلوچ کیا ہے یا مار پیٹائی کی ہے تو یہ فحاشی اور بے حیائی بھی ہے۔ اگر نافرمانی بوجہ بھاری سمجھنے کے ہے، ان کے حکم کو یا دونوں کی نہی کو یا دونوں کے چہروں پر تیوری چڑھنے کے سبب سے ہے یا دونوں سے الگ تھلگ رہنے کے لئے ہے مگر ساتھ ساتھ اطاعت کرتا ہے اور خاموشی کو لازم رکھنے کے لئے ہے تو یہ صغیرہ گناہ ہے۔ اگر اس کا سارا عمل ان کو مجبور کرتا ہے کہ وہ اس سے کھینچ جائیں اور اس کو کوئی امر یا نہی نہ کریں اور ان کو اس سے صدمہ یا نقصان پہنچتا ہے تو یہ کبیرہ گناہ ہے۔ (۹)...... چوری کبیرہ گناہ ہے، لیکن چوری کے ساتھ ساتھ ڈاکہ ڈالنا فاحشہ ہے۔ اس لئے چور کا ہاتھ کاٹا جاتا ہے اور ڈاکو کا ہاتھ اور پیر مخالف سمت سے کاٹا جاتا ہے۔ (۱۰)...... اور ڈاکہ کے ساتھ بندے کو قتل کرنا فاحشہ ہے۔ اس لئے والی کو اس کا معاف کرنا بھی عمل نہیں کرتا۔ جب وہ توبہ سے قبل اس پر قادر ہو۔ (۱۱)...... بے کار اور حقیر چیز کی چوری صغیرہ گناہ ہے۔ جس شخص کی چوری ہوئی ہے اگر وہ مسکین ہو اور وہ مسروقہ چیز اس کی ضرورت ہو بلکہ اس"}],[267,"§اپنے اعمال کو بے وقار کرنے والے امور سے بچو\nہمیں خبر دی ہے ابو بکر بن محمد بن حسن بن فورک رحمۃ اللہ علیہ نے کہ ہمیں حدیث بیان کی ہے عبداللہ بن جعفر اصفہانی نے کہ ہمیں حدیث بیان کی ہے یونس بن حبیب نے کہ خبر دی ہے ابو داؤد نے کہ ہمیں حدیث بیان کی ہے عمران قطان نے قتادہ سے، انہوں نے عبد ربہ سے، انہوں نے ابو عیاض سے، انہوں نے عبداللہ بن مسعود رضی اللہ عنہ سے یہ کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا کہ: تم لوگ بچاؤ اپنے آپ کو اعمال کو حقیر و بے وزن کرنے والے امور سے۔ وہ انسان میں اکٹھے ہو کر اس کو ہلاک کر ڈالتے ہیں۔ رسول اللہ صلی اللہ علیہ وسلم نے اس کی مثال بیان فرمائی ہے، جیسے کچھ لوگ مل کر کسی میدان یا جنگل میں اترتے ہیں اور قوم کے کاریگر آتے ہیں، کوئی آدمی لکڑی لاتا ہے، کوئی چھوٹی سی لکڑی لاتا ہے، حتی کہ ایک ڈھیر جمع ہو جاتا ہے، پھر وہ آگ سلگاتے ہیں اور وہ اس سب کو کھا جاتی ہے جو اس میں پھینکا جائے۔\nبلال بن سعد کا ارشاد: (1)","",{"k":"(1) أخرجه البيهقي من طريق أبي داود الطيالسي في مسنده (۴۰۰)"}],[268,"ہمیں خبر دی ہے ابو الحسن بن بشران نے کہ خبر دی ہے دعلج بن احمد بن دعلج نے کہ ہمیں حدیث بیان کی ہے محمد بن اسماعیل بن مہران اسماعیلی نے کہ ہمیں حدیث بیان کی ہے عمر بن عثمان نے کہ ہمیں حدیث بیان کی ہے ولید بن مسلم نے اوزاعی سے، انہوں نے کہا کہ میں نے سنا بلال بن سعد سے، وہ فرماتے تھے: تم گناہ اور غلطی کے چھوٹے ہونے کو نہ دیکھو بلکہ یہ دیکھو کہ تم نافرمانی کتنی بڑی ذات کی کر رہے ہو۔\nعباس بن عطاء کا ارشاد:"],[269,"ہمیں خبر دی ہے ابو عبدالرحمن سلمی نے کہ میں نے منصور بن عبداللہ سے سنا کہ وہ اس کو کہتے تھے کہ میں نے سنا عباس بن عطاء سے وہ فرماتے تھے کہ: پرہیز گاروں کی پرہیز گاری اور متقیوں کا تقویٰ ذرے اور رائی کے دانے سے پیدا ہوتا ہے اور ہمارا رب وہ ہے جو خیال و نظر پر پیٹھ پیچھے عیب لگانے، سامنے طعنہ پر بھی حساب لے گا اور وہ محاسبہ کرنے میں ہر چیز کو شامل کرنے والا اور احاطہ کرنے والا ہے اور اس سے زیادہ سخت بات یہ ہے کہ وہ ذرے ذرے کی مقداروں اور رائی کے دانوں کے برابر بھی حساب لے گا۔ جس ذات کا حساب ایسا سخت ہو وہ واقعی اس بات کی حقدار ہے کہ اس سے بچا جائے اور تقویٰ اختیار کیا جائے۔"],[270,"ہمیں خبر دی ہے ابو الحسین بن فضل قطان نے کہ ہمیں حدیث بیان کی ہے عبداللہ بن جعفر نے کہ ہمیں حدیث بیان کی ہے یعقوب بن سفیان نے کہ ہمیں حدیث بیان کی ہے زید بن بشر نے کہ خبر دی ہے ابن وہب نے کہ ہمیں حدیث بیان کی ہے ابن زید نے اور ذکر کیا ہے عمرو نے اور ابا بکر ابن المنکدر کے دو بیٹوں کا انہوں نے فرمایا کہ: دونوں میں سے ایک پر جب موت آئی تو وہ رو پڑا۔ پوچھا گیا کہ آپ کو کس چیز نے رلایا، ہم تو آپ کے موت اچھا ہونے پر رشک کرتے ہیں؟ انہوں نے فرمایا کہ میں اس لئے نہیں رویا کہ خدانخواستہ میں نے اللہ کی کسی نافرمانی و گناہ کرنے کی جسارت کر لی تھی۔ لیکن اس بات سے ڈرتا ہوں کہ کہیں ایسا نہ ہو کہ میں کسی چیز کو معمولی سمجھ کر کرتا رہا ہوں اور وہ اللہ کے ہاں بہت بڑی ہو (اور اس کا مجھ سے محاسبہ ہو جائے)۔ اور دوسرے بیٹے اپنی موت کے وقت روئے، ان سے رونے کی وجہ پوچھی گئی تو فرمایا کہ میں نے سنا ہے کہ اللہ تعالیٰ ایک قوم کے لئے فرماتے ہیں:\n﴿ وبدا لهم من الله ما لم يكونو يحتسبون ﴾ [الزمر ۴۷]\n’’ان پر اللہ کی طرف سے وہ امر ظاہر ہو جائے گا جس کا وہ گمان بھی نہ کرتے تھے۔‘‘\nمیں وہی کچھ دیکھ رہا ہوں جو تم سب دیکھ رہے ہو اور اللہ کی قسم میں بالکل نہیں جانتا کہ اللہ کے ہاں میرے سامنے کیا کچھ ظاہر ہو گا؟ اور کیا کچھ سامنے آئے گا؟ اور انہوں نے فرمایا: کہا جاتا ہے کہ محمد ان کا بھائی تھا (محمد بن منکدر عابد تھے) اور عبادت میں ان سے قریب تر تھا اور کون سی چیز تھے محمد اپنے زمانے میں؟"],[271,"ہمیں خبر دی ہے ابو الحسن بن بشران نے کہ خبر دی ہے ابو الحسن احمد بن اسحق طیبی نے کہ ہمیں حدیث بیان کی ہے ابراہیم بن حسین ہمدانی نے کہ ہمیں حدیث بیان کی ہے آدم بن ابو ایاس نے کہ ہمیں حدیث بیان کی ہے ضمرہ بن ربیعہ نے حضرت سفیان ثوری سے اللہ تعالیٰ کے اس فرمان کے بارے میں:\n﴿ فيغفر لمن يشاء يعذب من يشاء ﴾ [البقرہ ۲۸۴]\n’’اللہ تعالیٰ جسے چاہیں گے معاف فرما دیں گے اور جسے چاہیں گے عذاب دیں گے۔‘‘\nفرمایا کہ جس کو چاہیں گے بڑے سے بڑے گناہ پر معاف کر دیں گے اور جس کو چاہیں گے چھوٹے سے چھوٹے گناہ پر عذاب دیں گے۔\nسیدنا ابن عباس رضی اللہ عنہ سے روایت ہے کہ صغائر اور کبائر میں فرق ہے۔\nاور ان سے یہ بھی روایت ہے کہ ان میں کوئی فرق نہیں ہے۔\nکبیرہ گناہ وہ ہے جس پر جہنم یا عذاب یا لعنت کی وعید آئی ہے\nابن عباس رضی اللہ عنہ کا قول ہے: (1)","",{"k":"(1) عزاه السيوطي في الدر المنثور (۳۸۶/۱) لابن أبي حاتم عن مجاهد."}],[272,"ہمیں خبر دی ہے ابو زکریا ابن ابو الحق مزکی نے کہ ہمیں حدیث بیان کی ہے کہ ابو الحسن طرائی نے کہ ہمیں حدیث بیان کی ہے عثمان بن سعید دارمی نے کہ ہمیں حدیث بیان کی ہے عبداللہ بن صالح نے معاویہ بن صالح سے انہوں نے علی بن ابو طلحہ سے انہوں نے ابن عباس سے اللہ تعالیٰ کے اس ارشاد کے بارے میں:\n﴿ ان تجتنبوا كبائر ما تنهون عنه ﴾ [النساء ۳۱]\n’’اگر تم بڑے بڑے گناہوں سے پرہیز کرو جس سے تم منع کئے گئے ہو۔‘‘\nفرمایا کہ کبیرہ گناہ ہیں جن کو اللہ تعالیٰ نے آگ کے ذکر کے ساتھ ختم کیا ہے یا عذاب یا غضب یا لعنت کے ساتھ ختم کیا ہے۔\nاکبر الکبائر شرک ہے\nابن عباس رضی اللہ عنہ کا قول ہے: (1)","",{"k":"(1) عزاه السيوطي في الدر المنثور (۱۴۶/۲) لابن أبي حاتم عن ابن عباس"}],[273,"مذکورہ اسناد کے ساتھ سیدنا ابن عباس رضی اللہ عنہ سے مروی ہے کہ تمام کبیرہ گناہوں میں سے بڑا گناہ اللہ تعالیٰ کے ساتھ شرک کرنا ہے۔ اس لئے کہ اللہ تعالیٰ فرماتا ہے:\nجو مال دبا دبا کر رکھتے ہیں اس کی زکوٰۃ نہیں دیتے قیامت میں ان کی پیشانیاں داغی جائیں گی۔\nجھوٹی گواہی دینا اور گواہی چھپانا بھی کبیرہ گناہ ہے۔ کیونکہ اللہ تعالیٰ کا فرمان ہے:\nعباس رضی اللہ عنہ سے کہا گیا ہے کہ کبیرہ گناہ سات ہیں؟ انہوں نے فرمایا: قریب قریب ستر ہیں۔\nامام بیہقی رحمۃ اللہ علیہ کا قول:\nامام بیہقی رحمۃ اللہ علیہ نے فرمایا کہ: ابن عباس رضی اللہ عنہ کا یہ قول احتمال رکھتا ہے کہ یہ انہوں نے اللہ کی حرمتوں کی تعظیم میں اور محرمات کے ارتکاب سے ترہیب اور ڈرانے کے لئے فرمایا ہو۔ بہر حال صغائر اور کبائر کے مابین فرق کرنا دنیا اور آخرت کے احکامات سے لازمی اور ضروری ہے ان نصوص کی بنیاد پر جو کتاب و سنت میں آئی ہیں۔\nمسلمان اہل قبلہ بڑے بڑے گناہوں کے مرتکب لوگ قیامت میں جب بغیر توبہ کے آئیں گے\nہمارے احباب رضی اللہ عنہم نے فرمایا کہ: اصحاب کبائر اہل قبلہ جب قیامت میں بغیر توبہ کئے آئیں گے ان کا معاملہ اللہ تعالیٰ کے حوالے ہے۔ اگر چاہے گا تو ان کو ابتداء ہی میں معاف کر دے گا۔ اگر چاہے گا تو ان کے حق میں ان کے نبی کی شفاعت قبول کر لے گا۔ اگر چاہے گا تو ان کو جہنم میں داخل کرنے کا حکم فرمائے گا۔ پھر وہ ایک خاص مدت تک عذاب میں مبتلا رہیں گے۔ پھر ان کو جہنم سے جنت کی طرف نکالنے کا حکم دے گا یا شفاعت کے ساتھ یا بغیر شفاعت کے۔ اور ہمیشہ جہنم میں تو صرف کفار ہی رکھے جائیں گے۔\nہمارے احباب نے اس بات پر استدلال اللہ تعالیٰ کے اس قول سے کیا ہے:\n﴿ بلى من كسب سيئة واحاطت به خطيئته الخ ﴾ [البقرہ ۸۱]\n’’ہاں جس نے برائی کا کسب کیا اور اس کے گناہوں نے اس کو احاطہ میں لے لیا۔ وہی لوگ جہنمی ہیں اور وہ ہمیشہ اسی میں رہیں گے۔‘‘\nاس آیت میں اللہ تعالیٰ نے یہ خبر دی ہے کہ ہمیشہ آگ میں رکھنا اس کے لئے ہے جس کو اس کے گناہوں نے گھیر لیا ہو گا۔ (وہ کافر ہی ہو سکتا ہے) اس لئے کہ مؤمن ایک کبیرہ گناہ کا مرتکب ہو یا بہت سے کبائر کا اس کے گناہوں نے اس کا احاطہ نہیں کیا ہوتا، اس لئے کہ تمام گناہوں کا سردار اور بڑا گناہ کفر ہے۔ وہ مؤمن کے گناہوں میں موجود نہیں ہوتا ہے۔ لہذا یہ صحیح ہوا کہ وہ ہمیشہ آگ میں نہیں رہے گا۔\nاگر یہ اعتراض کیا جائے کہ یہ آیت اللہ تعالیٰ کے اس دوسرے قول کے معارض و مخالف ہے۔ وہ یہ ہے:\n﴿ والذين امنوا وعملوا الصالحات اولئك اصحب الجنة هم فيها خالدون ﴾ [البقرہ ۸۲]\n’’وہ لوگ جو ایمان لائے ہیں اور انہوں نے نیک عمل کئے ہیں وہی لوگ جنتی ہیں، وہ اس میں ہمیشہ رہیں گے۔‘‘\nاس آیت میں اللہ تعالیٰ نے جنت کا وعدہ دیا ہے اس شخص کو جس نے ایمان کی اصل اور اس کی فروع (دونوں چیزیں) جمع کر لی ہیں۔ جبکہ کبیرہ گناہ کا مرتکب یا کبائر کا مرتکب صالحات اور نیک اعمال کا تارک ہوتا ہے۔ تو یہ بات صحیح ہو گی کہ جنت والا وعدہ اس کے لئے نہیں ہے۔ تو معترض کو جواباً یہ کہا جائے گا کہ کبیرہ یا کبائر کا مرتکب جب ان سے توبہ کر لے اور قیامت میں ان گناہوں سے تائب ہو کر آئے، مگر صالحات اور نیکیوں کا تارک ہو ایمان کے اور اس کی فروعات کے مابین جمع کرنے والا نہ ہو اس کے باوجود وہ جنت میں داخل ہو گا۔ حالانکہ اس کی توبہ ان نیکیوں کے قائم مقام نہیں ہو سکتی جو اس نے چھوڑی ہیں۔ اس لئے کہ اس کے اوپر شر اور برائی سے ہمیشہ دور رہنا لازم تھا۔ پس جب اس نے کچھ وقت شر اور گناہ کا اقدام و ارتکاب کیا اور پھر کچھ وقت اس سے دور ہو گیا تو گویا ایسا کرنے سے وہ کچھ فرض کو ادا کرنے والا (اور کچھ کا تارک ہوا) اور کچھ فرض ممکن نہیں ہے اور جائز نہیں ہے کہ پورے فرض کا بدل سکے۔ اور جب یہ بات ممکن ہے اور جائز ہے کہ اللہ تعالیٰ گناہوں سے تائب ہونے والے پر احسان فرمائے اور اس کی توبہ کے بدلے میں اس کے گناہ معاف کر دے تو یہ کیونکر درست نہیں ہو گا کہ اللہ تعالیٰ گناہوں پر اصرار کرنے والے پر بھی احسان فرمائے اور اس کے ایمان کے سبب جو کہ تمام نیکیوں سے احسن اور بہتر نیکی ہے اس کے گناہ معاف فرما دے؟ اور اس کی صلوٰۃ اور دیگر بعض حسنات کے سبب وہ غلطیاں بھی مٹا دے جو اس کی سیئات کی مدت میں داخل ہو گئی تھیں۔ جیسے کہ اللہ تعالیٰ نے خود ارشاد فرمایا ہے:\n﴿ ان الحسنات يذهبن السيئات ﴾ [ہود ۱۱۴]\n’’بے شک نیکیاں برائیوں کو ختم کر دیتی ہیں۔‘‘\nاس کو لے لیجئے اور محفوظ اور یاد رکھئے۔ دونوں اس بات میں ایک دوسرے سے مختلف ہیں اور جدا ہیں کہ تائب مغفور ہوتا ہے بغیر عذاب دینے کے اور گناہوں پر اصرار کرنے والا بھی اپنے گناہوں کے سبب کچھ مدت تک عذاب دیا جائے گا، پھر جنت میں داخل کیا جائے گا۔ اس لئے کہ خبر صادق اس کے بارے میں وارد ہو چکی ہے اور ہمارے اصحاب نے اس پر اللہ تعالیٰ کے اس فرمان کے ساتھ استدلال کیا ہے:\n﴿ ان الله لا يغفر ان يشرك به ويغفر ما دون ذالك لمن يشاء ﴾ [النساء ۱۱۶]\n’’بے شک اللہ تعالیٰ نہیں معاف فرمائے گا اس بات کو کہ اس کے ساتھ شریک ٹھہرایا جائے اور معاف فرما دے گا اس کے ماسوا (گناہ) جس کے لئے چاہے گا۔‘‘\nاور یہ جائز نہیں ہے کہ اللہ تعالیٰ کی خبر میں اختلاف فرض کر لیا جائے اور اس کے ساتھ حدیث بھی نبی کریم صلی اللہ علیہ وسلم سے وارد ہوئی ہے۔ (1)","",{"k":"(1) ﴿انه من يشرك بالله فقد حرم الله عليه الجنة﴾ (المائدہ ۷۲) بے شک جو شخص اللہ کے ساتھ شریک بنائے تحقیق اللہ نے اس پر جنت حرام کر دی۔ اللہ تعالیٰ کی رحمت اور مہربانی سے مایوسی (کے ذکر کے ساتھ مذکور ہونا بھی کبیرہ گناہ ہونے کی نشانی ہے) کیونکہ اللہ تعالیٰ فرماتے ہیں: ﴿لا ييناس من رحمة الله الا القوم الكافرون﴾ (یوسف ۸۷) اللہ کے لطف و کرم سے ناامید نہیں ہوتے مگر کافر۔ اور اللہ کی تدبیر اور گرفت سے نڈر و بے باک ہونا (یہ بھی کبیرہ گناہ ہونے کی علامت ہے)۔ ارشاد باری ہے: ﴿فلا يامن مكر الله الا القوم الخاسرون﴾ (اعراف ۹۹) اللہ تعالیٰ کی تدبیر سے بے خوف نہیں ہوتے مگر خسارے پانے والے لوگ۔ انہیں کبیرہ گناہوں میں سے ہے والدہ کا نافرمان ہونا۔ اس لئے کہ اللہ تعالیٰ نے نافرمان کو جبار اور شقی اور عصی سرکش، بدبخت، نافرمان قرار دیا ہے۔ اور انہیں میں سے ہے اس نفس کو قتل کرنا جس کو اللہ نے حرام کیا ہے بغیر حق کے۔ کیونکہ اللہ تعالیٰ کا ارشاد ہے: ﴿جزاءه جهنم﴾ (النساء ۹۳) کہ قاتل کی سزا جہنم ہے۔ اور پاکدامن عورت کو بدکاری کی تہمت لگانا کبیرہ گناہ ہے، کیونکہ اللہ تعالیٰ فرماتے ہیں: ﴿لعنوا في الدنيا والاخرة ولهم عذاب عظيم﴾ (النور ۲۳) دنیا آخرت میں تہمت لگانے والے لعنت کئے گئے ہیں اور ان کے لئے عذاب عظیم ہے۔ یتیم کا ناحق مال کھانا کبیرہ گناہ ہے۔ اس لئے کہ اللہ تعالیٰ کا ارشاد ہے: ﴿ان الذين ياكلون اموال اليتمى ظلما انما ياكلون في بطونهم نارا وسيصلون سعيرا﴾ (النساء ۱۰) بے شک جو لوگ یتیموں کا مال کھاتے ہیں ناحق وہ اپنے پیٹوں میں آگ بھرتے ہیں، وہ عنقریب جہنم میں داخل ہوں گے۔ میدان جہاد سے فرار ہونا کبیرہ گناہ ہے۔ اس لئے کہ اللہ تعالیٰ فرماتے ہیں: ﴿ومن يولهم يومئذ دبره الا متحرفا لقتال او متحيزا الى فئة فقد باء بغضب من الله﴾ (انفال ۱۶) جس شخص نے (اس دن جہاد میں) پیٹھ پھیر لی، اس کے ماسوا جس نے جنگ کی چال چلنے یا دوسری اپنی ٹولی سے ملنے کے لئے پیٹھ پھیری۔ (جس نے فرار کے لئے پیٹھ پھیری) اس نے اللہ کے غضب کی طرف رجوع کیا۔ کبیرہ گناہوں میں سے سود خوری بھی ہے۔ کیونکہ اللہ تعالیٰ کا ارشاد ہے: ﴿الذين ياكلون الربوا لا يقومون الا كما يقوم الذي يتخبطه الشيطن من المس﴾ (البقرہ ۲۷۵) جو لوگ سود کھاتے ہیں قبروں سے نہیں کھڑے ہوں گے مگر مثل اس شخص جو کھڑا ہوتا مخبوط الحواس شیطان کے چھوڑنے سے اور کبیرہ گناہ سحر ہے۔ کیونکہ اللہ تعالیٰ فرماتے ہیں: ﴿ولقد علموا لمن اشتراه ماله في الاخرة من خلاق﴾ (البقرہ ۱۰۲) البتہ تحقیق وہ جانتے ہیں کہ البتہ جو اس کو خریدتا ہے اس کے لئے آخرت میں کوئی حصہ نہیں ہے اور کبیرہ گناہ زنا (بدکاری) بھی ہے۔ کیونکہ اللہ تعالیٰ کا فرمان ہے: ﴿ومن يفعل ذالك يلق اثاما يضاعف له العذاب يوم القيمة ويخلد فيه مهانا﴾ (الفرقان ۶۹) جو شخص اس کا ارتکاب کرے وہ کئی گناہوں کو ملتا ہے اس کے لئے دو گنا عذاب ہو گا قیامت کے دن اور اس میں ذلیل ہو گا اور جھوٹی اور گناہ کی قسم بھی کبیرہ گناہ ہے۔ کیونکہ اللہ تعالیٰ فرماتے ہیں: ﴿ان الذين يشترون بعهد الله وايمانهم ثمنا قليلا اولئك لا خلاق لهم في الاخرة﴾ (آل عمران ۷۷) بے شک جو لوگ خرید کرتے ہیں اللہ کے عہد اور اپنی قسموں کے بدلے میں حقیری قیمت وہی لوگ ہیں جن کے لئے آخرت میں کوئی حصہ نہیں ہے۔ غلول اور مال غنیمت کی چوری بھی کبیرہ گناہ ہے۔ کیونکہ اللہ تعالیٰ فرماتے ہیں: ﴿ومن يغلل يات بما غل يوم القيمة﴾ (آل عمران ۱۶۱) جو شخص مال غنیمت میں چوری کرے گا قیامت کے دن چرائی ہوئی چیز لے کر آئے گا۔ فرض زکوٰۃ کو منع کرنا یعنی نہ دینا یہ بھی کبیرہ گناہ ہے۔ کیونکہ اللہ تعالیٰ کا فرمان ہے: ﴿فتكوى بها جباههم﴾ (التوبہ ۳۵) ﴿ومن يكتمها فانه اثم قلبه﴾ (البقرہ ۲۸۳) جو شخص شہادت کو چھپائے گا اس کا دل گناہگار ہے۔ اور شراب پینا اس لئے کہ اللہ تعالیٰ نے بتوں کی پوجا کو اس کے برابر کیا ہے اور جان بوجھ کر نماز چھوڑ دینا یا اللہ کی فرض کردہ چیزوں میں سے کوئی چیز ترک کرنا یہ بھی کبیرہ گناہ ہیں، کیونکہ رسول اللہ کا فرمان ہے: من ترك الصلوة متعمدا فقد برئ من ذمة الله ورسوله جو شخص قصداً نماز ترک کر دے وہ اللہ کے ذمہ سے خارج ہو گیا۔ عہد شکنی کرنا اور قطع رحمی کرنا بھی کبیرہ گناہ ہیں، کیونکہ اللہ تعالیٰ کا حکم ہے: ﴿لهم اللعنة ولهم سوء الدار﴾ ان کے لئے لعنت ہے اور ان کے لئے برا گھر ہے۔ (الرعد ۲۵) امام بیہقی رحمۃ اللہ علیہ نے فرمایا: بہر حال دونوں میں فرق کو ترک کر دیا پس کس چیز میں ہے۔ ۲۹۲...... ہمیں خبر دی ہے ابو نصر بن قتادہ نے کہ خبر دی ہے ابو عمرو بن نجید نے کہ خبر دی ہے ابو مسلم الجی نے کہ خبر دی ہے عبدالرحمن بن حماد شعیشی نے کہ خبر دی ہے ابن عون نے محمد سے، اس نے سیدنا ابن عباس رضی اللہ عنہ سے، انہوں نے فرمایا: كل ما نهى الله عنه كبيرة ہر وہ کام ہے جس سے اللہ نے روکا ہے وہ کبیرہ گناہ ہے۔ اسی طرح فرمایا اور یحییٰ بن عتیق نے اور ہشام نے محمد بن سیرین سے، انہوں نے عباس رضی اللہ عنہ سے اسی طرح کہا ہے۔ ۲۹۳...... ہمیں خبر دی ہے ابو الحسین بشران نے کہ خبر دی ہے اسماعیل بن محمد صفار نے کہ ہمیں حدیث بیان کی ہے احمد بن منصور نے کہ ہمیں حدیث بیان کی ہے عبدالرزاق نے کہ خبر دی ہے معمر نے ایوب سے، انہوں نے ابن سیرین سے، انہوں نے عبیدہ سے کہ انہوں نے فرمایا: كل ما عصى الله ربه فهو كبيرة ہر وہ کام جس میں اللہ کی نافرمانی کی جائے وہی کبیرہ گناہ ہے۔ اور تحقیق نادر چیز ذکر کی ہے۔ اور اللہ تعالیٰ فرماتے ہیں: ﴿قل للمؤمنين يغضوا من ابصارهم﴾ (النور ۳۰) مؤمنوں سے کہہ دیجئے کہ وہ اپنی نگاہیں نیچی رکھیں۔ ۲۹۴...... اپنی اسناد کے ساتھ ہمیں معمر نے حدیث بیان کی ہے ابن طاؤس سے، اس نے اپنے والد سے، انہوں نے کہا کہ سیدنا ابن عزاه السيوطي في الدر المنثور (۱۴۸/۲) لابن جرير وابن المنذر وابن أبي حاتم والطبراني وابن مردويه عن ابن عباس. عزاه السيوطي في الدر المنثور (۱۴۶/۲) لعبد الرزاق وعبد بن حميد وابن جرير وابن المنذور وابن أبي حاتم والمصنف من طرق عن ابن عباس."}],[274,"ہمیں خبر دی ہے ابو طاہر فقیہ نے کہ خبر دی ہے ابو حامد بن بلال نے کہ ہمیں حدیث بیان کی ہے یحییٰ بن ربیع مکی نے کہ ہمیں حدیث بیان کی ہے سفیان نے زہری سے، انہوں نے ابو ادریس سے، انہوں نے عبادہ بن صامت سے کہ رسول اللہ صلی اللہ علیہ وسلم نے عورتوں کی بیعت کے بارے میں صحابہ کرام رضی اللہ عنہم سے فرمایا تھا: میرے ساتھ تم لوگ اس بات پر بیعت کرو کہ تم اللہ کے ساتھ شریک نہیں کرو گے، چوری نہیں کرو گے، بدکاری نہیں کرو گے۔ یعنی پوری آیت بیعت والی باتوں کا ذکر فرمایا۔ (پھر فرمایا کہ) جو شخص تم میں سے ساری باتیں پوری کرے گا اس کا اجر اللہ تعالیٰ کے ذمے ہو گا اور جو شخص ان باتوں میں سے کسی چیز کا ارتکاب کر بیٹھا اور اس کو سزا دے دی گئی وہ سزا اس کے لئے کفارہ ہو گی اور جس نے کسی کام کا ارتکاب کیا اور اللہ تعالیٰ نے اس پر پردہ ڈال دیا (یعنی اس کا گناہ سامنے نہ آ سکا) وہ اللہ عزوجل کے حوالے ہو گا۔ اگر وہ چاہے گا معاف کر دے گا اور چاہے گا تو اس کو عذاب دے گا۔\nبخاری اور مسلم نے اپنی اپنی صحیح میں اس حدیث کو سفیان بن عیینہ کی روایت سے نقل کیا ہے۔\nامام بیہقی رحمۃ اللہ علیہ کا قول:\nامام بیہقی نے فرمایا: عبادہ بن صامت کا قول فی بیعتہ النساء سے انہوں نے یہ مراد لی ہے کہ جیسے عورتوں کی بیعت میں ہے اور وہ اللہ تعالیٰ کا یہ فرمان ہے:\n﴿ يا ايها النبي اذا جاءك المؤمنات يبايعنك على ان لا يشركن بالله شيئا ولا يسرقن ولا يزنين ولا يقتلن اولادهن ولا ياتين ببهتان يفترينه بين ايديهن وارجلهن ولا يعصينك في معروف الخ ﴾ [۱۲]\n’’اے نبی جب تیرے پاس ایمان والی عورتیں تیرے ساتھ بیعت ہونے کے لئے آئیں تو (ان شرائط پر ان کی بیعت قبول کر لیجئے) کہ:‘‘\nوہ لوگ جو اللہ تعالیٰ کے ساتھ کسی دوسرے الہ کو نہیں پکڑتے۔ (یعنی شرک کی نفی کی ہے)\nلہذا آیت میں یہ فقرہ:\n﴿ومن يفعل ذالك يلق اثاما﴾\n’’جو شخص یہ کام کرے گا وہ ملے گا کئی کئی گناہوں کو بھرے گا۔‘‘\nاور رجوع کرے گا ان تمام سابقہ چیزوں کی طرف جو پہلے مذکور ہوئی ہیں۔ جس نے ان کبائر اور اس وعید کے اور اس پر جو دلیل دلالت کرتی ہے وہ یہ قول ہے:\n﴿يضاعف له العذاب﴾\n’’کہ اس کے لئے دہرا عذاب ہے۔‘‘\nکے درمیان جمع کیا ہے اس نے یہ ارادہ کیا ہے۔ وہ شخص جس نے شرک اور اس کے علاوہ کبائر کے مابین جمع کیا ہے۔ اس پر جمع کر دیئے ہیں شرک کے عذاب کے ساتھ کبائر کے عذاب، لہذا اس پر عذاب دہرا ہو گیا ہے۔ پھر فرمایا:\n﴿الا من تاب وامن وعمل عملا صالحا﴾\n’’مگر جو شخص ایمان لایا اور نیک عمل کئے۔‘‘\nتو یہ ایمان اور عمل صالح کا ذکر کیا ہے اور یہ اس لئے تاکہ اس کا ایمان اس کے کفر کو تباہ کر دے اور ختم کر دے اور ایمان میں اس کی اصلاح اس کو تباہ کر دے جو پہلے سے کفر میں اس سے خرابی ہوئی جیسے ہم نے اس میں نبی کریم صلی اللہ علیہ وسلم سے روایت کیا ہے۔ اگر یہ اعتراض کیا جائے کہ اللہ تعالیٰ نے یہ بھی فرمایا ہے:\n﴿ ومن يقتل مؤمنا متعمدا فجزاؤه جهنم خالدا فيها ﴾ [النساء ۹۳]\n’’جو شخص کسی مؤمن کو قتل کرے گا اس کی جزا جہنم ہے وہ اس میں ہمیشہ رہے گا۔‘‘\n(جواب میں) کہا جائے گا کہ اہل تفسیر اس طرف گئے ہیں کہ یہ آیت اس شخص کے بارے میں نازل ہوئی تھی جس نے قتل کیا تھا اور مرتد ہو گیا تھا اسلام سے اور ہمارے بعض اصحاب اس طرف گئے ہیں کہ یہ آیت اپنے سبب یا شان نزول پر بند ہے۔ (1)","",{"k":"(1) عزاه السيوطي في الدر المنثور (۱۴۶/۲) لعبد بن حميد وابن جرير وابن المنذر والطبراني والمصنف من طرق عن ابن عباس. أخرجه البخاري (۸۳/۱۲ فتح) و مسلم (۱۳۳۳/۳) من طريق ابن عيينة به. اللہ کے ساتھ کسی شے کو شریک نہیں کریں گے۔ چوری نہیں کریں گی۔ زنا نہیں کریں گی۔ اپنی اولاد کو قتل نہیں کریں گی۔ اور بہتان نہیں باندھیں گی، جیسے وہ اپنے ہاتھوں اور پیروں کے آگے اختراع کریں۔ اور ہر اچھے کام میں تیری نافرمانی نہیں کریں گی۔ اور گزشتہ حدیث میں حضور صلی اللہ علیہ وسلم کا یہ قول کرنا: ومن اصاب من ذالك شيئا فستره الله عليه کہ جو شخص ان مذکورہ گناہوں میں سے کسی گناہ کا ارتکاب کرے اور اللہ تعالیٰ اس کے اوپر پردہ ڈال دے۔ حضور صلی اللہ علیہ وسلم کی مراد اس سے شریک کے ماسوا باقی گناہ ہے۔ جیسے آپ کا یہ قول کرنا (فعوقب بہ) یعنی جس نے مذکورہ گناہوں میں سے کسی کا ارتکاب کیا اور اس کو سزا دی گئی۔ اس سے مراد بھی ماسوائے شرک کے گناہ مراد ہے۔ جبھی تو سزا اور حد کو کفارہ قرار دے دیا۔ اس غلطی کا اور گناہ شرک کے بعد جس کا ارتکاب کیا اور جس گناہ کے ارتکاب کے بعد اس میں حد جاری نہیں کی گئی اس کو اللہ کی مشیت کے سپرد کیا۔ اگر چاہے تو اس کے لئے معافی فرما دے اگر چاہے تو اس کو عذاب دے۔ پھر عذاب دائی نہیں ہو گا۔ اس بات کی دلیل شفاعت قبول کر کے جنت میں بھیجنے والی احادیث میں اور وہ آیات ہیں جو کتاب اللہ میں اس معنی میں آئی ہیں۔ اگر یہ اعتراض کیا جائے کہ آیت مغفرت میں یہ فقرہ کہ جس کو چاہے بخش دے گا مطلب یہ ہے کہ اس شخص کے صغیرہ گناہ معاف کر دے گا جو کبیرہ گناہوں سے اجتناب کرنے والا ہو گا اور اس کے لئے بخشش نہیں کرے گا جو کبائر کا ارتکاب کرنے والا ہو گا جیسے کہ دوسری آیت میں ارشاد ہے: ﴿ان تجتنبوا كبائر ما تنهون عنه نكفر عنكم سيئاتكم وندخلكم مدخلا كريما﴾ (النساء ۳۱) ’’اگر تم کبیرہ گناہوں سے اجتناب کرو گے جس سے تم منع کئے گئے ہو تو مٹا دیں گے ہم تم سے تمہاری غلطیاں اور داخل کریں ہم تم کو باعزت مقام میں۔‘‘ تو جواب میں کہا جائے گا کہ وہ کبائر جن سے اجتناب کرنے کو مغفرت کے لئے شرط قرار دیا گیا ہے اس سے مراد شرک ہے اور یہ اس آیت میں مطلق ہے اور اس کے ساتھ سیئات کی تکفیر کرنا اور مٹانا بھی مطلق ہے اور وہ دونوں اس آیت میں جس کے ساتھ ہم نے حجت پکڑی ہے دونوں جگہ دونوں مفید ہیں۔ لہذا دونوں کے مابین جمع کرنا واجب ہے اور مطلق کو مقید پر محمول کرنا۔ اگر یہ اعتراض کیا جائے کہ اللہ تعالیٰ نے کبیرہ گناہوں کے ارتکاب کرنے والوں کو آگ کی اور اس میں ہمیشہ رہنے کی وعید اور دھمکی دی ہے اور ان سے توبہ کرنے والوں کے سوا کسی کو علیحدہ نہیں کیا۔ چنانچہ ارشاد فرمایا: ﴿ولا تقتلوا النفس التي حرم الله الا بالحق (تا) الا من تاب﴾ (الفرقان ۶۸ تا ۷۰) ’’نہ قتل کرو کسی نفس کو جس کو اللہ نے حرام کیا ہے مگر حق کی تائید کے ساتھ۔‘‘ (یہاں تک کہ فرمایا) مگر وہ شخص جو توبہ کرے تو جواب میں کہا جائے گا کہ اس وعید اور دھمکی کا تعلق صرف اسی سے نہیں بلکہ تمام ان امور سے اور اشیاء سے ہے جن کا پہلے ذکر ہو چکا ہے اور اللہ تعالیٰ نے اس آیت کی ابتداء شرک کے ذکر کے ساتھ کیا ہے۔ چنانچہ ارشاد ہوا: ﴿والذين لا يدعون مع الله الها اخر﴾ (الفرقان ۶۸)"}],[275,"ہمیں خبر دی ہے ابو عبد الرحمن بن محبوب دحان نے ہمیں حدیث بیان کی ہے حسین بن ہارون نے کہ ہمیں حدیث بیان کی ہے احمد بن محمد بن نصر نے کہ ہمیں حدیث بیان کی ہے یوسف بن بلال نے کہ ہمیں حدیث بیان کی ہے محمد بن مروان نے کہ مجھے حدیث بیان کی ہے کلبی نے ابو صالح سے انہوں نے ابن عباس رضی اللہ عنہ سے، انہوں نے فرمایا مقیس بن ضبابہ نے اپنے بھائی ہشام بن ضبابہ کو بنی نجار کے محلہ میں مقتول پایا جبکہ ہشام مسلمان تھا۔ مقیس حضور صلی اللہ علیہ وسلم کی خدمت میں حاضر ہوا۔ آپ کی خدمت میں اس بات کا تذکرہ کیا۔ آپ صلی اللہ علیہ وسلم نے بنی فہر کے ایک آدمی کو نمائندہ بنا کر بھیجا اور اس کو فرمایا کہ تم بنی نجار کے پاس جاؤ اور جا کر میرا سلام کہو اور ان سے کہو کہ رسول اللہ صلی اللہ علیہ وسلم تمہیں حکم دیتے ہیں کہ اگر تم ہشام کے قاتل کو جانتے ہو تو اس کے بھائی کو ہشام کا قاتل حوالے کر دو کہ وہ اس سے (بدلہ) قصاص لے گا۔ اور اگر تم نہیں جانتے تو تم لوگ اس قتل کی دیت اس کے حوالے کرو۔\nچنانچہ فہری نے رسول اللہ صلی اللہ علیہ وسلم کی طرف سے اس کو یہ پیغام پہنچایا۔ بنی نجار والوں نے کہا سمع اور طاعت ہے اللہ کے لئے اور اس کے رسول کے لئے۔ (یعنی ہم یہی کچھ کریں گے جو آپ نے فرمایا ہے) اللہ کی قسم ہم ہشام کے قاتل کو نہیں جانتے، لیکن ہم اس کے بھائی کو دیت دیں گے۔ ابن عباس رضی اللہ عنہ نے فرمایا کہ انہوں نے مقیس کو سو اونٹ دیئے۔ پھر وہ فہری اور مقیس وہاں سے اٹھے اور مدینے کی طرف چلے۔\nجب مدینے کے قریب پہنچے تو مقیس بن ضبابہ کے پاس شیطان آیا اور اس نے مقیس کے دل میں وسوسہ ڈالا اور کہا کہ کیا کیا تم نے؟ تم نے اپنے بھائی کی دیت (اس کا خون بہا) قبول کر لیا۔ یہ تو تیرے اوپر گالی ہو گی۔ ایسا کر کہ تیرے ساتھ جو آدمی ہے اس کو قتل کر دے۔ اپنے نفس کا بدلہ نفس ہو جائے گا اور دیت بھی اضافی طور پر بچے گی۔ لہذا اس نے پتھر اٹھایا اور فہری کو دے مارا اور اس کا سر کچل دیا۔ پھر وہاں سے اونٹ ہانک کر مکہ کی طرف کافر ہو کر روانہ ہو گیا اور اپنے شعروں میں یہ کہنے لگا:\nمیں نے اپنے بھائی کے بدلے فہری کو قتل کر دیا اور میں نے اس کا خون بہا بنو نجار کے ارباب شوریٰ کی پیٹھ پر لا دیا۔ اور میں نے اپنے بھائی کا قصاص بھی پا لیا اور تکیہ لگا کر لیٹ گیا ہوں اور میں پہلا شخص ہوں جو بتوں کی طرف لوٹ گیا ہوں۔\nسیدنا ابن عباس رضی اللہ عنہ نے فرمایا کہ یہ آیت اس واقعہ میں اسی مقیس کے بارے میں نازل ہوئی تھی۔\n﴿ ومن يقتل مؤمنا متعمد فجزاؤه جهنم الخ ﴾ [النساء ۹۳]\n’’جو شخص کسی مؤمن کو جان بوجھ کر قتل کرے اس کی جزا جہنم ہے۔‘‘\nامام بیہقی رحمۃ اللہ علیہ کا قول:\nامام بیہقی رحمۃ اللہ علیہ نے فرمایا کہ ایک دوسرا جواب بھی ہے، وہ وہ ہے جو ہم نے روایت کیا ہے ابو مجلز لاحق بن حمید سے اور وہ بڑے بڑے تابعین میں سے تھے۔ انہوں نے اس آیت کے بارے میں فرمایا کہ یہ اس کی جزا ہے۔ اگر اللہ چاہے گا کہ اس کی جزا سے درگذر کرے تو وہ خود کرے گا۔\n۲۹۷...... ہمیں اس کی خبر دی ہے ابو علی حسین بن محمد روذباری نے کہ خبر دی ہے محمد بن بکر نے کہ ہمیں حدیث بیان کی ہے ابو داؤد نے کہ ہمیں حدیث بیان کی ہے احمد بن یونس نے کہ ہمیں حدیث بیان کی ہے ابو شہاب نے سلیمان تیمی سے، انہوں نے ابو مجلز لاحق بن حمید سے، پھر اس نے اس بات کو ذکر کیا ہے اور یہی نبی کریم صلی اللہ علیہ وسلم سے بھی مروی ہے۔ لیکن اس کی اسناد ثابت نہیں ہے۔\nامام بیہقی رحمۃ اللہ علیہ کا قول:\nامام بیہقی رحمۃ اللہ علیہ نے فرمایا کہ مجھے یہ خبر پہنچی ہے ابو سلیمان خطابی بستی رحمۃ اللہ علیہ سے کہ انہوں نے فرمایا تھا کہ: پورا قرآن مجید بمنزلہ ایک کلمہ کے ہے۔ جس کا نزول پہلے ہوا اور جس کا بعد میں ہوا اس پر عمل کے وجوب میں سب برابر ہے جب تک اول اور آخر میں منافات واقع نہ ہو۔ مثال کے طور پر اگر اس قول: ويغفر ما دون ذالك لمن يشاء میں اور ومن يقتل مؤمنا متعمدا فجزاؤه جهنم خالدا فيها (نساء ۹۳) میں جمع کیا جائے اور اس کے ساتھ لمن يشاء کو لاحق کیا جائے۔ یہ باہم متناقض و مخالف نہیں ہو گا۔ مشیت کی شرط قائم ہے سب کے سب گناہوں میں ماسوائے شرک کے اور اسی طرح ہے یہ بھی فجزاؤه جهنم واحتمال رکھتا ہے کہ اس کا معنی یہ ہو فجزاؤه جهنم اس کی جزا جہنم ہے۔ اگر اللہ اس کو جزا دینے پر آئے اور اس کو معاف نہ کرے تو اس طرح پہلی آیت خبر ہے اس میں کوئی خلاف نہیں ہے اور دوسری آیت وعدہ ہے جس میں عفو و درگذر کی امید ہے۔ واللہ اعلم۔"],[276,"ہمیں خبر دی ہے ابو سعد مالینی نے کہ خبر دی ہے ابو احمد بن عدی حافظ نے، انہوں نے کہا میں نے سنا عمر بن محمد وکیل سے، وہ کہتے ہیں مجھے حدیث بیان کی ہے معاذ بن مثنیٰ نے کہ ہمیں حدیث بیان کی ہے سوار بن عبداللہ نے کہ ہمیں حدیث بیان کی ہے اصمعی نے، انہوں نے کہا کہ عمرو بن عبید ابو عمرو بن ابی العلا کے پاس آئے اور ان سے کہا اے ابو عمرو! کیا اللہ اپنے وعدے کے خلاف کرتا ہے؟ انہوں نے جواب دیا کہ اللہ تعالیٰ اپنے وعدے کے خلاف ہرگز نہیں کرتا۔ عمرو نے کہا اللہ نے خود فرمایا۔ انہوں نے پوچھا، کیا فرمایا ہے؟ انہوں نے وعید کی کوئی آیت ذکر کی جو عمرو کو یاد نہیں رہی تو ابو عمرو نے کہا کونسی عجمیت تو دیا گیا ہے۔ وعد، ایعاد سے مختلف ہوتا ہے۔ پھر ابو عمرو نے شعر کہا:\nواني وان اوعدته او وعدته ساخلف ايعادي وانجز موعدي\nاور بے شک میں نے اگرچہ دھمکی دی ہے اس کو یا وعدہ دیا ہے۔ بہت جلدی میں اپنی دھمکی کے خلاف کروں گا اور پورا کروں گا میں اپنا وعدہ۔\nامام بیہقی رحمۃ اللہ علیہ نے فرمایا کہ:\nاگر یہ اعتراض کیا جائے کہ اللہ سبحانہ و تعالیٰ نے فرمایا ہے:\n﴿ ومن يعص الله ورسوله ويتعد حدوده يدخله نارا خالدا فيها ﴾ [النساء ۱۴]\n’’جو شخص اللہ اور اس کے رسول صلی اللہ علیہ وسلم کی نافرمانی کرے اور اللہ کی حدود سے تجاوز کرے اس کو اللہ تعالیٰ آگ میں داخل کرے گا اور وہ اس میں ہمیشہ رہے گا۔‘‘\n(اس سے تو معلوم ہوتا ہے کہ مؤمن گناہگار ہمیشہ جہنم میں رہے گا؟)\nکہا گیا ہے کہ اس طرح ہم کہیں گے۔ الحدود اسم جمع ہے متعدی ہوتا اللہ کی حدود کے لئے جمع بنایا گیا ہے بوجہ ترک ایمان کے اور تارک ایمان ہمیشہ آگ میں رکھا جائے گا۔ اگر اعتراض کیا جائے کہ اللہ تعالیٰ نے یہ بھی فرمایا ہے:\n﴿ وان الفجار لفي جحيم يصلونها يوم الدين وما هم عنها بغائبين ﴾ [انفطار ۱۴-۱۶]\n’’بے شک گناہگار البتہ جہنم میں ہوں گے۔ قیامت کے دن اس میں داخل ہوں گے اور اس سے وہ غائب نہیں ہوں گے۔‘‘\nکہا گیا ہے کہ اللہ نے فرمایا ہے:\n﴿ ان الابرار لفي نعيم ﴾ [انفطار ۱۳]\n’’بے شک نیکوکار لوگ البتہ نعمتوں میں ہوں گے۔‘‘\n(جواب ہے) کہ ایسا فاسق جو ایمان رکھتا ہو وہ اپنے ایمان کی بدولت بڑ یعنی نیک ہوتا ہے۔ اگر اعتراض کیا جائے کہ وہ مطلق بڑ اور نیک نہیں ہے۔\nجواب میں کہا جائے گا کہ اسی طرح وہ مطلق فاجر بھی نہیں ہے۔\nاگر اعتراض کیا جائے کہ اس کے فجور نے اس کے ایمان کو تباہ کر دیا ہے۔\nجواب دیا جائے گا کہ اس قول میں اور مرجیہ کے قول میں پھر کوئی فرق نہیں رہے گا جو یہ کہتے ہیں کہ اس کے ایمان نے اس کے فجور اور گناہوں کو تباہ کر دیا ہے۔ یہ بات دلالت کرتی ہے کہ اللہ تعالیٰ نے فجار سے وہ لوگ مراد لئے ہیں جن کے درمیان اور ابرار کے درمیان تقابل ہے۔ اس لئے کہ تمام نیکیوں کی سردار نیکی ایمان ہے اور تمام فجور کا سردار فجور کفر ہے اور ہمارے موقف کی صحت پر جو چیز دلالت کرتی ہے وہ اللہ تعالیٰ کے مندرجہ ذیل فرمان ہیں:\n(۲)\n﴿ لا اضيع عمل عامل منكم ﴾ [آل عمران ۱۹۵]\n’’تم میں سے کسی عمل کرنے والے کے عمل کو میں ضائع نہیں کروں گا۔‘‘\n(۳)\n﴿ ان الله لا يظلم مثقال ذرة وان تك حسنة يضاعفها ويؤت من لدنه اجرا عظيما ﴾ [النساء ۴۰]\n’’بے شک اللہ تعالیٰ نہیں ظلم کریں گے۔ ایک ذرے کی مقدار اگر نیکی ہوگی تو اس کو دگنا کر دیں گے اور اپنی طرف سے بہت بڑا اجر عطا کریں گے۔‘‘\n(۴)\n﴿ فمن يعمل مثقال ذرة خيرا يره ﴾ [الزلزلہ ۷]\n’’جو شخص ایک ذرے کی مقدار خیر کا عمل کرے گا اس کو عمل وہ دیکھ لے گا۔‘‘\n(۵)\n﴿ يوم تجد كل نفس ما عملت من خير محضرا ﴾ [آل عمران ۳۰]\n’’جس دن پالے گا ہر نفس جو کچھ اس نے خیر کا عمل کیا تھا حاضر کیا ہوا (پالے گا)۔‘‘\n(۶)\n﴿ فالذين امنوا منكم وانفقوا لهم اجر كبير ﴾ [الحدید ۷]\n’’پس جو لوگ تم میں سے ایمان لائے ہیں اور خرچ کیا ہے ان کے لئے بہت بڑا اجر ہے۔‘‘\n(۷)\n﴿ وعد الله المؤمنين والمؤمنات جنات ﴾ [التوبہ ۷۲]\n’’اللہ تعالیٰ نے ایمان والے مردوں اور ایمان والی عورتوں کے لئے باغات (بہشتوں) کا وعدہ فرمایا ہے۔‘‘\n(۸)\n﴿ هل جزاء الاحسان الا الاحسان ﴾ [الرحمن ۶۰]\n’’نیکی کا بدلہ صرف نیکی ہی ہے۔‘‘\nیہ مذکورہ آیات اور دیگر وہ سب آیات جو اس مفہوم میں وارد ہوئی ہیں، وہ سب کی سب اس بات پر دلالت کرتی ہیں کہ اللہ تعالیٰ اس شخص کا عمل ضائع نہیں فرمائیں گے جو اچھا عمل کرے گا اور سب اعمال سے احسن عمل اللہ اور اس کے رسول کے ساتھ ایمان لانا ہے۔\nجس شخص نے مؤمن کو دائمی طور پر آگ میں رکھنے کا قول کیا ہے۔ در حقیقت اس نے اس کے اعمال کے اجر کو ضائع کیا ہے اور اس کے لئے کوئی معاوضہ نہیں بنایا ہے۔ حالانکہ ہم یہ دیکھتے ہیں کہ اللہ تعالیٰ نے طاعات پر ثواب دینے کا وعدہ فرمایا ہے اور گناہوں پر عذاب کا۔ لہذا کسی کو یہ حق حاصل نہیں ہے کہ یہ کہے کہ اللہ تعالیٰ اس کے معاصی کے اعمال کو دیکھے گا اور طاعات کے عمل کو نہیں دیکھے گا۔ حالانکہ دوسرے کے اعمال طاعت ہوں یا معاصی اس نے خود کئے ہیں۔ مگر پھر دوسرے کو بھی یہ حق ہوگا کہ وہ اس کے برعکس کہے یعنی یہ کہ اللہ تعالیٰ مؤمن کی طاعات کو دیکھے گا۔ معاصی اور گناہوں کو نہیں دیکھے گا۔ مگر اس کا کہنا تو دور کی بات ہے کوئی بھی اس کا قائل موجود نہیں ہے۔ دوسرے یہ کہ ہم سب مسلمانوں کا اس بات پر اتفاق ہے اور اجماع ہے کہ طاعات کا اجر حاصل ہوگا اور طاعات کے حکم کے زوال میں ہم نے اختلاف کیا ہے۔ لہذا ہم نے جس چیز کا یقین کیا ہے بعض طاعات پر اجر کا حصول معصیت کے سبب ہے اس کا حکم نہیں اٹھ جائے گا۔\nبعض لوگوں نے عقیدہ شفاعت کو اس آیت سے استدلال کرتے ہوئے باطل قرار دیا ہے۔\n﴿ ما للظالمين من حميم ولا شفيع يطاع ﴾ [غافر ۱۸]\n’’ظالموں کے لئے نہ کوئی ولی دوست ہو گا اور نہ ہی کوئی سفارشی جس کی شفاعت قبول کی جائے گی۔‘‘\nتو اس کا جواب یہ ہے کہ (یہاں پر ظالموں سے مراد کافر ہیں۔ اس آیت کا آغاز اس بات کی شہادت دیتا ہے کیونکہ یہ آیت کافروں کے ذکر میں واقع ہے۔\nاگر ایسے لوگ اس آیت سے دلیل پکڑیں:\n﴿ ولا يشفعون الا لمن ارتضى ﴾ [الانبیاء ۲۸]\n’’(سفارشی) سفارش نہیں کریں گے مگر اس شخص کے لئے جس کے لئے اللہ تعالیٰ پسند کرے گا۔‘‘\nکہا گیا ہے کہ یہ ہماری دلیل ہے۔ اس لئے کہ فاسق بھی اپنے ایمان کے سبب مرتضیٰ اور پسندیدہ ہوتا ہے۔ (اور یہ بات بھی قرآن مجید کی آیات سے ثابت ہے) اللہ تعالیٰ کا ارشاد ہے:\n﴿ثم اورثنا الكتاب الذين اصطفينا من عباده﴾\n’’پھر ہم نے ان لوگوں کو کتاب کا وارث ٹھہرایا جن کو اپنے بندوں میں سے برگزیدہ کیا۔‘‘\nسورۃ انبیاء کی مذکورہ آیت میں ارتضیٰ فرمایا اور اس آیت یعنی فاطر میں ہے اصطفینا فرمایا۔ دونوں زبان کے لغت کے اعتبار سے ایک ہیں۔\nاس کے بعد ارشاد فرمایا:\n﴿فمنهم ظالم لنفسه﴾\n’’تو کچھ ان میں سے اپنے آپ پر ظلم کرتے ہیں۔‘‘\nیعنی مصطفین اور برگزیدہ لوگوں میں سے بعض اپنے آپ پر ظلم و زیادتی کرتے ہیں اور ظلم سے مراد وہی فسق ہے۔ اسی طرح اللہ نے یہ خبر دی ہے کہ ان میں ظالم بھی ہیں، یعنی فاسق ہیں اور اس طرح حضرت یونس علیہ السلام کے قصہ میں فرمایا کہ یونس علیہ السلام نے اپنے بارے میں کہا تھا:\n﴿ اني كنت من الظالمين ﴾ [الانبیاء ۸۷]\n’’کہ بے شک میں ظالم ہوں (قصور وار ہوں)۔‘‘\nاور ہم نے نبی کریم صلی اللہ علیہ وسلم سے کئی طریقوں سے اللہ تعالیٰ کے اس فرمان کے بارے میں روایت کی ہے:\n﴿ثم اورثنا الكتاب الذين اصطفينا﴾\n’’پھر ہم نے ان لوگوں کو کتاب کا وارث ٹھہرایا جن کو اپنے بندوں سے برگزیدہ کیا۔‘‘\nنبی کریم صلی اللہ علیہ وسلم نے فرمایا کہ وہ سب کے سب جنت میں ہوں گے۔ یہ کتاب البعث والنشور کی ساتویں جز میں اپنے شواہد سمیت مذکور ہیں۔ اور آیت الا من ارتضیٰ کی ایک توجیہ یہ کی گئی ہے کہ الا من ارتضى ان يشفعوا له ہے۔ یعنی مگر جس کے لئے اللہ تعالیٰ پسند کرے گا کہ شفاعت کرنے والے اس کے لئے شفاعت کریں۔\nاس طرح کا قول یہ بھی ہے:\n﴿ من ذا الذي يشفع عنده الا باذنه ﴾ [البقرہ ۲۵۵]\n’’کوئی ہے جو اس کے آگے سفارش کر سکے مگر اس کی اجازت کے ساتھ۔‘‘\nیعنی جس کے لئے اللہ پسند کرے گا کہ اس کے لئے سفارش کی جائے اللہ خود اجازت دیں گے۔\nشیخ حلیمی رحمۃ اللہ علیہ کا قول:\nشیخ حلیمی رحمۃ اللہ علیہ نے فرمایا کہ آیت: الا من ارتضیٰ (کی یہی مذکورہ توجیہ ہی ہے) اس کے علاوہ دوسری کسی توجیہ کا احتمال نہیں رکھتی۔\nاس لئے کہ اللہ کے ہاں برگزیدہ لوگ نہ تو کسی فرشتے کی شفاعت کے محتاج ہوتے ہیں اور نہ ہی کسی نبی کی شفاعت کے۔ (لہذا یہ بات ثابت ہوئی کہ) جو ہم نے کہا ہے وہی آیت کا معنی صحیح ہے۔ اور یہ کہنا صحیح نہیں کہ اللہ تعالیٰ یہ پسند نہیں کرتے کہ کسی کبیرہ گناہ کے مرتکب کے لئے سفارش کی جائے۔ اس لئے کہ گناہگار شفاعت کا محتاج ہوتا ہے اور اس کا ضرورت مند ہوتا ہے۔ تو جس قدر گناہگار کا گناہ بڑا ہوگا اسی قدر وہ شفاعت کا بھی زیادہ محتاج ہوگا۔ پھر یہ کیسے جائز ہو سکتا ہے اور یہ کیسے ممکن ہو سکتا ہے کہ شفاعت کے لئے اس کی شدت احتیاج اس کے درمیان اور شفاعت کے درمیان حائل ہو جائے۔ (یعنی اللہ تعالیٰ صاحب کبیرہ کے لئے شفاعت کو پسند نہ کریں اور شفاعت نہ ہو سکے) (پھر سوال ہو سکتا ہے کہ پھر تو کافر کے لئے بھی شفاعت ممکن ہونی چاہئے کیونکہ اس کا گناہ بھی بڑا ہے) تو جواب یہ ہوگا کہ شفاعت کا امتناع تو کافروں کے لئے بھی نہیں ہے۔ اس اعتبار سے کہ ان کا گناہ بڑا ہے۔ لیکن (کافر کے لئے سفارش اس لئے ممنوع ہے کہ وہ) اس ذات باری کا منکر ہے جس کی بارگاہ میں سفارش کی جائے گی یا اس لئے کہ وہ رسول کا منکر ہے جو اس کے حق میں سفارشی ہے یا اس لئے ممنوع ہے کہ اللہ تعالیٰ نے خبر دی ہے کہ وہ کافر کے حق میں کسی کی سفارش قبول نہیں کرے گا جبکہ یہ سارے معانی اہل قبلہ مرتکب کبیرہ مومن کے حق میں معدوم و مفقود ہیں۔\nپھر یہ سوال کیا جا سکتا ہے کہ قرآن مجید میں تو یہ بھی آیا ہے:\n﴿ يوم لا تملك نفس لنفس شيئا ﴾ [انفطار ۱۹]\n’’کہ اس دن کوئی نفس کسی نفس کے لئے کسی چیز کا بھی مالک نہیں ہو گا۔‘‘\nاس سے معلوم ہوتا ہے کہ کوئی شخص کسی کے حق میں سفارش نہیں کر سکے گا۔ لہذا اس آیت سے شفاعت کا امتناع ثابت ہوا؟ تو جواب یہ ہے کہ یہ آیت شفاعت کو منع نہیں کرتی۔ اس لئے کہ آیت میں تملک کا لفظ آیا ہے کہ کوئی مالک نہیں ہے۔ ملک سے بنا ہے اور ملک سے مراد ہے قوت و طاقت کے ساتھ روک دینا تو واقعی اللہ تعالیٰ کو قوت و طاقت سے کسی معاملے میں کوئی نہیں روک سکے گا۔ اس آیت کا شفاعت کے مفہوم کے ساتھ کوئی تعلق نہیں ہے) اس لئے کہ شفاعت، شفاعت کرنے والے کی طرف سے بارگاہ الہی میں انتہائی تذلل اور عاجزی پیش کرنے کا نام ہے اور اپنے آپ کو اس انتہائی اظہار عجز کے ذریعہ اس کے قائم مقام کرنا ہوتا ہے جس کے لئے سفارش کر رہا ہے۔ لہذا اس کام کے لئے سب سے زیادہ لائق اور اس کے احوال کے لحاظ سے زیادہ قیامت کے روز سے زیادہ کوئی موقع اور وقت نہیں ہو سکتا۔ تحقیق حضور محمد مصطفیٰ صلی اللہ علیہ وسلم سے شفاعت کے اثبات میں اور اہل توحید کی ایک جماعت کو جہنم سے نکالنے اور ان کو جنت میں داخل کرنے کے بارے میں اخبار صحیحہ وارد ہو چکی ہیں جو اخبار متواترہ کے قریب قریب ہیں۔ اسی طرح اللہ تعالیٰ کی طرف سے اہل کبائر کی ایک جماعت کے بارے میں جو اہل شرک نہ ہوں، مغفرت کرنا بغیر عذاب کے بطور اس کے فضل اور رحمت کے بارے میں احادیث آ چکی ہیں۔ اللہ بڑا وسعت والا ہے، کریم ہے۔\nامام بیہقی رحمۃ اللہ علیہ نے فرمایا کہ ہم نے یہ احادیث کتاب البعث والنشور میں ذکر کر دی ہیں اور ہم یہاں ان سے بعض کی طرف اشارہ کریں گے۔\nاللہ تعالیٰ نے محمد صلی اللہ علیہ وسلم کے لئے ارشاد فرمایا ہے:\n﴿ ومن الليل فتهجد به نافلة لك عسى ان يبعثك ربك مقاما محمودا ﴾ [الاسراء ۷۹]\nاور رات تہجد کی نماز ادا کر تو یہ حکم زیادہ اس کے قریب ہے کہ تیرا رب تجھے پہنچا دے مقام محمود پر۔ اور ہم نے حدیث ثابت میں روایت کیا ہے یزید الفقیر سے، انہوں نے جابر بن عبد اللہ سے جو اس بات پر دلالت کرتی ہے کہ یہ آیت شفاعت کے بارے میں ہے۔ اور اسی طرح ہم نے حذیفہ بن یمان سے اور سیدنا ابن عمر رضی اللہ عنہ اور دیگر سے بھی روایات کی ہیں۔\nہمیں خبر دی ہے ابو عبد اللہ حافظ نے کہ ہمیں حدیث بیان کی ہے ابو العباس نے کہ ہمیں حدیث بیان کی ہے عباس دوری نے کہ ہمیں حدیث بیان کی ہے محمد بن عبید نے کہ ہمیں حدیث بیان کی ہے داؤد نے اور ہمیں حدیث بیان کی ہے ابو عبد الرحمن سلمی نے کہ ہمیں حدیث بیان کی ہے میرے دادا ابو عمرو نے کہ خبر دی ہے محمد بن موسیٰ حلوانی نے کہ ہمیں حدیث بیان کی ہے عمرو بن علی نے کہ ہمیں حدیث بیان کی ہے وکیع بن جراح نے ہمیں حدیث بیان کی ہے داؤد زعافری نے اپنے باپ سے، انہوں نے سیدنا ابو ہریرہ رضی اللہ عنہ کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا:\nالمقام المحمود الشفاعة\nکہ مقام محمود شفاعت ہے۔\nاور ایک روایت میں ہے محمد بن عبید سے نبی کریم صلی اللہ علیہ وسلم سے اس آیت کے بارے میں:\nعسى ان يبعثك ربك مقاما محمودا\nقریب ہے کہ تیرا رب تجھے مقام محمود پر پہنچائے گا۔\nقال هو المقام الذي يشفع فيه لامته\nفرمایا کہ وہ مقام ہے جس میں آپ صلی اللہ علیہ وسلم اپنی امت کے لئے شفاعت فرمائیں گے۔\nہمیں خبر دی ہے ابو عبد اللہ حافظ نے کہ ہمیں حدیث بیان کی ہے ابو بکر محمد بن داؤد بن سلیمان نے۔ انہوں نے کہا ہمیں حدیث بیان کی ہے عبد اللہ بن احمد احوازی نے کہ ہمیں حدیث بیان کی ہے ابو بکر بن ابی شیبہ نے اپنی مسند میں کہ ہمیں حدیث بیان کی ہے وکیع نے ادریس اودی سے، انہوں نے اپنے باپ سے، انہوں نے ابو ہریرہ رضی اللہ عنہ سے، انہوں نے نبی کریم صلی اللہ علیہ وسلم سے کہ مقام محمود شفاعت ہے۔\nہمیں خبر دی ہے ابو عبد اللہ حافظ نے کہ میں نے سنا ابو بکر بن داؤد نے، انہوں نے کہا کہ میں نے سنا عبدان سے وہ کہتے تھے وہ یہ حدیث ہے جس کا لوگوں نے ہمارے اوپر انکار کیا ہے۔ (1)","",{"k":"(1) قال الذهبي في التجريد (۱۲۰/۲) هشام بن ضبابة الكناني الليثي أخو مقيس. أسلم ووجد قتيلا من بني النجار وقال ابن إسحاق وغيره قتل في غزوة المريسيع قتله أنصاري وظنه من العدو. والحديث عزاه السيوطي في الدر المنثور (۱۹۵/۲) للمصنف. أخرجه أبو داود (۴۲۷۶) عن أحمد بن يونس به وأخرجه المصنف في البعث (۴۵) ﴿ان لا نضيع اجر من احسن عملا﴾ (الکہف ۳۰) ’’بے شک ہم اس کا اجر ضائع نہیں کریں گے جس نے اچھا عمل کیا۔‘‘"}]])